Object.assign(window.TEM8_DICTIONARY, {"tedious":{"oxford":{"phon":"ˈtiːdiəs","pos":"adjective","senses":[{"en":"lasting or taking too long and not interesting","cn":"冗长的；啰嗦的；单调乏味的；令人厌烦的","ex":{"en":"The journey soon became tedious.","cn":"那次旅行不久就变得乏味起来。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"枯燥的;乏味的;令人生厌的","en":"If you describe something such as a job, task, or situation as tedious, you mean it is boring and rather frustrating.","ex":{"en":"Such lists are long and tedious to read.","cn":"这种表单读起来冗长乏味。"}}]},"media":{"uk":"media/uk/tedious__gb_1.mp3","us":"media/us/tedious__us_1.mp3"},"examples":[{"en":"We had to listen to the tedious details of his operation.","cn":"我们不得不听他唠叨他那次行动繁琐的细节。"},{"en":"The journey soon became tedious.","cn":"那次旅行不久就变得乏味起来。"}]},"temperatures":{"oxford":{"phon":"ˈtemprətʃə(r)","pos":"noun","senses":[{"en":"the measurement in degrees of how hot or cold a thing or place is","cn":"温度；气温"},{"en":"the measurement of how hot sb's body is","cn":"体温"}]},"media":{"uk":"media/uk/temperature__gb_1.mp3","us":"media/us/temperature__us_1.mp3"}},"temperamental":{"media":{"uk":"media/uk/temperamental__gb_1.mp3","us":"media/us/temperamental__us_1.mp3"},"oxford":{"phon":"ˌtemprəˈmentl","pos":"adjective","senses":[{"en":"tending to become angry, excited or upset easily, and to behave in an unreasonable way","cn":"喜怒无常的；容易激动的；反复无常的","lab":"usually disapproving","ex":{"en":"You never know what to expect with her. She's so temperamental.","cn":"你永远说不清她要干什么。她一时一变。"}},{"en":"connected with somebody’s nature and personality","cn":"气质的；性情的；性格的","ex":{"en":"They are firm friends in spite of temperamental differences.","cn":"他们尽管性格不同，但仍然友情甚笃。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱发脾气的;脾气乖张的;喜怒无常的","en":"If you say that someone is temperamental, you are criticizing them for not being calm or quiet by nature, but having moods that change often and suddenly.","ex":{"en":"He is very temperamental and critical.","cn":"他好使性子，还爱挑毛病。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(机器、汽车)老出问题的，易出故障的，性能不稳的","en":"If you describe something such as a machine or car as temperamental, you mean that it often does not work properly.","ex":{"en":"I first started cruising in yachts with temperamental petrol engines","cn":"我刚开始驾驶游艇航行时，艇上的汽油发动机老出毛病。"}}]},"examples":[{"en":"You never know what to expect with her. She's so temperamental.","cn":"你永远说不清她要干什么。她一时一变。"},{"en":"They are firm friends in spite of temperamental differences.","cn":"他们尽管性格不同，但仍然友情甚笃。"}]},"territory":{"media":{"uk":"media/uk/territory__gb_1.mp3","us":"media/us/territory__us_1.mp3"},"oxford":{"phon":"ˈterətri","pos":"noun","senses":[{"en":"land that is under the control of a particular country or political leader","cn":"领土；版图；领地","g":"[countable, uncountable]","ex":{"en":"enemy/disputed/foreign territory","cn":"敌方／有争议的／外国领土"}},{"en":"an area that one person, group, animal, etc. considers as their own and defends against others who try to enter it","cn":"（个人、群体、动物等占据的）领域，管区，地盘","g":"[countable, uncountable]","ex":{"en":"Blackbirds will defend their territory against intruders.","cn":"乌鸫会保护自己的地盘，不允许外来者侵入。"}},{"en":"an area of activity, especially one that is familiar/unfamiliar or somebody's particular responsibility","cn":"活动范围，领域（尤指所熟悉或不熟悉的，或某人的职责）","g":"[countable, usually singular]","ex":{"en":"This type of work is uncharted territory for us.","cn":"我们从未涉足过这类工作。"}},{"en":"an area of a town, country, etc. that somebody has responsibility for in their work or another activity","cn":"（某人负责的）地区","g":"[countable, uncountable]","ex":{"en":"Our representatives cover a very large territory.","cn":"我们的代理人负责的地区很广。"}},{"en":"a particular type of land","cn":"（某类）地区；（某种）地方","g":"[uncountable]","ex":{"en":"unexplored territory","cn":"未勘察地区"}},{"en":"a country or an area that is part of the US, Australia or Canada but is not a state or province","cn":"（美国）领地；（澳大利亚）地区；（加拿大）地区","g":"[countable]","ex":{"en":"Guam and American Samoa are US territories.","cn":"关岛和美属萨摩亚是美国的领地。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"领土;领地","en":"Territory is land which is controlled by a particular country or ruler.","ex":{"en":"The government denies that any of its territory is under rebel control.","cn":"政府否认有领土被反叛分子所控制。"}},{"pos":"N-COUNT 可数名词","cn":"属地，地区，托管地(指被别国控制的国家或地区)","en":"A territory is a country or region that is controlled by another country.","ex":{"en":"They just want to return to their families in the occupied territories","cn":"他们只是想回到在占领区的家人身边。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(知识)领域;(经验)范围","en":"You can use territory to refer to an area of knowledge or experience. virgin territory→see: ;","ex":{"en":"Following the futuristic The Handmaid's Tale, Margaret Atwood's seventh novel, Cat's Eye, returns to more familiar territory","cn":"写完了具有未来色彩的《女仆的故事》之后，玛格丽特·阿特伍德的第七部小说《猫眼》回归到了人们较熟悉的题材上。"}},{"pos":"N-VAR 可变名词","cn":"(动物的)领地，地盘","en":"An animal's territory is an area which it regards as its own and which it defends when other animals try to enter it.","ex":{"en":"The territory of a cat only remains fixed for as long as the cat dominates the area.","cn":"猫的地盘只在它占据那个地方的时候是固定不变的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(具有一定特点的)地带，地区","en":"Territory is land with a particular character.","ex":{"en":"...mountainous territory.","cn":"多山地带"}},{"pos":"PHRASE 短语","cn":"是难免的事;是必然的事","en":"If you say that something comes with the territory, you mean that you accept it as a natural result of the situation you are in.","ex":{"en":"Doing human rights work is risky business. That comes with the territory","cn":"做人权工作是要冒风险的。这是难免的。"}}]},"examples":[{"en":"She has to work late most days, but in her kind of job that goes with the territory.","cn":"她在大部分日子里都得工作到很晚，但根据她的工作性质，这是不可避免的。"},{"en":"Mating blackbirds will defend their territory against intruders.","cn":"乌鸫交配时会保护自己的地盘，不允许外来者侵入。"}]},"teamwork":{"media":{"uk":"media/uk/teamwork__gb_1.mp3","us":"media/us/teamwork__us_1.mp3"},"oxford":{"phon":"ˈtiːmwɜːk","pos":"noun","senses":[{"en":"the activity of working well together as a team","cn":"团队合作；协同工作","ex":{"en":"She stressed the importance of good teamwork.","cn":"她强调了团队合作的重要性。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"配合;合作;协作","en":"Teamwork is the ability a group of people have to work well together.","ex":{"en":"Today's complex buildings require close teamwork between the architect and the builders.","cn":"如今的建筑结构复杂，需要建筑师和施工人员密切协作。"}}]},"examples":[{"en":"She stressed the importance of good teamwork.","cn":"她强调了团队合作的重要性。"},{"en":"We want to encourage good teamwork and communication.","cn":"我们要鼓励良好的团队合作和沟通。"}]},"tempered":{"oxford":{"phon":"ˈtempə(r)","pos":"noun","senses":[{"en":"if sb has a temper , they become angry very easily","cn":"脾气；易怒的性情"},{"en":"a short period of feeling very angry","cn":"怒气；火气；阵怒"}]}},"terriers":{"oxford":{"phon":"ˈteriə(r)","pos":"noun","senses":[{"en":"a small active dog. There are many types of terrier.","cn":"㹴（一种活泼的小狗）"}]}},"temperament":{"media":{"uk":"media/uk/temperament__gb_1.mp3","us":"media/us/temperament__us_1.mp3"},"oxford":{"phon":"ˈtemprəmənt","pos":"noun","senses":[{"en":"a person’s or an animal’s nature as shown in the way they behave or react to situations or people","cn":"（人或动物的）气质，性情，性格，禀性","g":"[countable, uncountable]","ex":{"en":"to have an artistic temperament","cn":"有艺术家的气质"}},{"en":"the fact of tending to get emotional and excited very easily and behave in an unreasonable way","cn":"易冲动；（性情）暴躁；喜怒无常","g":"[uncountable]","ex":{"en":"an actor given to displays of temperament","cn":"性情喜怒无常的演员"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"性格;性情;秉性","en":"Your temperament is your basic nature, especially as it is shown in the way that you react to situations or to other people.","ex":{"en":"His impulsive temperament regularly got him into difficulties","cn":"他容易冲动，经常因此惹麻烦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"爱发脾气;脾气乖张;喜怒无常","en":"Temperament is the tendency to behave in an uncontrolled, bad-tempered, or unreasonable way.","ex":{"en":"Mark does have a habit of allowing his temperament to get the better of him","cn":"马克的确经常由着自己的性子来。"}}]},"examples":[{"en":"She's a dreamer and a romantic by temperament.","cn":"她生性异想天开，浪漫多情。"},{"en":"an actor given to displays of temperament","cn":"性情喜怒无常的演员"}]},"te":{"oxford":{"phon":"tiː","pos":"noun","senses":[{"en":"the 7th note of a major scale","cn":"大调音阶的第 7 音"}]},"media":{"uk":"media/uk/te__gb_1.mp3","us":"media/us/te__us_1.mp3"}},"tenacity":{"media":{"uk":"media/uk/tenacity__gb_1.mp3","us":"media/us/tenacity__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坚韧;坚毅","en":"If you have tenacity, you are very determined and do not give up easily.","ex":{"en":"Talent, hard work and sheer tenacity are all crucial to career success.","cn":"事业要成功，才能、勤奋和顽强的意志都至关重要。"}}]},"examples":[{"en":"They competed with skill and tenacity.","cn":"他们竞争靠的是技术和顽强意志。"},{"en":"a tenacious religious tradition that is still practised in Shinto temples","cn":""}],"oxford":{"phon":"təˈnæsəti","pos":"noun","senses":[{"en":"the quality of not giving up something easily; the quality of being determined","cn":"坚韧：不轻易放弃的品质；被确定的质量","ex":{"en":"They competed with skill and tenacity.","cn":"他们竞争靠的是技术和顽强意志。"}}]}},"telescope":{"oxford":{"phon":"ˈtelɪskəʊp","pos":"noun","senses":[{"en":"a piece of equipment like a tube in shape, containing lenses, that you look through to make objects that are far away appear larger and nearer","cn":"望远镜","ex":{"en":"to look at the stars through a telescope","cn":"用望远镜观察星星"}},{"en":"to become shorter, or make something shorter, by sliding sections inside one another","cn":"（使）叠套缩短，叠缩","g":"[intransitive, transitive]","pos":"verb"},{"en":"to reduce something so that it happens in less time","cn":"缩短，精简，压缩（成…）","g":"[transitive]","ex":{"en":"Three episodes have been telescoped into a single programme.","cn":"三集的内容被浓缩成了一个单独的节目。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"望远镜","en":"A telescope is a long instrument shaped like a tube. It has lenses inside it that make distant things seem larger and nearer when you look through it.","ex":{"en":"It's hoped that the telescope will enable scientists to see deeper into the universe than ever before.","cn":"人们希望望远镜能使科学家看到比以往更遥远的宇宙深处。"}}]},"media":{"img":["media/ldoce/img/telescope.jpg","media/pic/binoculars_telescope.jpg"],"uk":"media/uk/telescope__gb_1.mp3","us":"media/us/telescope__us_1.mp3"},"examples":[{"en":"Three episodes have been telescoped into a single programme.","cn":"三集的内容被浓缩成了一个单独的节目。"},{"en":"to look at the stars through a telescope","cn":"用望远镜观察星星"}]},"tenses":{"oxford":{"phon":"tens","pos":"adjective","senses":[{"en":"nervous or worried, and unable to relax","cn":"神经紧张的；担心的；不能松弛的"},{"en":"in which people have strong feelings such as worry, anger, etc. that often cannot be expressed openly","cn":"令人紧张的（或焦虑的、满腹愤懑的等）"}]}},"teeth":{"collins":{"senses":[{"pos":"","cn":"","en":"Teeth is the plural of tooth."}]},"media":{"uk":"media/uk/teeth__gb_1.mp3","us":"media/us/teeth__us_1.mp3"}},"tentativeness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not definite or certain, because you may want to change things","cn":""},{"en":"done without confidence","cn":""}]},"examples":[{"en":"I passed on my tentative conclusions to the police.","cn":"","src":"ld"},{"en":"The government is taking tentative steps towards tackling the country’s economic problems.","cn":"","src":"ld"}],"media":{"uk":"media/uk/tentativeness__gb_1.mp3","us":"media/us/tentativeness__us_1.mp3"},"oxford":{"phon":"ˈtentətɪvnəs","pos":"noun","senses":[{"en":"the state of not being definite or certain because you may want to change it later","cn":"不确定的；不肯定的；暂定的","ex":{"en":"The reason for the tentativeness of these conclusions is clear.","cn":"这些结论的暂时性的原因是显而易见的。"}},{"en":"the fact of not behaving or being done with confidence","cn":"踌躇的；犹豫不定的；不果断的","ex":{"en":"He played with some uncertainty and tentativeness.","cn":"他打球时带着一些不确定性和试探性。"}}]}},"teenager":{"media":{"uk":"media/uk/teenager__gb_1.mp3","us":"media/us/teenager__us_1.mp3"},"oxford":{"phon":"ˈtiːneɪdʒə(r)","pos":"noun","senses":[{"en":"a person who is between 13 and 19 years old","cn":"（13 至 19 岁之间的）青少年，少男，少女","ex":{"en":"a magazine aimed at teenagers","cn":"以青少年为对象的杂志"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"青少年，十几岁的人(指从 13 到 19 岁)","en":"A teenager is someone who is between thirteen and nineteen years old.","ex":{"en":"As a teenager he attended Tulse Hill Senior High School.","cn":"十几岁时，他上了塔尔斯山高中。"}}]},"examples":[{"en":"a magazine aimed at teenagers","cn":"以青少年为对象的杂志"},{"en":"a TV sex education series aimed at teenagers","cn":"一部针对青少年的性教育电视系列片"}]},"terrifying":{"media":{"uk":"media/uk/terrifying__gb_1.mp3","us":"media/us/terrifying__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吓人的;令人害怕的","en":"If something is terrifying, it makes you very frightened.","ex":{"en":"I still find it terrifying to find myself surrounded by large numbers of horses","cn":"我仍旧觉得被一大群马包围很可怕。"}}]},"examples":[{"en":"It was a terrifying experience.","cn":"那是一次可怕的经历。"}],"oxford":{"phon":"ˈterɪfaɪɪŋ","pos":"adjective","senses":[{"en":"making somebody feel extremely frightened","cn":"使恐惧；使十分害怕；使惊吓","ex":{"en":"It was a terrifying experience.","cn":"这个经历太可怕了。"}}]}},"temp":{"oxford":{"phon":"temp","pos":"noun","senses":[{"en":"a temporary employee in an office","cn":"临时雇员；临时工"},{"en":"to do a temporary job or a series of temporary jobs","cn":"打临时工；做临时工作；打零工","lab":"British English","ex":{"en":"I've been temping for an employment agency.","cn":"我一直在一家职业介绍所做临时工。"},"pos":"verb"},{"en":"temperature","cn":"温度","ex":{"en":"max temp 17°C","cn":"最高温度 17 摄氏度"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"临时雇员;临时工","en":"A temp is a person who is employed by an agency that sends them to work in different offices for short periods of time, for example to replace someone who is ill or on holiday."},{"pos":"VERB 动词","cn":"当临时雇员;打零工","en":"If someone is temping, they are working as a temp.","ex":{"en":"Like so many aspiring actresses, she ended up waiting tables and temping in office jobs","cn":"和许许多多曾经满怀抱负的女演员一样，她最后只能端端盘子，在办公室打打零工。"}}]},"media":{"uk":"media/uk/temp__gb_1.mp3","us":"media/us/temp__us_1.mp3"},"examples":[{"en":"I've been temping for an employment agency.","cn":"我一直在一家职业介绍所做临时工。"},{"en":"max temp 17 °C","cn":"最高温度 17 摄氏度"}]},"tenured":{"media":{"uk":"media/uk/tenured__gb_1.mp3","us":"media/us/tenured__us_1.mp3"},"oxford":{"phon":"ˈtenjəd","pos":"adjective","senses":[{"en":"that you can keep permanently","cn":"终身的；长期保有的","ex":{"en":"a tenured post","cn":"终身职位"}},{"en":"having the right to keep their job permanently","cn":"获终身聘用的；享有终身职位的","ex":{"en":"a tenured professor","cn":"终身教授"}}]},"examples":[{"en":"a tenured post","cn":"终身职位"},{"en":"a tenured professor","cn":"终身教授"}]},"terrapin":{"oxford":{"phon":"ˈterəpɪn","pos":"noun","senses":[{"en":"a small turtle (= a reptile with a hard round shell), that lives in warm rivers and lakes in North America","cn":"水龟（生活在北美温带江河湖泊中）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水龟","en":"A terrapin is a reptile which has a thick shell covering its body and which lives partly in water and partly on land."}]},"media":{"uk":"media/uk/terrapin__gb_1.mp3","us":"media/us/terrapin__us_1.mp3"}},"technical":{"media":{"uk":"media/uk/technical__gb_1.mp3","us":"media/us/technical__us_1.mp3"},"oxford":{"phon":"ˈteknɪkl","pos":"adjective","senses":[{"en":"connected with the practical use of machines, methods, etc. in science and industry","cn":"技术的；技能的；工艺的","g":"[usually before noun]","ex":{"en":"We offer free technical support for those buying our software.","cn":"我们向购买我们软件的顾客免费提供技术支持。"}},{"en":"connected with the skills needed for a particular job, sport, art, etc.","cn":"专门技术的；技巧的；技艺的","g":"[usually before noun]","ex":{"en":"She doesn't possess the technical ability to perform the song well.","cn":"她不具备唱好这支歌的唱功。"}},{"en":"connected with a particular subject and therefore difficult to understand if you do not know about that subject","cn":"专科的；专业的","ex":{"en":"A lot of the discussions were highly technical.","cn":"许多讨论都很专业。"}},{"en":"connected with the details of a law or set of rules","cn":"诉讼程序性的；技术性的","g":"[only before noun]","ex":{"en":"Their lawyers spent days arguing over technical details.","cn":"他们的律师花了好几天时间辩论诉讼程序细则。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"技术的;工艺的","en":"Technical means involving the sorts of machines, processes, and materials that are used in industry, transport, and communications.","ex":{"en":"In order to reach this limit a number of technical problems will have to be solved.","cn":"要达到这个限度，还有很多技术问题必须解决。"}},{"pos":"ADJ 形容词","cn":"技巧的;方法的","en":"You use technical to describe the practical skills and methods used to do an activity such as an art, a craft, or a sport.","ex":{"en":"Their technical ability is exceptional","cn":"他们技艺超群。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(语言)专业的，专门的，专用的","en":"Technical language involves using special words to describe the details of a specialized activity.","ex":{"en":"The technical term for sunburn is erythema","cn":"晒斑的专业术语叫红斑。"}}]},"examples":[{"en":"We offer free technical support for those buying our software.","cn":"我们向购买我们软件的顾客免费提供技术支持。"},{"en":"Their lawyers spent days arguing over technical details.","cn":"他们的律师花了好几天时间辩论诉讼程序细则。"}]},"terrorism":{"media":{"uk":"media/uk/terrorism__gb_1.mp3","us":"media/us/terrorism__us_1.mp3"},"oxford":{"phon":"ˈterərɪzəm","pos":"noun","senses":[{"en":"the use of violent action in order to achieve political aims or to force a government to act","cn":"恐怖主义","lab":"British English","ex":{"en":"an act of terrorism","cn":"恐怖主义行动"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恐怖主义","en":"Terrorism is the use of violence, especially murder and bombing, in order to achieve political aims or to force a government to do something."}]},"examples":[{"en":"an act of terrorism","cn":"恐怖主义行动"},{"en":"The government is doing everything possible to combat terrorism .","cn":"政府正在尽其所能打击恐怖主义。"}]},"terms":{"media":{"uk":"media/uk/terms__gb_1.mp3","us":"media/us/terms__us_1.mp3"},"oxford":{"phon":"tɜːmz","pos":"noun","senses":[{"en":"the conditions that people offer, demand or accept when they make an agreement, an arrangement or a contract","cn":"（协议、合同等的）条件，条款","ex":{"en":"peace terms","cn":"和平条件"}},{"en":"conditions that you agree to when you buy, sell, or pay for something; a price or cost","cn":"（交易的）条件；价钱；费用","ex":{"en":"to buy something on easy terms (= paying for it over a long period)","cn":"按分期付款方式购买"}},{"en":"a way of expressing yourself or of saying something","cn":"表达方式；措辞；说法","ex":{"en":"We wish to protest in the strongest possible terms (= to say we are very angry).","cn":"我们想要以最强硬的措辞抗议。"}}]},"examples":[{"en":"Under the terms of the agreement, their funding of the project will continue until 2015.","cn":"根据协议条款，他们为这个项目提供资金，将延续到 2015 年。"},{"en":"The job is great in terms of salary, but it has its disadvantages.","cn":"就薪金而言，这个工作倒是挺不错的，但也有一些不利之处。"}]},"tempt":{"oxford":{"phon":"tempt","pos":"verb","senses":[{"en":"to attract somebody or make somebody want to do or have something, even if they know it is wrong","cn":"引诱；诱惑","ex":{"en":"I was tempted by the dessert menu.","cn":"甜点菜单馋得我垂涎欲滴。"}},{"en":"to persuade or try to persuade somebody to do something that you want them to do, for example by offering them something","cn":"劝诱；鼓动；怂恿；利诱","ex":{"en":"How can we tempt young people into engineering?","cn":"我们怎么才能吸引年轻人学习工程学呢？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"引诱;诱惑;吸引","en":"Something that tempts you attracts you and makes you want it, even though it may be wrong or harmful.","ex":{"en":"Reducing the income will further impoverish these families and could tempt an offender into further crime","cn":"降低收入只会使这些家庭更加贫穷，而且可能诱使不法分子进一步犯罪。"}},{"pos":"VERB 动词","cn":"怂恿;利诱;诱惑","en":"If you tempt someone, you offer them something they want in order to encourage them to do what you want them to do.","ex":{"en":"...a million dollar marketing campaign to tempt American tourists back to Britain","cn":"耗资百万美元试图把美国游客重新吸引到英国来的营销活动"}},{"pos":"PHRASE 短语","cn":"说晦气话，玩过火，冒险（使好运结束）","en":"If someone says that something they say or do is tempting fate or is tempting providence, they mean they are worried that it may cause the good luck they have had so far to end.","ex":{"en":"As soon as you start to talk about never having played on a losing side, it is tempting fate.","cn":"你刚说从来没输过，晦气就来了。"}}]},"media":{"uk":"media/uk/tempt__gb_1.mp3","us":"media/us/tempt__us_1.mp3"},"examples":[{"en":"How can we tempt young people into engineering?","cn":"我们怎么才能吸引年轻人学习工程学呢？"},{"en":"Don't tempt thieves by leaving valuables clearly visible.","cn":"别把贵重物品放在显眼处招贼。"}]},"text":{"media":{"uk":"media/uk/text__gb_1.mp3","us":"media/us/text__us_1.mp3"},"oxford":{"phon":"tekst","pos":"noun","senses":[{"en":"any form of written material","cn":"文本；文档","g":"[uncountable]","ex":{"en":"a computer that can process text","cn":"能处理文本的电脑"}},{"en":"a piece of writing that you have to answer questions about in an exam or a lesson","cn":"（考试或一课书中赖以回答问题的）文章","g":"[countable]","ex":{"en":"Read the text carefully and then answer the questions.","cn":"先仔细阅读文章，然后再回答问题。"}},{"en":"a written message that you send using a mobile phone","cn":"（手机）短信","g":"[countable]","ex":{"en":"She sent me a text to say she would be late.","cn":"她给我发短信说会晚到。"}},{"en":"the main printed part of a book or magazine, not the notes, pictures, etc.","cn":"（书或杂志的）正文，本文（相对于附注、图片等）","g":"[uncountable]","ex":{"en":"My job is to lay out the text and graphics on the page.","cn":"我的工作是设计页面上的正文和图表。"}},{"en":"the written form of a speech, a play, an article, etc.","cn":"演讲稿；剧本；文稿","g":"[countable]","ex":{"en":"The newspaper had printed the full text of the president's speech.","cn":"报纸刊登了总统演讲的全文。"}},{"en":"a book, play, etc., especially one that is being studied","cn":"（尤指学习用的）课本，教科书，剧本","g":"[countable]","lab":"US English","ex":{"en":"a literary text","cn":"文学课本"}},{"en":"a book that teaches a particular subject and that is used especially in schools and colleges","cn":"教科书；课本；教材","g":"[countable]","lab":"North American English","ex":{"en":"medical texts","cn":"医学课本"}},{"en":"a sentence or short passage from the Bible that is read out and discussed by somebody, especially during a religious service","cn":"（尤指宗教仪式上引用的）《圣经》经文","g":"[countable]"},{"en":"to send somebody a written message using a mobile phone","cn":"（用手机）发短信","ex":{"en":"Text me when you're on your way.","cn":"路上给我发短信吧。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(书籍的)正文，文字部分","en":"The text of a book is the main part of it, rather than the introduction, pictures, or notes.","ex":{"en":"The text is precise and informative.","cn":"正文内容准确，信息量大。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"书面材料;文字材料","en":"Text is any written material.","ex":{"en":"The machine can recognise handwritten characters and turn them into printed text","cn":"这种机器能够识别手写字体，并将其转化为打印文本。"}},{"pos":"N-COUNT 可数名词","cn":"(讲演、广播、录音的)文字稿，原稿","en":"The text of a speech, broadcast, or recording is the written version of it.","ex":{"en":"A spokesman said a text of Dr Runcie's speech had been circulated to all of the bishops.","cn":"一位发言人说，朗西博士的演讲稿已经分发给所有主教了。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指科学或学术方面的)文献，文本","en":"A text is a book or other piece of writing, especially one connected with science or learning.","ex":{"en":"Her text is believed to be the oldest surviving manuscript by a female physician.","cn":"她的文献据信是现存最古老的、由女性内科医生留下的手稿。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指学校课堂使用的)课文，课文录音;(考卷上的)选文，录音材料","en":"A text is a written or spoken passage, especially one that is used in a school or university for discussion or in an examination.","ex":{"en":"I'll read the text aloud first","cn":"我先朗读一下课文。"}},{"pos":"N-COUNT 可数名词","cn":"同 text message","en":"A text is the same as a text message .","ex":{"en":"I borrowed my wife's mobile phone last week and a text arrived from another man.","cn":"我上周借我老婆的手机用，收到一个男人发来的短信。"}},{"pos":"VERB 动词","cn":"给…发送（手机）短信","en":"If you text someone, you send them a text message on a mobile phone.","ex":{"en":"Mary texted me when she got home.","cn":"玛丽到家后给我发了条短信。"}}]},"examples":[{"en":"My job is to lay out the text and graphics on the page.","cn":"我的工作是设计页面上的正文和图表。"},{"en":"Read the text carefully and then answer the questions.","cn":"先仔细阅读文章，然后再回答问题。"}]},"terrapins":{"oxford":{"phon":"ˈterəpɪn","pos":"noun","senses":[{"en":"a small turtle (= a reptile with a hard round shell), that lives in warm rivers and lakes in N America","cn":"水龟（生活在北美温带江河湖泊中）"}]}},"tens":{"oxford":{"phon":"ten","pos":"number","senses":[{"en":"10","cn":"十"},{"en":"( BrE ) ( often ironic ) used to say that sb has guessed sth correctly or done sth very well","cn":"完全正确；得满分"}]},"media":{"uk":"media/uk/ten__gb_1.mp3","us":"media/us/ten__us_1.mp3"}},"ten":{"media":{"uk":"media/uk/ten__gb_1.mp3","us":"media/us/ten__us_1.mp3"},"oxford":{"phon":"ten","pos":"number","senses":[{"en":"10","cn":"十","ex":{"en":"There are only ten of these rare animals left.","cn":"这些珍稀动物只剩下十只了。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 10","en":"Ten is the number 10. ten a penny→see: ;","ex":{"en":"Over the past ten years things have changed.","cn":"过去 10 年间，情况已发生了变化。"}}]},"examples":[{"en":"Not brilliant, Robyn, but I'll give you ten out of ten for effort.","cn":"做得不算顶好，罗宾，但要论卖力气我给你打满分。"},{"en":"Ten to one he'll be late.","cn":"十之八九他会迟到。"}]},"tell":{"media":{"uk":"media/uk/tell__gb_1.mp3","us":"media/us/tell__us_1.mp3"},"oxford":{"phon":"tel","pos":"verb","senses":[{"en":"to give information to somebody by speaking or writing","cn":"告诉；告知","g":"[transitive]","sc":"give information","ex":{"en":"He told the news to everybody he saw.","cn":"他逢人便讲这个消息。"}},{"en":"to give information about something","cn":"提供（情况）；说明；显示","g":"[transitive]","sc":"give information","ex":{"en":"The advertisement told us very little about the product.","cn":"这则广告提供的产品情况很少。"}},{"en":"to express something in words","cn":"讲述；说；表达","g":"[transitive]","sc":"express in words","ex":{"en":"to tell stories/jokes/lies","cn":"讲故事；说笑话；撒谎"}},{"en":"to let somebody know a secret","cn":"泄露（秘密）；告发","g":"[intransitive]","lab":"informal","sc":"secret","ex":{"en":"Promise you won't tell.","cn":"你要保证不往外讲。"}},{"en":"to order or advise somebody to do something","cn":"命令；指示；吩咐","g":"[transitive]","sc":"order","ex":{"en":"He was told to sit down and wait.","cn":"有人吩咐他坐下等着。"}},{"en":"to know, see or judge something correctly","cn":"知道；看出；确切地判断","g":"[intransitive, transitive]","sc":"know/judge","ex":{"en":"I think he's happy. It's hard to tell.","cn":"我想他是幸福的。这很难说。"}},{"en":"to recognize the difference between one thing or person and another","cn":"识别；分辨；区分；辨认","g":"[transitive]","sc":"distinguish","ex":{"en":"It was hard to tell the difference between the two versions.","cn":"很难分辨出这两个版本有什么区别。"}},{"en":"to have an effect on somebody/something, especially a bad one","cn":"产生效果，发生影响（尤指负面影响）","g":"[intransitive]","sc":"have effect","ex":{"en":"The strain was beginning to tell on the rescue team.","cn":"过度的疲劳开始让救援队吃不消了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"告诉;告知","en":"If you tell someone something, you give them information.","ex":{"en":"In the evening I returned to tell Phyllis our relationship was over","cn":"晚上我回来告诉菲莉丝我们之间完了。"}},{"pos":"VERB 动词","cn":"说(笑话);讲(故事);讲述(个人经历)","en":"If you tell something such as a joke, a story, or your personal experiences, you communicate it to other people using speech.","ex":{"en":"His friends say he was always quick to tell a joke","cn":"他的朋友们说，以前他讲笑话总是张嘴就来。"}},{"pos":"VERB 动词","cn":"叫;命令;吩咐;建议","en":"If you tell someone to do something, you order or advise them to do it.","ex":{"en":"A passer-by told the driver to move his car so that it was not causing an obstruction","cn":"一个过路人叫那个司机把他的车挪一挪，免得挡道。"}},{"pos":"VERB 动词","cn":"劝说，告诫，鼓舞(自己)","en":"If you tell yourself something, you put it into words in your own mind because you need to encourage or persuade yourself about something.","ex":{"en":"'Come on', she told herself","cn":"“加油！”她在心里暗暗打气。"}},{"pos":"VERB 动词","cn":"判断;断定;看出","en":"If you can tell what is happening or what is true, you are able to judge correctly what is happening or what is true.","ex":{"en":"It was already impossible to tell where the bullet had entered","cn":"已经无法判断子弹是从哪里打进来的。"}},{"pos":"VERB 动词","cn":"区分;辨别;识别","en":"If you can tell one thing from another, you are able to recognize the difference between it and other similar things.","ex":{"en":"I can't really tell the difference between their policies and ours","cn":"我真的看不出他们的政策和我们的有什么不同。"}},{"pos":"VERB 动词","cn":"说出秘密;泄密","en":"If you tell, you reveal or give away a secret.","ex":{"en":"Many of the children know who they are but are not telling.","cn":"许多孩子知道他们是谁，可就是不说。"}},{"pos":"VERB 动词","cn":"(事实、事件)表明，说明，显示","en":"If facts or events tell you something, they reveal certain information to you through ways other than speech.","ex":{"en":"The facts tell us that this is not true","cn":"事实告诉我们，这不是真的。"}},{"pos":"VERB 动词","cn":"(不快的或令人疲倦的经历)产生效果，产生影响","en":"If an unpleasant or tiring experience begins to tell, it begins to have a serious effect.","ex":{"en":"The pressure began to tell as rain closed in after 20 laps","cn":"跑完 20 圈以后，眼看就要下雨了，大家开始紧张起来。"}},{"pos":"PHRASE 短语","cn":"就…所知;据…所知","en":"You use as far as I can tell or so far as I could tell to indicate that what you are saying is based on the information you have, but that there may be things you do not know.","ex":{"en":"As far as I can tell, Jason is basically a nice guy","cn":"据我所知，贾森算得上是个好人。"}},{"pos":"CONVENTION 惯用语","cn":"(用来强调所说的话)我可以肯定/我敢说/我没法形容","en":"You can say 'I tell you', 'I can tell you', or 'I can't tell you' to add emphasis to what you are saying.","ex":{"en":"I tell you this, I will not rest until that day has come","cn":"我可以肯定地说，不到那天我不会休息。"}},{"pos":"CONVENTION 惯用语","cn":"谁也说不准;很难说","en":"If you say 'You never can tell', you mean that the future is always uncertain and it is never possible to know exactly what will happen.","ex":{"en":"You never can tell what life is going to bring you.","cn":"你永远不知道人生会给你带来些什么。"}},{"pos":"CONVENTION 惯用语","cn":"我早就告诉过你;我说的没错吧","en":"If someone disagrees with you or refuses to do what you suggest and you are eventually proved to be right, you can say 'I told you so'.","ex":{"en":"Her parents did not approve of her decision and, if she failed, her mother would say, 'I told you so.'","cn":"她父母不赞同她的决定，要是她失败了，她妈妈就会说：“怎么样，我说对了吧？”"}},{"pos":"CONVENTION 惯用语","cn":"我的建议是，听我说(用来引出建议或转换话题)","en":"You use I'll tell you what or I tell you what to introduce a suggestion or a new topic of conversation.","ex":{"en":"I tell you what, I'll bring the water in a separate glass.","cn":"要不这样吧，我用另一个玻璃杯把水端过来。"}},{"pos":"","cn":"","en":"to tell the time→see: ; time will tell→see: ;"},{"pos":"","cn":"","en":"相关词组：tell against tell apart tell off tell on"}]},"examples":[{"en":"‘I get so annoyed with Steve!’ ‘Tell me about it. He drives me crazy.’ “","cn":"史蒂夫把我烦透了！” “你算说对了。他快把我逼疯了。”"},{"en":"The kittens look exactly alike — how can you tell which is which?","cn":"这些小猫看上去一模一样，你怎么能分辨出哪只是哪只呢？"}]},"test":{"media":{"uk":"media/uk/test__gb_1.mp3","us":"media/us/test__us_1.mp3"},"oxford":{"phon":"test","pos":"noun","senses":[{"en":"an examination of somebody’s knowledge or ability, consisting of questions for them to answer or activities for them to perform","cn":"测验；考查","lab":"British English also","sc":"of knowledge/ability","ex":{"en":"an IQ/a fitness test","cn":"智商／健康测试"}},{"en":"a medical examination to discover what is wrong with you or to check the condition of your health","cn":"（医疗上的）检查，化验，检验","sc":"of health","ex":{"en":"The hospital is doing some tests.","cn":"医院正在做一些检查。"}},{"en":"an experiment to discover whether or how well something works, or to find out more information about it","cn":"试验；测试","sc":"of machine/product, etc.","ex":{"en":"the results of laboratory tests","cn":"实验室测试结果"}},{"en":"a situation or an event that shows how good, strong, etc. somebody/something is","cn":"检验；考验","sc":"of strength, etc.","ex":{"en":"The local elections will be a good test of the government's popularity.","cn":"地方选举将是检验政府是否得人心的一个很好的试金石。"}},{"en":"a cricket or rugby match played between the teams of two different countries, usually as part of a series of matches on a tour","cn":"（板球或橄榄球的）各国家队间的决赛阶段比赛","sc":"in cricket, etc.","ex":{"en":"They played well in the first Test against South Africa.","cn":"他们在对南非的第一场国际锦标赛中打得不错。"}},{"en":"to find out how much somebody knows, or what they can do by asking them questions or giving them activities to perform","cn":"测验；考查","g":"[transitive, intransitive]","sc":"knowledge/ability","ex":{"en":"Students will be tested at the end of each module.","cn":"学生将在每个模块结束时接受测试。"},"pos":"verb"},{"en":"to perform well/badly in a test of knowledge or ability","cn":"在知识或能力测试中表现不错／糟糕","g":"[intransitive]","sc":"knowledge/ability","ex":{"en":"students who tested well in reading","cn":"阅读测试考得好的学生"},"pos":"verb"},{"en":"to examine the blood, a part of the body, etc. to find out what is wrong with a person, or to check the condition of their health","cn":"试验；检查；化验","g":"[transitive]","sc":"health","ex":{"en":"to test somebody’s eyesight/hearing","cn":"检查某人的视力／听力"},"pos":"verb"},{"en":"to produce a particular result in a medical test","cn":"在医学测试中产生特定结果","g":"[intransitive]","sc":"health","ex":{"en":"She tested negative for HIV.","cn":"她的艾滋病毒检测呈阴性。"},"pos":"verb"},{"en":"to use or try a machine, substance, idea, etc. to find out how well it works or to find out more information about it","cn":"试验；检验；测试","g":"[transitive]","sc":"machine/product/theory, etc.","ex":{"en":"Test your brakes regularly.","cn":"要定期检验刹车。"},"pos":"verb"},{"en":"(of a machine or product) to perform well/badly in a test of how well it works","cn":"（机器或产品）测试结果良好／很差","g":"[intransitive]","sc":"machine/product/theory, etc.","ex":{"en":"The ad had tested badly with consumers.","cn":"测试结果表明消费者对这则广告的评价很差。"},"pos":"verb"},{"en":"to be difficult and therefore need all your strength, ability, etc.","cn":"考验；检验","g":"[transitive]","sc":"strength, etc.","ex":{"en":"The long climb tested our fitness and stamina.","cn":"那次长距离爬山是对我们健康状况和耐力的考验。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"检验;试验;测试","en":"When you test something, you try it, for example by touching it or using it for a short time, in order to find out what it is, what condition it is in, or how well it works.","ex":{"en":"Either measure the temperature with a bath thermometer or test the water with your wrist","cn":"要么用浴用温度计测量水温，要么用手腕试一下。"}},{"pos":"N-COUNT 可数名词","cn":"试验;测试;检验","en":"A test is a deliberate action or experiment to find out how well something works.","ex":{"en":"...the banning of nuclear tests.","cn":"禁止核试验"}},{"pos":"VERB 动词","cn":"对…进行测试;考核;考查","en":"If you test someone, you ask them questions or tell them to perform certain actions in order to find out how much they know about a subject or how well they are able to do something.","ex":{"en":"There was a time when each teacher spent an hour, one day a week, testing pupils in every subject","cn":"曾经，每个老师每周都有一天花上一小时对学生的每门功课进行测试。"}},{"pos":"N-COUNT 可数名词","cn":"测试(题);考试(题);考卷","en":"A test is a series of questions that you must answer or actions that you must perform in order to show how much you know about a subject or how well you are able to do something.","ex":{"en":"Out of a total of 2,602 pupils only 922 passed the test","cn":"所有 2,602 名学生中，只有 922 名通过了测试。"}},{"pos":"VERB 动词","cn":"考验;试探","en":"If you test someone, you deliberately make things difficult for them in order to see how they react.","ex":{"en":"She may be testing her mother to see how much she can take before she throws her out.","cn":"她可能在试探她妈妈，看她能忍耐到什么程度才会把她撵出家门。"}},{"pos":"N-COUNT 可数名词","cn":"考验;检验","en":"If an event or situation is a test of a person or thing, it reveals their qualities or effectiveness.","ex":{"en":"It is a commonplace fact that holidays are a major test of any relationship","cn":"度假对任何恋爱关系都是重大考验，这是常识。"}},{"pos":"VERB 动词","cn":"对…进行体检;化验;检查","en":"If you are tested for a particular disease or medical condition, you are examined or go through various procedures in order to find out whether you have that disease or condition.","ex":{"en":"My doctor wants me to be tested for diabetes","cn":"我的医生要我去做个检查，看是否患有糖尿病。"}},{"pos":"N-COUNT 可数名词","cn":"体检;(健康)检查","en":"A medical test is an examination of a part of your body in order to check that you are healthy or to find out what is wrong with you.","ex":{"en":"If necessary X-rays and blood tests will also be used to aid diagnosis","cn":"如有必要，还要进行 X 光检查和验血以帮助诊断。"}},{"pos":"N-COUNT 可数名词","cn":"(常指板球、橄榄球的)国际锦标赛","en":"A test is a sports match between two international teams, usually in cricket, rugby union, or rugby league."},{"pos":"PHRASE 短语","cn":"使经受检验;对…进行试验","en":"If you put something to the test, you find out how useful or effective it is by using it.","ex":{"en":"The Liverpool team are now putting their theory to the test","cn":"利物浦队此时正在验证他们的理论。"}},{"pos":"PHRASE 短语","cn":"测试…的强度(或稳定性)","en":"If new circumstances or events put something to the test, they put a strain on it and indicate how strong or stable it really is.","ex":{"en":"Sooner or later, life will put the relationship to the test.","cn":"总有一天，生活会考验这种关系是否牢固。"}},{"pos":"PHRASE 短语","cn":"经得住时间的考验","en":"If you say that something will stand the test of time, you mean that it is strong or effective enough to last for a very long time.","ex":{"en":"It says a lot for her culinary skills that so many of her recipes have stood the test of time.","cn":"她的许多食谱经受住了时间的考验，这充分证明了她的厨艺。"}},{"pos":"","cn":"","en":"to test the waters→see: ;"}]},"examples":[{"en":"Children are tested on core subjects at ages 7, 11 and 14.","cn":"儿童在 7、11 和 14 岁时要接受核心课程的测验。"},{"en":"I'll run a diagnostic test to see why the server keeps crashing.","cn":"我要做诊断测试，弄清为什么服务器总是不断地发生故障。"}]},"telecommuting":{"media":{"uk":"media/uk/telecommuting__gb_1.mp3","us":"media/us/telecommuting__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 teleworking","en":"Telecommuting is the same as teleworking ."}]},"oxford":{"phon":"ˌtelikəˈmjuːtɪŋ","pos":"noun","senses":[{"en":"the practice of working from home, making use of the internet, email and phone","cn":"远程办公（利用互联网、电子邮件和电话来实现）"}]}},"telephone":{"oxford":{"phon":"ˈtelɪfəʊn","pos":"noun","senses":[{"en":"a system for talking to somebody else over long distances, using wires or radio; a machine used for this","cn":"电话；电话机","g":"[countable, uncountable]","lab":"British English","ex":{"en":"The telephone rang and Pat answered it.","cn":"电话响起，帕特接了。"}},{"en":"the part of the phone that you hold in your hand and speak into","cn":"（电话机的）受话器，听筒","g":"[countable]","ex":{"en":"I picked up the telephone and called some people I knew.","cn":"我拿起电话，打给了我认识的人。"}},{"en":"to speak to somebody by phone","cn":"给某人打电话","lab":"British English","ex":{"en":"Please write or telephone for details.","cn":"欲知详情，请来信或电话联系。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电话","en":"The telephone is the electrical system of communication that you use to talk directly to someone else in a different place. You use the telephone by dialling a number on a piece of equipment and speaking into it.","ex":{"en":"They usually exchanged messages by telephone","cn":"他们一般通过电话互通消息。"}},{"pos":"N-COUNT 可数名词","cn":"电话(机)","en":"A telephone is the piece of equipment that you use when you talk to someone by telephone.","ex":{"en":"He got up and answered the telephone","cn":"他起身去接了电话。"}},{"pos":"VERB 动词","cn":"给…打电话;打电话给","en":"If you telephone someone, you dial their telephone number and speak to them by telephone.","ex":{"en":"I felt so badly I had to telephone Owen to say I was sorry","cn":"我心里实在难受，觉得必须给欧文打电话道个歉。"}},{"pos":"PHRASE 短语","cn":"正在打电话","en":"If you are on the telephone, you are speaking to someone by telephone.","ex":{"en":"Linda remained on the telephone to the police for three hours","cn":"琳达在电话里和警察谈了 3 个小时。"}},{"pos":"PHRASE 短语","cn":"装有电话","en":"To be on the telephone means to have a telephone in your house or office which is connected to the rest of the telephone system.","ex":{"en":"She wasn't on the telephone","cn":"她没装电话。"}}]},"media":{"uk":"media/uk/telephone__gb_1.mp3","us":"media/us/telephone__us_1.mp3"},"examples":[{"en":"You can telephone your order 24 hours a day.","cn":"一天 24 小时你都可以打电话订购。"},{"en":"We're not on the telephone at the cottage.","cn":"我们的乡间别墅没有安装电话。"}]},"tempted":{"oxford":{"phon":"tempt","pos":"verb","senses":[{"en":"to attract sb or make sb want to do or have sth, even if they know it is wrong","cn":"引诱；诱惑"},{"en":"to persuade or try to persuade sb to do sth that you want them to do, for example by offering them sth","cn":"劝诱；鼓动；怂恿；利诱"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"想做…的;希望做的","en":"If you say that you are tempted to do something, you mean that you would like to do it.","ex":{"en":"I'm very tempted to sell my house","cn":"我很想把我的房子卖掉。"}}]}},"temporary":{"oxford":{"phon":"ˈtemprəri","pos":"adjective","senses":[{"en":"lasting or intended to last or be used only for a short time; not permanent","cn":"短暂的；暂时的；临时的","ex":{"en":"to hire temporary workers","cn":"雇用临时工"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"暂时的;临时的;短暂的","en":"Something that is temporary lasts for only a limited time.","ex":{"en":"His job here is only temporary","cn":"他在这儿的工作只是临时的。"}}]},"media":{"uk":"media/uk/temporary__gb_1.mp3","us":"media/us/temporary__us_1.mp3"},"examples":[{"en":"We regret this service is temporarily unavailable.","cn":"我们很抱歉暂时不能提供这一服务。"},{"en":"More than half the staff are temporary.","cn":"半数以上的职员是临时雇员。"}]},"telecommunications":{"oxford":{"phon":"ˌtelikəˌmjuːnɪˈkeɪʃnz","pos":"noun","senses":[{"en":"the technology of sending signals, images and messages over long distances by radio, telephone, television, satellite , etc.","cn":"电信；电讯"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电信;电讯","en":"Telecommunications is the technology of sending signals and messages over long distances using electronic equipment, for example by radio and telephone.","ex":{"en":"...the UK telecommunications industry.","cn":"英国电信业"}}]},"media":{"uk":"media/uk/telecommunications__gb_1.mp3","us":"media/us/telecommunications__us_1.mp3"},"examples":[{"en":"technological developments in telecommunications","cn":"电信技术的发展"},{"en":"a telecommunication company","cn":"电信公司"}]},"terrier":{"oxford":{"phon":"ˈteriə(r)","pos":"noun","senses":[{"en":"a small active dog. There are many types of terrier.","cn":"梗犬（一种活泼的小型犬）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"犭更;小猎犬","en":"A terrier is a small breed of dog. There are many different types of terrier."}]},"media":{"uk":"media/uk/terrier__gb_1.mp3","us":"media/us/terrier__us_1.mp3","img":["media/ldoce/img/terrier.jpg"]}},"teenaged":{"media":{"uk":"media/uk/teenaged__gb_1.mp3","us":"media/us/teenaged__us_1.mp3"},"oxford":{"phon":"ˈtiːneɪdʒd","pos":"adjective","senses":[{"en":"between 13 and 19 years old","cn":"十几岁的（指 13 至 19 岁的）；青少年的","ex":{"en":"They have two teenaged daughters.","cn":"他们有两个十几岁的女儿。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"十几岁的，青少年的(指从13到19岁)","en":"Teenaged people are aged between thirteen and nineteen.","ex":{"en":"She is the mother of two teenaged daughters.","cn":"她有两个十几岁的女儿。"}}]},"examples":[{"en":"They have two teenaged daughters.","cn":"他们有两个十几岁的女儿。"}]},"tech":{"media":{"uk":"media/uk/tech__gb_1.mp3","us":"media/us/tech__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 technical college","en":"A tech is the same as a technical college ."}]},"examples":[{"en":"I decided to tech down and use my film camera rather than my digital camera.","cn":""}],"oxford":{"phon":"tek","pos":"noun","senses":[{"en":"scientific knowledge used in practical ways in industry, for example in designing new machines","cn":"技术；工艺；工艺技术","g":"[uncountable, countable]"},{"en":"machines or equipment designed using technology","cn":"技术性机器（或设备）","g":"[uncountable]","ex":{"en":"tech companies","cn":"科技公司"}},{"en":"technical college (a college where students can study mainly practical subjects)","cn":"工学院","g":"[countable]","lab":"British English, informal，，","ex":{"en":"He teaches at the local tech.","cn":"他在当地科技公司任教。"}},{"en":"a technician (= a person whose job is keeping a particular type of equipment or machinery in good condition)","cn":"技术员；技师","g":"[countable]","lab":"informal","ex":{"en":"She's a lab tech at the university.","cn":"她是大学的实验室技术人员。"}}]}},"team":{"media":{"uk":"media/uk/team__gb_1.mp3","us":"media/us/team__us_1.mp3"},"oxford":{"phon":"tiːm","pos":"noun","senses":[{"en":"a group of people who play a particular game or sport against another group of people","cn":"（游戏或运动的）队","lab":"British English","ex":{"en":"a football/basketball/soccer team","cn":"足球队；篮球队；足球队"}},{"en":"a group of people who work together at a particular job","cn":"（一起工作的）组，班","ex":{"en":"a team member/leader","cn":"队员；队长"}},{"en":"two or more animals that are used together to pull a cart, etc.","cn":"（同拉一辆车等的）一组牲畜，联畜"},{"en":"to put two or more things or people together in order to do something or to achieve a particular effect","cn":"使互相配合；使协作；使合作","ex":{"en":"This production of ‘Macbeth’ teams two of our finest actors.","cn":"这部《麦克白》由我们两位最优秀的演员组成。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（游戏或体育运动的）队，小组","en":"A team is a group of people who play a particular sport or game together against other similar groups of people.","ex":{"en":"The team failed to qualify for the African Nations Cup finals","cn":"该队未能闯入非洲国家杯决赛。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"团队;工作队;工作组","en":"You can refer to any group of people who work together as a team .","ex":{"en":"Each specialist consultant has a team of doctors under him","cn":"每位会诊专家手下都有一组医生。"}},{"pos":"","cn":"","en":"相关词组：team up"}]},"examples":[{"en":"A team of experts has/have been called in to investigate.","cn":"一个专家小组已应召来进行调查。"},{"en":"He was teamed with his brother in the doubles.","cn":"他被安排和哥哥搭档参加双打。"}]},"tear":{"media":{"uk":"media/uk/tear__gb_1.mp3","us":"media/us/tear__us_1.mp3"},"oxford":{"phon":"teə(r)","pos":"verb","senses":[{"en":"to damage something by pulling it apart or into pieces or by cutting it on something sharp; to become damaged in this way","cn":"撕裂；撕碎；扯破；戳破","g":"[transitive, intransitive]","sc":"damage","ex":{"en":"I tore my jeans on the fence.","cn":"我的牛仔裤被篱笆划破了。"}},{"en":"to make a hole in something by force","cn":"撕开，划成，刺出，扯开（裂口或洞）","g":"[transitive]","sc":"damage","ex":{"en":"The blast tore a hole in the wall.","cn":"墙被炸开了个洞。"}},{"en":"to remove something from something else by pulling it roughly or violently","cn":"拉掉；撕掉；拔掉；扯掉","g":"[transitive]","sc":"remove from something/somebody","ex":{"en":"The storm nearly tore the roof off.","cn":"暴风雨差一点儿把屋顶掀掉。"}},{"en":"to pull yourself/somebody away by force from somebody/something that is holding you or them","cn":"挣开；拽开；夺去；揪走","g":"[transitive]","sc":"remove from something/somebody","ex":{"en":"She tore herself from his grasp.","cn":"她挣脱了他紧紧抓着她的手。"}},{"en":"to injure a muscle, etc. by stretching it too much","cn":"拉伤；拽伤","g":"[transitive]","sc":"injure muscle","ex":{"en":"a torn ligament/muscle","cn":"拉伤的韧带／肌肉"}},{"en":"to move somewhere very quickly or in an excited way","cn":"飞跑；狂奔；疾驰","g":"[intransitive]","sc":"move quickly","ex":{"en":"He tore off down the street.","cn":"他沿大街飞奔。"}},{"en":"very badly affected or damaged by something","cn":"深受⋯之苦的；饱经⋯摧残的","sc":"-torn","ex":{"en":"to bring peace to a strife-torn country","cn":"给一个饱经变乱创伤的国家带来和平"}},{"en":"a hole that has been made in something by tearing","cn":"破洞；裂口；裂缝","ex":{"en":"This sheet has a tear in it.","cn":"这条床单上有个破洞。"},"pos":"noun"},{"en":"a drop of liquid that comes out of your eye when you cry","cn":"眼泪；泪珠；泪水","ex":{"en":"A tear rolled down his face.","cn":"一滴眼泪沿他的面颊流下来。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"眼泪;泪水;泪珠","en":"Tears are the drops of salty liquid that come out of your eyes when you are crying.","ex":{"en":"Her eyes filled with tears","cn":"她双眼噙满泪水。"}},{"pos":"N-PLURAL 复数名词","cn":"哭泣","en":"You can use tears in expressions such as in tears ,burst into tears, and close to tears to indicate that someone is crying or is almost crying.","ex":{"en":"He was in floods of tears on the phone","cn":"他在电话里失声痛哭。"}},{"pos":"See also:","cn":"","en":"blood→see: ;"},{"pos":"V-ERG 及物/不及物动词","cn":"撕开;扯坏;扯破","en":"If you tear paper, cloth, or another material, or if it tears, you pull it into two pieces or you pull it so that a hole appears in it.","ex":{"en":"She very nearly tore my overcoat","cn":"她差点把我的大衣扯破了。"}},{"pos":"N-COUNT 可数名词","cn":"(纸、布等的)破洞，窟窿","en":"A tear in paper, cloth, or another material is a hole that has been made in it.","ex":{"en":"I peered through a tear in the van's curtains.","cn":"我通过篷车帘子的破洞窥视。"}},{"pos":"VERB 动词","cn":"撕裂，撕开，划破(皮肉)","en":"If something tears your flesh or skin, it cuts it badly.","ex":{"en":"Canine teeth are for piercing and killing prey, and tearing flesh","cn":"犬齿用来咬穿、咬死猎物，还可以撕肉。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(肌肉、韧带)拉伤，撕裂","en":"If you tear one of your muscles or ligaments, or if it tears, you injure it by accidentally moving it in the wrong way.","ex":{"en":"He tore a muscle in his right thigh","cn":"他右大腿的一块肌肉拉伤了。"}},{"pos":"VERB 动词","cn":"撕掉;扯去;拔掉","en":"To tear something from somewhere means to remove it roughly and violently.","ex":{"en":"She tore the windscreen wipers from his car","cn":"她猛地扯掉他车上的雨刷。"}},{"pos":"VERB 动词","cn":"(人、动物)撕扯，撕咬","en":"If a person or animal tears at something, they pull it violently and try to break it into pieces.","ex":{"en":"Female fans fought their way past bodyguards and tore at his clothes.","cn":"女粉丝冲破保安的阻拦，撕扯他的衣裳。"}},{"pos":"VERB 动词","cn":"(常指失控或危险地)奔，冲，闯","en":"If you tear somewhere, you move there very quickly, often in an uncontrolled or dangerous way.","ex":{"en":"The door flew open and Miranda tore into the room","cn":"门猛地开了，米兰达闯进房间。"}},{"pos":"V-PASSIVE 被动动词","cn":"使饱经创伤;使经受磨难","en":"If you say that a place is torn by particular events, you mean that unpleasant events which cause suffering and division among people are happening there.","ex":{"en":"...a country that has been torn by civil war and foreign invasion since its independence.","cn":"自独立以来就饱受内战和外敌入侵之苦的国家"}},{"pos":"See also:","cn":"","en":"→see: ; to tear someone to pieces→see: ; to tear someone to shreds→see: ;"},{"pos":"","cn":"","en":"相关词组：tear apart tear away tear down tear into tear off tear up"}]},"examples":[{"en":"It tears me apart to think I might have hurt her feelings.","cn":"一想到我可能伤害了她的感情，我就感到痛心。"},{"en":"They tore into their food as if they were starving.","cn":"他们狼吞虎咽地吃起饭来，好像饿坏了似的。"}]},"technology":{"media":{"uk":"media/uk/technology__gb_1.mp3","us":"media/us/technology__us_1.mp3"},"oxford":{"phon":"tekˈnɒlədʒi","pos":"noun","senses":[{"en":"scientific knowledge used in practical ways in industry, for example in designing new machines","cn":"技术；工艺；工艺技术","g":"[uncountable, countable]","ex":{"en":"science and technology","cn":"科学技术"}},{"en":"machines or equipment designed using technology","cn":"技术性机器（或设备）","g":"[uncountable]","ex":{"en":"The scheme provides access to advanced computer technology in the classroom.","cn":"这一方案为教室配备了先进的电脑技术。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"科技;工艺;技术","en":"Technology refers to methods, systems, and devices which are the result of scientific knowledge being used for practical purposes.","ex":{"en":"Technology is changing fast","cn":"科技日新月异。"}}]},"examples":[{"en":"The company has invested in the latest technology.","cn":"这家公司已在最新技术设备方面投资。"},{"en":"to make use of the most modern technologies","cn":"利用最现代的技术"}]},"tent":{"oxford":{"phon":"tent","pos":"noun","senses":[{"en":"a shelter made of a large sheet of canvas, nylon, etc. that is supported by poles and ropes fixed to the ground, and is used especially for camping","cn":"帐篷","ex":{"en":"to put up/take down a tent","cn":"搭帐篷；拆帐篷"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"帐篷","en":"A tent is a shelter made of canvas or nylon which is held up by poles and ropes, and is used mainly by people who are camping."}]},"media":{"uk":"media/uk/tent__gb_1.mp3","us":"media/us/tent__us_1.mp3","img":["media/ldoce/img/tent.jpg"]},"examples":[{"en":"Food will be served in the hospitality tent (= for example at an outdoor show).","cn":"招待帐篷将有食物供应。"},{"en":"to put up/take down a tent","cn":"搭帐篷；拆帐篷"}]},"texture":{"media":{"uk":"media/uk/texture__gb_1.mp3","us":"media/us/texture__us_1.mp3"},"oxford":{"phon":"ˈtekstʃə(r)","pos":"noun","senses":[{"en":"the way a surface, substance or piece of cloth feels when you touch it, for example how rough, smooth, hard or soft it is","cn":"质地；手感","lab":"figurative","ex":{"en":"the soft texture of velvet","cn":"天鹅绒柔软的质地"}},{"en":"the way food or drink tastes or feels in your mouth, for example whether it is rough, smooth, light, heavy, etc.","cn":"口感","ex":{"en":"The two cheeses were very different in both taste and texture.","cn":"这两种奶酪的味道和口感大不相同。"}},{"en":"the way that different parts of a piece of music or literature are combined to create a final impression","cn":"（音乐或文学的）和谐统一感，神韵","ex":{"en":"the rich texture of the symphony","cn":"这首交响曲优美和谐的乐感"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（摸上去的）质地，质感，纹理","en":"The texture of something is the way that it feels when you touch it, for example how smooth or rough it is.","ex":{"en":"Aloe Vera is used in moisturisers to give them a wonderfully silky texture","cn":"芦荟用于润肤霜中，使之具有美妙的丝般润滑感。"}},{"pos":"N-VAR 可变名词","cn":"(尤指食品、土壤的)结构，构造","en":"The texture of something, especially food or soil, is its structure, for example whether it is light with lots of holes, or very heavy and solid.","ex":{"en":"This cheese has an open, crumbly texture with a strong flavour","cn":"这种奶酪多孔松脆，风味浓郁。"}},{"pos":"N-VAR 可变名词","cn":"(音乐、文学作品的)神韵，谐和统一（感）","en":"The texture of a piece of music or a work of literature is the impression that it makes on you as a result of the way that its different elements are combined.","ex":{"en":"The very texture of his prose bears the influence of his familiarity with drugs.","cn":"他独特的散文风韵显示出他常常在毒品的影响下进行创作的痕迹。"}}]},"examples":[{"en":"She uses a variety of different colours and textures in her wall hangings.","cn":"她悬挂的帷幔色彩和质地多姿多彩。"},{"en":"The two cheeses were very different in both taste and texture.","cn":"这两种奶酪的味道和口感大不相同。"}]},"testing":{"media":{"uk":"media/uk/testing__gb_1.mp3","us":"media/us/testing__us_1.mp3"},"oxford":{"phon":"ˈtestɪŋ","pos":"noun","senses":[{"en":"the activity of testing somebody/something in order to find something out, see if it works, etc.","cn":"试验；测试；检查","ex":{"en":"nuclear testing","cn":"核试验"}},{"en":"difficult to deal with and needing particular strength or abilities","cn":"棘手的；伤脑筋的；难应付的","ex":{"en":"This has been a testing time for us all.","cn":"对我们大家来说，这是一段难熬的时间。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题、局势)难对付的，考验人的，棘手的","en":"A testing problem or situation is very difficult to deal with and shows a lot about the character of the person who is dealing with it.","ex":{"en":"The most testing time is undoubtedly in the early months of your return to work","cn":"最考验人的时期莫过于重新回来上班的头几个月。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"检验;试验;检测","en":"Testing is the activity of testing something or someone in order to find out information.","ex":{"en":"...product testing and labelling","cn":"检验产品和给产品贴标签"}}]},"examples":[{"en":"testing and assessment in education","cn":"教育测试与评估"},{"en":"nuclear testing","cn":"核试验"}]},"teleworking":{"oxford":{"phon":"ˈteliwɜːkɪŋ","pos":"noun","senses":[{"en":"the practice of working from home, making use of the internet, email and phone","cn":"远程办公（利用互联网、电子邮件和电话来实现）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"远程工作;在家办公","en":"Teleworking is working from home using equipment such as telephones, fax machines, and modems to contact people."}]},"media":{"uk":"media/uk/teleworking__gb_1.mp3","us":"media/us/teleworking__us_1.mp3"}},"tendencies":{"oxford":{"phon":"ˈtendənsi","pos":"noun","senses":[{"en":"if sb/sth has a particular tendency , they are likely to behave or act in a particular way","cn":"倾向；偏好；性情"},{"en":"a new custom that is starting to develop","cn":"趋势；趋向"}]}},"tells":{"oxford":{"phon":"tel","pos":"verb","senses":[{"en":"to give information to sb by speaking or writing","cn":"告诉；告知"},{"en":"to give information about sth","cn":"提供（情况）；说明；显示"}]},"media":{"uk":"media/uk/tell__gb_1.mp3","us":"media/us/tell__us_1.mp3"}},"temporarily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for only a limited period of time","cn":""},{"en":"temporary – used especially about arrangements or information that people may decide to change in the future. Also used about licences or governments which are only arranged to last for a short time","cn":""}]},"examples":[{"en":"I’m living with my parents, but it’s only temporary.","cn":"","src":"ld"},{"en":"You might want to consider temporary work until you decide what you want to do.","cn":"","src":"ld"}],"media":{"uk":"media/uk/temporarily__gb_1.mp3","us":"media/us/temporarily__us_1.mp3"},"oxford":{"phon":"ˈtemprərəli","pos":"adverb","senses":[{"en":"in a way that lasts or is intended to last or be used only for a short time; in a way that is not permanent","cn":"短暂地；暂时地；临时地","ex":{"en":"We regret this service is temporarily unavailable.","cn":"很遗憾，我们暂时不提供这项服务。"}}]}},"tending":{"oxford":{"phon":"tend","pos":"verb","senses":[{"en":"to be likely to do sth or to happen in a particular way because this is what often or usually happens","cn":"往往会；常常就"},{"en":"to take a particular direction or often have a particular quality","cn":"趋向；走向；倾向；趋于"}]},"media":{"uk":"media/uk/tend__gb_1.mp3","us":"media/us/tend__us_1.mp3"}},"telegraph":{"media":{"uk":"media/uk/telegraph__gb_1.mp3","us":"media/us/telegraph__us_1.mp3"},"oxford":{"phon":"ˈtelɪɡrɑːf","pos":"noun","senses":[{"en":"a method of sending messages over long distances, using wires that carry electrical signals","cn":"电报（通信方式）","ex":{"en":"telegraph wires","cn":"电报线"}},{"en":"to send a message by telegraph","cn":"发电报；用电报发送（电文）；电告","g":"[intransitive, transitive]","pos":"verb"},{"en":"to make it clear to people what you are going to do, often without intending to","cn":"（无意中）流露（思想），泄露（动机）","g":"[transitive]","ex":{"en":"A tiny movement of her arm had telegraphed her intention to hit out.","cn":"她手臂的一个微小动作就表明了她要出击的意图。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电报(指通信系统)","en":"Telegraph is a system of sending messages over long distances, either by means of electricity or by radio signals. Telegraph was used more often before the invention of telephones."},{"pos":"VERB 动词","cn":"给…发电报;用电报发送(信息)","en":"To telegraph someone means to send them a message by telegraph.","ex":{"en":"Churchill telegraphed an urgent message to Wavell","cn":"丘吉尔给韦维尔发了封紧急电报。"}},{"pos":"VERB 动词","cn":"流露，透露(计划或意图)","en":"If someone telegraphs something that they are planning or intending to do, they make it obvious, either deliberately or accidentally, that they are going to do it.","ex":{"en":"The commission telegraphed its decision earlier this month by telling an official to prepare the order.","cn":"本月早些时候，委员会命令一位官员准备起草指令，透露了其决定。"}}]},"examples":[{"en":"Once he knew where we were, Lewis telegraphed every few hours.","cn":"一知道我们在哪里﹐刘易斯就每隔几小时发一份电报来。"},{"en":"A slight movement of the hand telegraphed his intention to shoot.","cn":"手微微一动就暴露了他想要开枪的意图。"}]},"tender":{"media":{"uk":"media/uk/tender__gb_1.mp3","us":"media/us/tender__us_1.mp3"},"oxford":{"phon":"ˈtendə(r)","pos":"adjective","senses":[{"en":"kind, gentle and loving","cn":"和善的；温柔的；亲切的；慈爱的","ex":{"en":"tender words","cn":"亲切的话语"}},{"en":"easy to bite through and cut","cn":"嫩的；柔软的","ex":{"en":"This meat is extremely tender.","cn":"这肉嫩得很。"}},{"en":"painful when you touch it","cn":"疼痛的；一触即痛的","ex":{"en":"My leg is still very tender where I banged it.","cn":"我撞到的腿还是很软。"}},{"en":"easily hurt or damaged","cn":"易损坏的；纤弱的；脆弱的","ex":{"en":"tender young plants","cn":"娇嫩的幼苗"}},{"en":"a formal offer to supply goods or do work at a stated price","cn":"投标","ex":{"en":"Cleaning services have been put out to tender (= companies have been asked to make offers to supply these services).","cn":"清洁工作已经对外招标。"},"pos":"noun"},{"en":"a truck attached to a steam engine, carrying fuel and water","cn":"（蒸汽机车的）煤水车","pos":"noun"},{"en":"a small boat, used for carrying people or goods between a larger boat and land","cn":"（在大船和口岸之间载运人或货物的）供应船，补给船，交通船","pos":"noun"},{"en":"to make a formal offer to supply goods or do work at a stated price","cn":"投标","g":"[intransitive]","ex":{"en":"Local firms were invited to tender for the building contract.","cn":"当地的公司被邀请投标承包建筑工程。"},"pos":"verb"},{"en":"to offer or give something to somebody","cn":"提议；提供；提出","g":"[transitive]","lab":"formal","ex":{"en":"He has tendered his resignation to the prime minister.","cn":"他已向首相递交辞呈。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温柔的;慈爱的;体贴的;柔软的","en":"Someone or something that is tender expresses gentle and caring feelings.","ex":{"en":"Her voice was tender, full of pity","cn":"她的声音很温柔，充满了怜爱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(年龄)幼小的，无知的","en":"If you say that someone does something at a tender age, you mean that they do it when they are still young and have not had much experience.","ex":{"en":"He had become attracted to the game at the tender age of seven.","cn":"他在7岁的小小年纪就喜欢上了这项运动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(肉等食品)软的，嫩的，易咀嚼的","en":"Meat or other food that is tender is easy to cut or chew.","ex":{"en":"Cook for a minimum of 2 hours, or until the meat is tender.","cn":"至少煮两个小时，或一直煮到肉变烂为止。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（身体部位）敏感的，疼痛的，一碰就疼的","en":"If part of your body is tender, it is sensitive and painful when it is touched.","ex":{"en":"My tummy felt very tender","cn":"我的肚子一碰就很疼。"}},{"pos":"N-VAR 可变名词","cn":"投标","en":"A tender is a formal offer to supply goods or to do a particular job, and a statement of the price that you or your company will charge. If a contract is put out to tender, formal offers are invited. If a company wins a tender, their offer is accepted.","ex":{"en":"Builders will then be sent the specifications and asked to submit a tender for the work","cn":"建筑商们将会收到说明书，并被邀请参与该项目投标。"}},{"pos":"VERB 动词","cn":"投标;参与竞标","en":"If a company tenders for something, it makes a formal offer to supply goods or do a job for a particular price.","ex":{"en":"The staff are forbidden to tender for private-sector work","cn":"工作人员不得投标承接私营部门的工作。"}},{"pos":"VERB 动词","cn":"提出;递交;呈交;缴纳","en":"If you tender something such as a suggestion, your resignation, or money, you formally offer or present it.","ex":{"en":"She quickly tendered her resignation","cn":"她很快递交了辞呈。"}}]},"examples":[{"en":"She shouldn't be having to deal with problems like this at such a tender age.","cn":"她小小年纪涉世未深，实在无须处理这样的问题。"},{"en":"Local firms were invited to tender for the building contract.","cn":"当地的公司被邀请投标承包建筑工程。"}]},"teacher":{"media":{"uk":"media/uk/teacher__gb_1.mp3","us":"media/us/teacher__us_1.mp3"},"oxford":{"phon":"ˈtiːtʃə(r)","pos":"noun","senses":[{"en":"a person whose job is teaching, especially in a school","cn":"教师；教员；老师；先生","lab":"British English","ex":{"en":"an English/a science teacher","cn":"英语／科学老师"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教师;老师;教员","en":"A teacher is a person who teaches, usually as a job at a school or similar institution.","ex":{"en":"I'm a teacher with 21 years' experience.","cn":"我是个有 21 年教龄的教师。"}}]},"examples":[{"en":"There is a growing need for qualified teachers of Business English.","cn":"对合格的商务英语教师的需求日益增长。"},{"en":"a history/science, etc. teacher","cn":"历史、理科等教师"}]},"temperate":{"media":{"uk":"media/uk/temperate__gb_1.mp3","us":"media/us/temperate__us_1.mp3"},"oxford":{"phon":"ˈtempərət","pos":"adjective","senses":[{"en":"having a mild temperature without extremes of heat or cold","cn":"气候温和的；温带的","g":"[usually before noun]","lab":"specialist","ex":{"en":"a country with a temperate climate","cn":"气候温和的国家"}},{"en":"behaving in a calm way and with control","cn":"温和的；心平气和的；自我克制的","lab":"formal"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(气候)温和的;(地区)温带的","en":"Temperate is used to describe a climate or a place which is never extremely hot or extremely cold.","ex":{"en":"The Nile Valley keeps a temperate climate throughout the year.","cn":"尼罗河流域一年四季气候温和。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)温和的，心平气和的，平心静气的","en":"If a person's behaviour is temperate, it is calm and reasonable, so that they do not get angry or lose their temper easily.","ex":{"en":"His final report to the President was far more temperate and balanced than the earlier memorandum.","cn":"和之前的备忘录相比，他递交给总统的总结报告措辞要更为温和得体。"}}]}},"teens":{"oxford":{"phon":"tiːnz","pos":"noun","senses":[{"en":"the years of a person’s life when they are between 13 and 19 years old","cn":"十几岁（13 至 19 岁之间）","ex":{"en":"She began writing poetry in her teens.","cn":"她从十几岁开始写诗。"}}]},"media":{"uk":"media/uk/teens__gb_1.mp3","us":"media/us/teens__us_1.mp3"},"examples":[{"en":"She began writing poetry in her teens.","cn":"她从十几岁开始写诗。"},{"en":"to be in your early/late teens","cn":"现年十三四/十八九岁"}]},"textual":{"media":{"uk":"media/uk/textual__gb_1.mp3","us":"media/us/textual__us_1.mp3"},"oxford":{"phon":"ˈtekstʃuəl","pos":"adjective","senses":[{"en":"connected with or contained in a text","cn":"文本的；篇章的","ex":{"en":"textual analysis","cn":"文本分析"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指文学)文本的，原文的","en":"Textual means relating to written texts, especially literary texts.","ex":{"en":"...close textual analysis of Shakespeare.","cn":"对莎士比亚作品缜密的文本分析"}}]},"examples":[{"en":"textual analysis","cn":"文本分析"},{"en":"textual errors","cn":"文本错误"}]},"tenderly":{"oxford":{"phon":"ˈtendəli","pos":"adverb","senses":[{"en":"in a kind, gentle and loving way","cn":"和善的；温柔的；亲切的；慈爱的","ex":{"en":"She kissed him tenderly.","cn":"她温柔地吻了他。"}}]},"media":{"uk":"media/uk/tenderly__gb_1.mp3","us":"media/us/tenderly__us_1.mp3"},"examples":[{"en":"Continue cooking until the meat is tender.","cn":""},{"en":"My arm is still tender where I bruised it.","cn":""}]},"telling":{"media":{"uk":"media/uk/telling__gb_1.mp3","us":"media/us/telling__us_1.mp3"},"oxford":{"phon":"ˈtelɪŋ","pos":"adjective","senses":[{"en":"having a strong or important effect; effective","cn":"强有力的；有明显效果的；显著的","ex":{"en":"a telling argument","cn":"有力的论据"}},{"en":"showing effectively what somebody/something is really like, but often without intending to","cn":"生动的；显露真实面目的，说明问题的（通常并非有意）","ex":{"en":"The number of homeless people is a telling comment on the state of society.","cn":"无家可归者的数量是社会状况的生动写照。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"讲述;叙述;报道","en":"The telling of a story or of something that has happened is the reporting of it to other people.","ex":{"en":"Herbert sat quietly through the telling of this saga","cn":"在聆听这个长篇传奇故事时，赫伯特自始至终安静地坐着。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反映本性的;显露真实情况的","en":"If something is telling, it shows the true nature of a person or situation.","ex":{"en":"It was her expression that was the most telling","cn":"她的面部表情最能反映她的真实想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(论点、批评)强有力的，有说服力的","en":"A telling argument or criticism is a very effective one.","ex":{"en":"He spoke reasonably, carefully, and with telling effect","cn":"他说起话来合乎情理，措辞谨慎，而且说服力强。"}},{"pos":"PHRASE 短语","cn":"无法预料;谁也不清楚;谁也说不准","en":"You use there's no telling to introduce a statement when you want to say that it is impossible to know what will happen in a situation.","ex":{"en":"There's no telling how long the talks could drag on","cn":"谁也说不准谈判还会拖多久。"}}]},"examples":[{"en":"The number of homeless people is a telling comment on the state of society.","cn":"无家可归者的数量是社会状况的生动写照。"},{"en":"a telling argument","cn":"有力的论据"}]},"terrain":{"media":{"uk":"media/uk/terrain__gb_1.mp3","us":"media/us/terrain__us_1.mp3"},"oxford":{"phon":"təˈreɪn","pos":"noun","senses":[{"en":"used to refer to an area of land when you are mentioning its natural features, for example, if it is rough, flat, etc.","cn":"地形；地势；地带","ex":{"en":"difficult/rough/mountainous terrain","cn":"难以通过的地带；崎岖不平的地形；山地"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"地形;地势;地带","en":"Terrain is used to refer to an area of land or a type of land when you are considering its physical features.","ex":{"en":"The terrain changed quickly from arable land to desert.","cn":"那个地带很快就从耕地变成了沙漠。"}}]},"examples":[{"en":"difficult/rough/mountainous, etc. terrain","cn":"难以通过的地带、崎岖不平的地形、山地等"},{"en":"rocky terrain","cn":"岩石地带"}]},"teach":{"media":{"uk":"media/uk/teach__gb_1.mp3","us":"media/us/teach__us_1.mp3"},"oxford":{"phon":"tiːtʃ","pos":"verb","senses":[{"en":"to give lessons to students in a school, college, university, etc.; to help somebody learn something by giving information about it","cn":"教（课程）；讲授；教授","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"She teaches at our local school.","cn":"她在我们当地的学校任教。"}},{"en":"to show somebody how to do something so that they will be able to do it themselves","cn":"教；训练","g":"[transitive]","ex":{"en":"Could you teach me to do that?","cn":"你能教我干那活儿吗？"}},{"en":"to make somebody feel or think in a different way","cn":"教育；教导；使懂得（情理）","g":"[transitive]","ex":{"en":"She taught me to be less critical of other people.","cn":"她教育我不要太苛求于人。"}},{"en":"to persuade somebody not to do something again by making them suffer so much that they are afraid to do it","cn":"使引以为戒；惩戒","g":"[transitive, no passive]","lab":"informal","ex":{"en":"Lost all your money? That'll teach you to gamble.","cn":"你把钱都输光了？这是赌博给你的教训。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"教;教会","en":"If you teach someone something, you give them instructions so that they know about it or how to do it.","ex":{"en":"The trainers have a programme to teach them vocational skills","cn":"培训师计划教他们一些职业技能。"}},{"pos":"VERB 动词","cn":"教育;教导;使学会","en":"To teach someone something means to make them think, feel, or act in a new or different way.","ex":{"en":"Their daughter's death had taught him humility","cn":"他们女儿的死使他学会了谦逊。"}},{"pos":"VERB 动词","cn":"教授;讲授;教书","en":"If you teach or teach a subject, you help students to learn about it by explaining it or showing them how to do it, usually as a job at a school, college, or university.","ex":{"en":"Ingrid is currently teaching Mathematics at Shimla Public School","cn":"英格丽德目前在希姆拉公立学校教数学。"}},{"pos":"See also:","cn":"","en":"to teach someone a lesson→see: ;"}]},"examples":[{"en":"My parents taught me that honesty was always the best policy.","cn":"我父母教导我，诚实永远是处世的最佳原则。"},{"en":"Our priority is to educate people about the dangers of drugs.","cn":"我们首先要做的是教育人们认识毒品的危险。"}]},"terror":{"media":{"uk":"media/uk/terror__gb_1.mp3","us":"media/us/terror__us_1.mp3"},"oxford":{"phon":"ˈterə(r)","pos":"noun","senses":[{"en":"a feeling of extreme fear","cn":"惊恐；恐惧；惊骇","g":"[uncountable, singular]","lab":"literary","ex":{"en":"a feeling of sheer/pure terror","cn":"胆战心惊"}},{"en":"a person, situation or thing that makes you very afraid","cn":"可怕的人；恐怖的事；可怕的情况","g":"[countable]","lab":"literary","ex":{"en":"These street gangs have become the terror of the neighbourhood.","cn":"这些街头少年团伙使得周围邻里谈之色变。"}},{"en":"violent action or the threat of violent action that is intended to cause fear, usually for political purposes","cn":"（通常出于政治目的）恐怖行动，恐怖","g":"[uncountable]","ex":{"en":"a campaign of terror","cn":"恐怖运动"}},{"en":"a person (usually a child) or an animal that causes you trouble or is difficult to control","cn":"讨厌鬼；小捣蛋","g":"[countable]","lab":"informal","ex":{"en":"Their kids are real little terrors.","cn":"他们的小孩都是十足的讨厌鬼。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恐惧;惊恐;恐慌","en":"Terror is very great fear.","ex":{"en":"I shook with terror whenever I was about to fly in an aeroplane","cn":"每次坐飞机前，我都吓得直发抖。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指有政治目的的)恐怖活动，恐怖主义","en":"Terror is violence or the threat of violence, especially when it is used for political reasons.","ex":{"en":"The bomb attack on the capital could signal the start of a pre-election terror campaign.","cn":"对首都的炸弹袭击可能标志着选举前的恐怖活动开始了。"}},{"pos":"N-COUNT 可数名词","cn":"恐怖的事物","en":"A terror is something that makes you very frightened.","ex":{"en":"As a boy, he had a real terror of facing people.","cn":"小时候，他特别害怕见人。"}},{"pos":"N-COUNT 可数名词","cn":"讨厌的小孩;淘气鬼;小捣蛋","en":"If someone describes a child as a terror, they think that he or she is naughty and difficult to control.","ex":{"en":"He was a terror. He had been a difficult child for as long as his parents could remember.","cn":"他是个淘气鬼，从小就不老实。"}},{"pos":"PHRASE 短语","cn":"完全吓不倒；让人丝毫不焦虑","en":"If something holds no terrors for you, you are not at all frightened or worried by it.","ex":{"en":"Childbirth now held fewer terrors for her than it once had.","cn":"她现在不像原来那样害怕分娩了。"}},{"pos":"","cn":"","en":"to live in terror→see: ; reign of terror→see: ;"}]},"examples":[{"en":"These street gangs have become the terror of the neighbourhood.","cn":"这些街头少年团伙使得周围邻里谈之色变。"},{"en":"Some women have a terror of losing control in the birth process.","cn":"有些妇女惧怕在分娩过程中难以自制。"}]},"teaching":{"media":{"uk":"media/uk/teaching__gb_1.mp3","us":"media/us/teaching__us_1.mp3"},"oxford":{"phon":"ˈtiːtʃɪŋ","pos":"noun","senses":[{"en":"the work of a teacher","cn":"教学；授课；指导","g":"[uncountable]","ex":{"en":"She wants to go into teaching (= make it a career).","cn":"她想从事教学工作。"}},{"en":"the ideas of a particular person or group, especially about politics, religion or society, that are taught to other people","cn":"教导；学说；教义；教诲","g":"[uncountable, countable, usually plural]","ex":{"en":"views that go against traditional Catholic teaching","cn":"与传统天主教教义相违的观点"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"教学;教书","en":"Teaching is the work that a teacher does in helping students to learn.","ex":{"en":"The Government funds university teaching.","cn":"政府为高校教学提供资金。"}},{"pos":"N-COUNT 可数名词","cn":"教义;教导;学说","en":"The teachings of a particular person, group of people, or religion are all the ideas and principles that they teach.","ex":{"en":"...the teachings of Jesus.","cn":"耶稣的教义"}}]},"examples":[{"en":"views that go against traditional Christian teaching","cn":"与传统基督教教义相违的观点"},{"en":"She wants to go into teaching (= make it a career).","cn":"她想从事教学工作。"}]},"temporal":{"media":{"uk":"media/uk/temporal__gb_1.mp3","us":"media/us/temporal__us_1.mp3"},"oxford":{"phon":"ˈtempərəl","pos":"adjective","senses":[{"en":"connected with the real physical world, not spiritual matters","cn":"世间的；世俗的；现世的","lab":"formal","ex":{"en":"Although spiritual leader of millions of people, the Pope has no temporal power.","cn":"教皇虽然是亿万人的精神领袖，但没有丝毫的世俗权力。"}},{"en":"connected with or limited by time","cn":"时间的","lab":"formal","ex":{"en":"a universe which has spatial and temporal dimensions","cn":"有时空维度的宇宙"}},{"en":"near the temple(s) at the side of the head","cn":"太阳穴的；颞的","lab":"anatomy","ex":{"en":"the right temporal lobe of the brain","cn":"大脑右颞叶"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"世俗的;俗家的;尘世的","en":"Temporal powers or matters relate to ordinary institutions and activities rather than to religious or spiritual ones.","ex":{"en":"...their spiritual and temporal leader.","cn":"他们的精神领袖兼世俗领导人"}},{"pos":"ADJ 形容词","cn":"颞部的;太阳穴的","en":"The temporal parts of your brain are the parts near the sides of your head.","ex":{"en":"...a small but important area of the temporal lobe of the brain.","cn":"大脑颞叶上虽小但很重要的一个区域"}},{"pos":"ADJ 形容词","cn":"时间的;时间方面的","en":"Temporal means relating to time.","ex":{"en":"One is also able to see how specific acts are related to a temporal and spatial context","cn":"人们也能看出具体行为是如何与时空相关联的。"}}]},"examples":[{"en":"Although spiritual leader of millions of people, the Pope has no temporal power.","cn":"教宗虽然是亿万人的精神领袖，但没有丝毫的世俗权力。"},{"en":"a universe which has spatial and temporal dimensions","cn":"有时空维度的宇宙"}]},"tempting":{"media":{"uk":"media/uk/tempting__gb_1.mp3","us":"media/us/tempting__us_1.mp3"},"oxford":{"phon":"ˈtemptɪŋ","pos":"adjective","senses":[{"en":"something that is tempting is attractive, and makes people want to have it, do it, etc.","cn":"吸引人的；诱人的；有吸引力的","ex":{"en":"It was a tempting offer.","cn":"这是个诱人的提议。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诱人的;吸引人的","en":"If something is tempting, it makes you want to do it or have it.","ex":{"en":"In the end, I turned down Raoul's tempting offer of the Palm Beach trip","cn":"最终，我回绝了拉乌尔提出的去棕榈海滩旅行的诱人邀请。"}}]},"examples":[{"en":"It's tempting to speculate about what might have happened.","cn":"大家不禁猜测，到底发生了什么事。"},{"en":"That cake looks very tempting.","cn":"那蛋糕的样子让人嘴馋。"}]},"tense":{"oxford":{"phon":"tens","pos":"adjective","senses":[{"en":"nervous or worried, and unable to relax","cn":"神经紧张的；担心的；不能松弛的","ex":{"en":"He's a very tense person.","cn":"他是个神经非常紧张的人。"}},{"en":"in which people have strong feelings such as worry, anger, etc. that often cannot be expressed openly","cn":"令人紧张的（或焦虑的、满腹愤懑的等）","ex":{"en":"I spent a tense few weeks waiting for the results of the tests.","cn":"等候测试结果的这几个星期里我寝食不安。"}},{"en":"tight rather than relaxed","cn":"绷紧的；不松弛的","ex":{"en":"A massage will relax those tense muscles.","cn":"按摩会使紧张的肌肉松弛。"}},{"en":"stretched tightly","cn":"拉紧的；绷紧的"},{"en":"produced with the muscles of the speech organs stretched tight","cn":"紧的；紧张音的","lab":"phonetics"},{"en":"any of the forms of a verb that may be used to show the time of the action or state expressed by the verb","cn":"（动词的）时，时态","ex":{"en":"the past/present/future tense","cn":"过去／现在／将来时态"},"pos":"noun"},{"en":"if you tense your muscles, or you or your muscles tense, they become tight and stiff, especially because you are not relaxed","cn":"（使肌肉）拉紧，绷紧","ex":{"en":"She tensed her muscles in anticipation of the blow.","cn":"眼看要挨打，她绷紧了肌肉。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(局势、时期)令人紧张的，让人焦虑的","en":"A tense situation or period of time is one that makes people anxious, because they do not know what is going to happen next.","ex":{"en":"This gesture of goodwill did little to improve the tense atmosphere at the talks","cn":"这一友好姿态基本上没有改善会谈的紧张气氛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张的;焦虑的;无法放松的","en":"If you are tense, you are anxious and nervous and cannot relax.","ex":{"en":"Dart, who had at first been very tense, at last relaxed.","cn":"起初，达特非常紧张，最后终于放松了下来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(肌肉)紧张的，绷紧的","en":"If your body is tense, your muscles are tight and not relaxed.","ex":{"en":"She lay, eyes shut, body tense","cn":"她躺着，双目紧闭，全身绷直。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（肌肉）紧张，绷紧","en":"If your muscles tense, if you tense, or if you tense your muscles, your muscles become tight and stiff, often because you are anxious or frightened.","ex":{"en":"Newman's stomach muscles tensed","cn":"纽曼的腹肌绷紧了。"}},{"pos":"N-COUNT 可数名词","cn":"(动词的)时，时态","en":"The tense of a verb group is its form, which usually shows whether you are referring to past, present, or future time.","ex":{"en":"It was as though Corinne was already dead: they were speaking of her in the past tense.","cn":"科琳娜好像已经去世了：他们谈论她时用的是过去时。"}},{"pos":"","cn":"","en":"相关词组：tense up"}]},"media":{"uk":"media/uk/tense__gb_1.mp3","us":"media/us/tense__us_1.mp3"},"examples":[{"en":"I spent a tense few weeks waiting for the results of the tests.","cn":"等候测试结果的这几个星期里我寝食不安。"},{"en":"He tensed himself, listening to see if anyone had followed him.","cn":"他绷紧神经，仔细听是否有人跟踪自己。"}]},"tea":{"media":{"uk":"media/uk/tea__gb_1.mp3","us":"media/us/tea__us_1.mp3","img":["media/ldoce/img/cup_tea.jpg"]},"oxford":{"phon":"tiː","pos":"noun","senses":[{"en":"the dried leaves (called tea leaves) of the tea bush","cn":"茶叶","g":"[uncountable, countable]","ex":{"en":"a packet of tea","cn":"一盒茶"}},{"en":"a hot drink made by pouring boiling water onto tea leaves. It may be drunk with milk or lemon and/or sugar added.","cn":"茶；茶水","g":"[uncountable, countable]","ex":{"en":"a cup of tea","cn":"一杯茶"}},{"en":"a cup of tea","cn":"一杯茶","g":"[countable]","ex":{"en":"Two teas, please.","cn":"请来两杯茶。"}},{"en":"a hot drink made by pouring boiling water onto the leaves of other plants","cn":"（用其他植物的叶子沏的）热饮料","g":"[uncountable, countable]","ex":{"en":"camomile/mint/herbal tea","cn":"春黄菊花茶；薄荷茶；药草茶"}},{"en":"the name used by some people in the UK for the cooked meal eaten in the evening, especially when it is eaten early in the evening","cn":"晚点，便餐（英国人傍晚时吃）","g":"[uncountable, countable]","lab":"British English","ex":{"en":"You can have your tea as soon as you come home from school.","cn":"你放学一回到家就可以吃晚点。"}},{"en":"a light meal eaten in the afternoon or early evening, usually with sandwiches and/or biscuits and cakes and with tea to drink","cn":"茶点（在下午或傍晚，通常喝茶时还有三明治、饼干和蛋糕）","g":"[uncountable, countable]","lab":"British English","ex":{"en":"Would you like to come to tea on Sunday?","cn":"星期天你过来吃茶点好吗？"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"茶;茶水","en":"Tea is a drink made by adding hot water to tea leaves or tea bags. Many people add milk to the drink and some add sugar.","ex":{"en":"...a cup of tea","cn":"一杯茶"}},{"pos":"N-MASS 物质名词","cn":"(用某些植物的叶子或花泡的)茶","en":"Drinks such as mint tea or chamomile tea are made by pouring hot water on the dried leaves of the particular plant or flower."},{"pos":"N-MASS 物质名词","cn":"茶叶","en":"The chopped dried leaves of the plant that tea is made from is referred to as tea .","ex":{"en":"...a packet of tea","cn":"一包茶叶"}},{"pos":"N-VAR 可变名词","cn":"下午茶;午后茶点","en":"Tea is a meal some people eat in the late afternoon. It consists of food such as sandwiches and cakes, with tea to drink. →see usage note at:","ex":{"en":"I'm doing the sandwiches for tea","cn":"我在做下午茶吃的三明治。"}},{"pos":"N-VAR 可变名词","cn":"（傍晚时吃的）晚点，晚餐","en":"Some people refer to the main meal that they eat in the early part of the evening as tea.","ex":{"en":"At five o'clock he comes back for his tea.","cn":"他 5 点钟回来吃晚餐。"}},{"pos":"PHRASE 短语","cn":"不感兴趣的人;不合胃口的事物","en":"If you say that someone or something is not your cup of tea, you mean that they are not the kind of person or thing that you like.","ex":{"en":"Politics was not his cup of tea","cn":"他对政治不感兴趣。"}}]},"examples":[{"en":"I wouldn't do your job. Not for all the tea in China!","cn":"我才不做你的那份工作。有天大的好处也不干！"},{"en":"You can have your tea as soon as you come home from school.","cn":"你放学一回到家就可以吃晚点。"}]},"tendency":{"oxford":{"phon":"ˈtendənsi","pos":"noun","senses":[{"en":"if somebody/something has a particular tendency, they are likely to behave or act in a particular way","cn":"倾向；偏好；性情","g":"[countable]","ex":{"en":"to display artistic tendencies","cn":"显示出对艺术的偏好"}},{"en":"a new custom that is starting to develop","cn":"趋势；趋向","g":"[countable]","ex":{"en":"There's a growing tendency for women to marry later.","cn":"女性越来越趋于晚婚。"}},{"en":"a group within a larger political group, whose views are more extreme than those of the rest of the group","cn":"（政党内的）极端派别","g":"[countable + singular or plural verb]","lab":"British English","ex":{"en":"a growing separatist tendency within the Anglo-Irish community","cn":"盎格鲁-爱尔兰社区内日益增长的分离主义倾向"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(令人焦虑或不快的)习惯，经常性行为，倾向","en":"A tendency is a worrying or unpleasant habit or action that keeps occurring.","ex":{"en":"The army has become increasingly restless over the mounting separatist tendencies of the northern republics.","cn":"军方对于北方几个共和国不断加剧的分裂倾向感到越来越不安。"}},{"pos":"N-COUNT 可数名词","cn":"(性格中不良的)倾向，偏好","en":"A tendency is a part of your character that makes you behave in an unpleasant or worrying way.","ex":{"en":"He is spoiled, arrogant and has a tendency towards snobbery","cn":"他被宠坏了，傲慢无礼，而且经常自命不凡。"}}]},"media":{"uk":"media/uk/tendency__gb_1.mp3","us":"media/us/tendency__us_1.mp3"},"examples":[{"en":"There is a growing tendency among employers to hire casual staff.","cn":"雇主雇用临时职员有增加的趋势。"},{"en":"There is a tendency for this disease to run in families.","cn":"这种疾病易在家族里遗传。"}]},"teaspoons":{"oxford":{"phon":"ˈtiːspuːn","pos":"noun","senses":[{"en":"a small spoon for putting sugar into tea and other drinks","cn":"茶匙；小匙"},{"en":"the amount a teaspoon can hold","cn":"一茶匙（的量）"}]}},"terrible":{"oxford":{"phon":"ˈterəbl","pos":"adjective","senses":[{"en":"very unpleasant; making you feel very unhappy, upset or frightened","cn":"非常讨厌的；令人极不快的；可怕的","lab":"especially British English","ex":{"en":"a terrible experience","cn":"令人极不愉快的经历"}},{"en":"causing great harm or injury; very serious","cn":"危害极大的；造成极大伤害的；非常严重的","ex":{"en":"a terrible accident","cn":"重大事故"}},{"en":"unhappy or ill","cn":"不痛快；有病","g":"[not before noun]","ex":{"en":"I feel terrible—I think I'll go to bed.","cn":"我觉得难受，想去睡觉了。"}},{"en":"of very bad quality; very bad","cn":"劣质的；劣等的；拙劣的","lab":"informal","ex":{"en":"a terrible meal","cn":"劣质餐食"}},{"en":"used to show the great extent or degree of something bad","cn":"极度的；极其严重的","g":"[only before noun]","lab":"informal","ex":{"en":"a terrible mistake","cn":"严重的错误"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常严重的;骇人的;糟糕的","en":"A terrible experience or situation is very serious or very unpleasant.","ex":{"en":"Tens of thousands more suffered terrible injuries in the world's worst industrial disaster","cn":"还有成千上万的人在那场全世界最严重的工业灾难中受了重伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感觉或看起来)病得很重的，心情很糟的","en":"If you feel terrible, you feel extremely ill or unhappy. If you tell someone that they look terrible, you mean that they look as if they are extremely ill or unhappy.","ex":{"en":"He did feel terrible at the time but seems to be fine now","cn":"他当时确实很难受，但现在似乎好了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"质量极差的;很糟糕的","en":"If something is terrible, it is very bad or of very poor quality.","ex":{"en":"She admits her French is terrible.","cn":"她承认自己的法语很蹩脚。"}},{"pos":"ADJ 形容词","cn":"(用来加强语气)十足的，极度的，不折不扣的","en":"You use terrible to emphasize the great extent or degree of something.","ex":{"en":"I was a terrible fool, you know. I remember that now","cn":"你知道，我那时愚蠢至极。我至今还记得。"}}]},"media":{"uk":"media/uk/terrible__gb_1.mp3","us":"media/us/terrible__us_1.mp3"},"examples":[{"en":"I've just had a terrible thought.","cn":"我刚刚产生了一个可怕的念头。"},{"en":"Your driving is terrible!","cn":"你的驾驶技术真是糟糕透了！"}]},"tennis":{"oxford":{"phon":"ˈtenɪs","pos":"noun","senses":[{"en":"a game in which two or four players use rackets to hit a ball backwards and forwards across a net on a specially marked court","cn":"网球","ex":{"en":"to play tennis","cn":"打网球"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"网球(运动)","en":"Tennis is a game played by two or four players on a rectangular court. The players use an oval bat with strings across it to hit a ball over a net across the middle of the court."}]},"media":{"img":["media/pic/racketsports_comp.jpg","media/thumb/tennis.jpg"],"uk":"media/uk/tennis__gb_1.mp3","us":"media/us/tennis__us_1.mp3"},"examples":[{"en":"a tennis player/tournament/club/court","cn":"网球运动员/锦标赛/俱乐部/场"},{"en":"to play tennis","cn":"打网球"}]},"tenth":{"media":{"uk":"media/uk/tenth__gb_1.mp3","us":"media/us/tenth__us_1.mp3"},"oxford":{"phon":"tenθ","pos":"ordinal number","senses":[{"en":"10th","cn":"第十","ex":{"en":"Today is the tenth (of May).","cn":"今天是五月十日。"}},{"en":"each of ten equal parts of something","cn":"十分之一","pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第十","en":"The tenth item in a series is the one that you count as number ten."},{"pos":"FRACTION 分数词","cn":"十分之一","en":"A tenth is one of ten equal parts of something.","ex":{"en":"We received only two tenths of an inch of rain during the entire month of June.","cn":"整个 6 月，我们这里的降水量只有0.2英寸。"}}]},"examples":[{"en":"in the tenth century","cn":"在10世纪"},{"en":"her tenth birthday","cn":"她的10岁生日"}]},"tend":{"media":{"uk":"media/uk/tend__gb_1.mp3","us":"media/us/tend__us_1.mp3"},"oxford":{"phon":"tend","pos":"verb","senses":[{"en":"to be likely to do something or to happen in a particular way because this is what often or usually happens","cn":"往往会；常常就","g":"[intransitive]","ex":{"en":"Women tend to live longer than men.","cn":"女人往往比男人长寿。"}},{"en":"to take a particular direction or often have a particular quality","cn":"趋向；走向；倾向；趋于","g":"[intransitive]","ex":{"en":"His views tend towards the extreme.","cn":"他的观点趋于偏激。"}},{"en":"to care for somebody/something","cn":"照料；照管；护理","g":"[transitive, intransitive]","ex":{"en":"a shepherd tending his sheep","cn":"照看羊的牧人"}},{"en":"to serve customers in a store, bar, etc.","cn":"招待，侍候，照顾，照料（商店、酒吧等的顾客）","g":"[transitive]","lab":"North American English","ex":{"en":"He had a job tending bar in San Francisco.","cn":"他在旧金山做酒吧服务员。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"往往会；经常就","en":"If something tends to happen, it usually happens or it often happens.","ex":{"en":"A problem for manufacturers is that lighter cars tend to be noisy","cn":"制造商们遇到的一个问题是，重量较轻的汽车往往噪音大。"}},{"pos":"VERB 动词","cn":"倾向于，容易表现出(某种特性)","en":"If you tend towards a particular characteristic, you often display that characteristic.","ex":{"en":"Artistic and intellectual people tend towards left-wing views.","cn":"搞艺术的人和知识分子容易持“左倾”观点。"}},{"pos":"VERB 动词","cn":"个人认为;个人觉得","en":"You can say that you tend to think something when you want to give your opinion, but do not want it to seem too forceful or definite.","ex":{"en":"I tend to think that members of parliament by and large do a good job.","cn":"我个人觉得，议会议员总体上工作还是不错的。"}},{"pos":"VERB 动词","cn":"护理;照料;照看","en":"If you tend someone or something, you do what is necessary to keep them in a good condition or to improve their condition.","ex":{"en":"For years he tended her in her painful illness","cn":"多年来她一直受到病痛的折磨，都是他在照料。"}},{"pos":"VERB 动词","cn":"照顾;照管;伺候","en":"If you tend to someone or something, you pay attention to them and deal with their problems and needs.","ex":{"en":"In our culture, girls are brought up to tend to the needs of others","cn":"在我们的文化里，女孩从小就学着照料别人。"}}]},"examples":[{"en":"People tend to think that the problem will never affect them.","cn":"人们往往认为这个问题绝不会影响到他们。"},{"en":"Ambulance crews were tending to the injured.","cn":"救护车上的救护人员在照料受伤者。"}]},"teenage":{"media":{"uk":"media/uk/teenage__gb_1.mp3","us":"media/us/teenage__us_1.mp3"},"oxford":{"phon":"ˈtiːneɪdʒ","pos":"adjective","senses":[{"en":"between 13 and 19 years old; connected with people of this age","cn":"十几岁的（指 13 至 19 岁）；青少年的","ex":{"en":"a teenage girl/boy","cn":"十几岁的少女／少年"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"十几岁的;青少年的","en":"Teenage children are aged between thirteen and nineteen years old.","ex":{"en":"Almost one in four teenage girls now smoke.","cn":"如今，十几岁的女孩几乎 4 个当中就有 1 个抽烟。"}},{"pos":"ADJ 形容词","cn":"面向十几岁青少年的;由十几岁青少年完成的","en":"Teenage is used to describe things such as films, magazines, bands, or activities that are aimed at or are done by teenage children.","ex":{"en":"...'Smash Hits', a teenage magazine.","cn":"青少年杂志《流行金曲》"}}]},"examples":[{"en":"teenage girls/boys","cn":"十几岁的少女/少年"},{"en":"teenage rebellion","cn":"青少年的叛逆行为"}]},"terrace":{"media":{"uk":"media/uk/terrace__gb_1.mp3","us":"media/us/terrace__us_1.mp3"},"oxford":{"phon":"ˈterəs","pos":"noun","senses":[{"en":"a continuous row of similar houses that are joined together in one block","cn":"（相同的一排）排房，排屋","g":"[countable]","lab":"British English","ex":{"en":"12 Albert Terrace","cn":"艾伯特排房 12 号"}},{"en":"a flat, hard area, especially outside a house or restaurant, where you can sit, eat and enjoy the sun","cn":"（尤指房屋或餐馆外的）露天平台，阳台","g":"[countable]","ex":{"en":"Close to the villa is a big pool with a sun terrace around it.","cn":"别墅旁边是个大游泳池，四周有晒台。"}},{"en":"the wide steps where people can stand to watch the game","cn":"阶梯看台","g":"[plural]","lab":"British English"},{"en":"one of a series of flat areas of ground that are cut into the side of a hill like steps so that crops can be grown there","cn":"梯田；阶地","g":"[countable]","ex":{"en":"The villagers had dug terraces in the hillside.","cn":"村民在山坡上开出了梯田。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"排屋(指相互连接、式样相似的房屋)","en":"A terrace is a row of similar houses joined together by their side walls.","ex":{"en":"...a terrace of stylish Victorian houses.","cn":"一排雅致的维多利亚风格的房屋"}},{"pos":"N-COUNT 可数名词","cn":"(房屋外的)草坪，平台","en":"A terrace is a flat area of stone or grass next to a building where people can sit.","ex":{"en":"Some guests recline in lounge chairs on the sea-facing terrace.","cn":"在面向大海的平台上一些客人斜躺在躺椅上。"}},{"pos":"N-COUNT 可数名词","cn":"梯田;阶地","en":"Terraces are a series of flat areas built like steps on the side of a hill so that crops can be grown there.","ex":{"en":"...massive terraces of maize and millet carved into the mountainside like giant steps.","cn":"山坡上开垦出的像巨型台阶一样的大块大块梯田，上面种着玉米和小米"}},{"pos":"N-PLURAL 复数名词","cn":"(足球赛观众可站立的)阶梯看台","en":"The terraces at a football ground are wide steps that people can stand on when they are watching a game."}]},"examples":[{"en":"All rooms have a balcony or terrace.","cn":"所有的房间都有阳台或露台。"},{"en":"12 Albert Terrace","cn":"艾伯特排房 12 号"}]},"tension":{"media":{"uk":"media/uk/tension__gb_1.mp3","us":"media/us/tension__us_1.mp3"},"oxford":{"phon":"ˈtenʃn","pos":"noun","senses":[{"en":"a situation in which people do not trust each other, or feel unfriendly towards each other, and that may cause them to attack each other","cn":"紧张局势（或关系、状况）","g":"[uncountable, countable, usually plural]","ex":{"en":"There is mounting tension along the border.","cn":"边境局势日趋紧张。"}},{"en":"a situation in which the fact that there are different needs or interests causes difficulties","cn":"矛盾；对立","g":"[countable, uncountable]","ex":{"en":"There is often a tension between the aims of the company and the wishes of the employees.","cn":"公司的目标和雇员的愿望之间经常存在矛盾。"}},{"en":"a feeling of worry and stress that makes it impossible to relax","cn":"（情绪上的）紧张，烦躁","g":"[uncountable]","ex":{"en":"nervous tension","cn":"神经紧张"}},{"en":"the feeling of fear and excitement that is created by a writer or a film director","cn":"（作家或电影导演制造的）紧张气氛","g":"[uncountable]","ex":{"en":"dramatic tension","cn":"扣人心弦的紧张气氛"}},{"en":"the state of being stretched tight; the extent to which something is stretched tight","cn":"拉伸；张力；拉紧状态；绷紧程度","g":"[uncountable]","ex":{"en":"muscular tension","cn":"肌肉绷紧"}},{"en":"to make a wire, sail, etc. tight and stretched","cn":"（使金属线、帆等）拉紧，绷紧","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"紧张关系;紧张局势","en":"Tension is the feeling that is produced in a situation when people are anxious and do not trust each other, and when there is a possibility of sudden violence or conflict.","ex":{"en":"The tension between the two countries is likely to remain","cn":"那两个国家间的紧张局面可能会持续下去。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"紧张;焦虑;焦急","en":"Tension is a feeling of worry and anxiety which makes it difficult for you to relax.","ex":{"en":"She has done her best to keep calm but finds herself trembling with tension and indecision","cn":"她尽力保持镇定，可还是由于紧张、犹豫不决而抖个不停。"}},{"pos":"N-VAR 可变名词","cn":"(势力、观点、影响之间的)冲突，分歧","en":"If there is a tension between forces, arguments, or influences, there are differences between them that cause difficulties.","ex":{"en":"The film explored the tension between public duty and personal affections.","cn":"这部电影探讨了公共义务和个人情感之间的冲突。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"拉紧程度;拉力;张力","en":"The tension in something such as a rope or wire is the extent to which it is stretched tight."}]},"examples":[{"en":"There is often a tension between the aims of the company and the wishes of the employees.","cn":"公司的目标和雇员的愿望之间经常存在矛盾。"},{"en":"We laughed and that helped ease the tension.","cn":"我们笑了，因而使紧张的情绪缓和下来。"}]},"tents":{"oxford":{"phon":"tent","pos":"noun","senses":[{"en":"a shelter made of a large sheet of canvas , nylon , etc. that is supported by poles and ropes fixed to the ground, and is used especially for camping","cn":"帐篷；帐棚"}]}},"telephoning":{"oxford":{"phon":"ˈtelɪfəʊn","pos":"noun","senses":[{"en":"a system for talking to sb else over long distances, using wires or radio; a machine used for this","cn":"电话；电话系统；电话机"},{"en":"the part of the telephone that you hold in your hand and speak into","cn":"电话听筒"}]}},"term":{"media":{"uk":"media/uk/term__gb_1.mp3","us":"media/us/term__us_1.mp3"},"oxford":{"phon":"tɜːm","pos":"noun","senses":[{"en":"a word or phrase used as the name of something, especially one connected with a particular type of language","cn":"词语；术语；措辞","g":"[countable]","ex":{"en":"a technical/legal/generic term","cn":"技术／法律／通用术语"}},{"en":"(especially in the UK) one of the three periods in the year during which classes are held in schools, universities, etc.","cn":"学期（尤用于英国，学校一年分三个学期）","g":"[countable, uncountable]","lab":"North American English also","ex":{"en":"the spring/summer/autumn/fall term","cn":"春季／夏季／秋季学期"}},{"en":"a period of time for which something lasts; a fixed or limited time","cn":"期；期限；任期","g":"[countable]","ex":{"en":"during the president’s first term of/in office","cn":"在总统的首届任期内"}},{"en":"the end of a particular period of time, especially one for which something is expected to last","cn":"到期；期满","g":"[singular]","lab":"formal","ex":{"en":"His life had reached its natural term.","cn":"他已尽其天年。"}},{"en":"each of the various parts in a series, an equation, etc.","cn":"（数列、方程等的）项","g":"[countable]","lab":"mathematics"},{"en":"to use a particular name or word to describe somebody/something","cn":"把…称为；把…叫做","ex":{"en":"At his age, he can hardly be termed young.","cn":"到了这个年纪，他称不上年轻了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"在…方面;从…角度看;根据…来说","en":"If you talk about something in terms of something or in particular terms, you are specifying which aspect of it you are discussing or from what point of view you are considering it.","ex":{"en":"Our goods compete in terms of product quality, reliability and above all variety","cn":"我们的产品在质量、可靠性，尤其是品种方面颇具竞争力。"}},{"pos":"PHRASE 短语","cn":"用…术语;用…语言;用…字眼","en":"If you say something in particular terms, you say it using a particular type or level of language or using language which clearly shows your attitude.","ex":{"en":"The video explains in simple terms how the new tax works","cn":"录像用简单易懂的语言解释了新税法。"}},{"pos":"N-COUNT 可数名词","cn":"术语;学科用语","en":"A term is a word or expression with a specific meaning, especially one which is used in relation to a particular subject.","ex":{"en":"Myocardial infarction is the medical term for a heart attack.","cn":"心肌梗死是心脏病的医学用语。"}},{"pos":"VERB 动词","cn":"把…称作;把…叫作","en":"If you say that something is termed a particular thing, you mean that that is what people call it or that is their opinion of it.","ex":{"en":"He had been termed a temporary employee","cn":"他被称作临时雇员。"}},{"pos":"N-VAR 可变名词","cn":"学期","en":"A term is one of the periods of time that a school, college, or university divides the year into.","ex":{"en":"...the summer term.","cn":"夏季学期"}},{"pos":"N-COUNT 可数名词","cn":"(政党、政府的)任期","en":"A term is a period of time between two elections during which a particular party or government is in power.","ex":{"en":"Felipe Gonzalez won a fourth term of office in Spain's election.","cn":"费利佩·冈萨雷斯在西班牙选举中获得第 4 次连任。"}},{"pos":"N-COUNT 可数名词","cn":"(工作、居住的)期间，期限","en":"A term is a period of time that someone spends doing a particular job or in a particular place.","ex":{"en":"...a 12 month term of service","cn":"为期 12 个月的任职期"}},{"pos":"N-COUNT 可数名词","cn":"(合同、保险的)有效期","en":"A term is the period for which a legal contract or insurance policy is valid.","ex":{"en":"Premiums are guaranteed throughout the term of the policy.","cn":"在保单有效期内，所缴纳的保险费是有保障的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"怀孕期;足月;临产","en":"The term of a woman's pregnancy is the nine month period that it lasts. Term is also used to refer to the end of the nine month period.","ex":{"en":"That makes her the first TV presenter to work the full term of her pregnancy","cn":"那样，她就成了首个怀孕期间一直上班的电视节目主持人。"}},{"pos":"N-PLURAL 复数名词","cn":"(协议、条约等的)条款，条件","en":"The terms of an agreement, treaty, or other arrangement are the conditions that must be accepted by the people involved in it.","ex":{"en":"...the terms of the Helsinki agreement","cn":"《赫尔辛基协议》的条款"}},{"pos":"PHRASE 短语","cn":"勉强接受;向…让步;对…妥协","en":"If you come to terms with something difficult or unpleasant, you learn to accept and deal with it.","ex":{"en":"She had come to terms with the fact that her husband would always be crippled.","cn":"她只好接受了丈夫将终生残疾这个现实。"}},{"pos":"PHRASE 短语","cn":"在平等的条件下;在相同的基础上","en":"If two people or groups compete on equal terms or on the same terms, neither of them has an advantage over the other.","ex":{"en":"I had at last found a sport where I could compete on equal terms with able-bodied people","cn":"我终于发现了一个可以和体格健全的人平等竞争的体育项目。"}},{"pos":"PHRASE 短语","cn":"关系融洽;友好相处","en":"If two people are on good terms or on friendly terms, they are friendly with each other.","ex":{"en":"Madeleine is on good terms with Sarah","cn":"马德琳和萨拉相处很好。"}},{"pos":"PHRASE 短语","cn":"从长远来看/从短期来看/从中期来看","en":"You use the expressions in the long term ,in the short term, and in the medium term to talk about what will happen over a long period of time, over a short period of time, and over a medium period of time.","ex":{"en":"The agreement should have very positive results in the long term","cn":"从长远来看，这个协议将会产生非常积极的影响。"}},{"pos":"PHRASE短语","cn":"按照…的条件;根据…的意见","en":"If you do something on your terms, you do it under conditions that you decide because you are in a position of power.","ex":{"en":"They will sign the union treaty only on their terms.","cn":"只有同意他们的条件，他们才会在联盟条约上签字。"}},{"pos":"PHRASE 短语","cn":"正在考虑，正在打算(做某事)","en":"If you say that you are thinking in terms of doing a particular thing, you mean that you are considering it.","ex":{"en":"United should be thinking in terms of winning the European Cup","cn":"联队应该在考虑要赢得欧洲杯。"}},{"pos":"","cn":"","en":"a contradiction in terms→see: ; in no uncertain terms→see: ; in real terms→see: ; on speaking terms→see: ;"}]},"examples":[{"en":"‘Register’ is the term commonly used to describe different levels of formality in language. “","cn":"语域”是一个术语，通常用以描述语言中用语的正式程度。"},{"en":"Such a development seems unlikely, at least in the short term (= it will not happen for quite a long time).","cn":"这样的发展看来可能性不大，起码短期之内应当如此。"}]},"temper":{"oxford":{"phon":"ˈtempə(r)","pos":"noun","senses":[{"en":"if somebody has a temper, they become angry very easily","cn":"脾气；易怒的性情","g":"[countable, usually singular, uncountable]","ex":{"en":"to have a fiery/hot/violent temper","cn":"脾气暴躁"}},{"en":"a short period of feeling very angry","cn":"怒气；火气；阵怒","g":"[countable, usually singular, uncountable]","ex":{"en":"She says awful things when she's in a temper.","cn":"她一发脾气说话就难听。"}},{"en":"the way that you are feeling at a particular time","cn":"心情；情绪；性情；心境","g":"[countable]","ex":{"en":"Come back when you're in a better temper.","cn":"心情好些时再回来。"}},{"en":"having a particular type of temper","cn":"有…脾气的；心情…的","ex":{"en":"good-/bad-tempered","cn":"脾气好的／坏的"}},{"en":"to make something less severe by adding something that has the opposite effect","cn":"使缓和；使温和","lab":"formal","ex":{"en":"Justice must be tempered with mercy.","cn":"法外尚需施恩。"},"pos":"verb"},{"en":"to make metal as hard as it needs to be by heating and then cooling it","cn":"使（金属）回火","lab":"specialist","ex":{"en":"The blade is hardened and tempered so that it resists damage.","cn":"刀刃经过硬化回火，不易损坏。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"坏脾气;暴脾气","en":"If you refer to someone's temper or say that they have a temper, you mean that they become angry very easily.","ex":{"en":"He had a temper and could be nasty","cn":"他脾气不大好，有时凶得很。"}},{"pos":"N-VAR 可变名词","cn":"情绪;心情","en":"Your temper is the way you are feeling at a particular time. If you are in a good temper, you feel cheerful. If you are in a bad temper, you feel angry and impatient.","ex":{"en":"I was in a bad temper last night","cn":"昨晚我心情不好。"}},{"pos":"VERB 动词","cn":"使缓和;使温和","en":"To temper something means to make it less extreme.","ex":{"en":"For others, especially the young and foolish, the state will temper justice with mercy","cn":"对待其他人时，尤其是年轻人和愚蠢的人，国家会刚柔并济。"}},{"pos":"PHRASE 短语","cn":"发脾气/开始发火","en":"If someone is in a temper or gets into a temper, the way that they are behaving shows that they are feeling angry and impatient.","ex":{"en":"She was still in a temper when Colin arrived","cn":"科林到的时候，她气还没有消。"}},{"pos":"PHRASE 短语","cn":"发脾气;大发雷霆","en":"If you lose your temper, you become so angry that you shout at someone or show in some other way that you are no longer in control of yourself.","ex":{"en":"I've never seen him get cross or lose his temper","cn":"我从未见过他生气或者发火。"}}]},"media":{"uk":"media/uk/temper__gb_1.mp3","us":"media/us/temper__us_1.mp3"},"examples":[{"en":"She lost her temper with a customer and shouted at him.","cn":"她对一位顾客发了脾气，冲着人家大喊大叫。"},{"en":"I struggle to keep my temper with the kids when they misbehave.","cn":"孩子们淘气时，我强捺住性子不发脾气。"}]},"temperature":{"media":{"uk":"media/uk/temperature__gb_1.mp3","us":"media/us/temperature__us_1.mp3"},"oxford":{"phon":"ˈtemprətʃə(r)","pos":"noun","senses":[{"en":"the measurement in degrees of how hot or cold a thing or place is","cn":"温度；气温","ex":{"en":"high/low temperatures","cn":"高温；低温"}},{"en":"the measurement of how hot somebody’s body is","cn":"体温","lab":"British English","ex":{"en":"to take somebody’s temperature (= measure the temperature of somebody’s body using a special instrument)","cn":"量体温"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"温度;气温","en":"The temperature of something is a measure of how hot or cold it is.","ex":{"en":"The temperature soared to above 100 degrees in the shade","cn":"阴凉处的温度骤升至100 多度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"体温","en":"Your temperature is the temperature of your body. A normal temperature is about 37˚ centigrade.","ex":{"en":"His temperature continued to rise alarmingly.","cn":"他的体温还在上升，令人担忧。"}},{"pos":"N-COUNT 可数名词","cn":"(特定场合的)氛围，情绪","en":"You can use temperature to talk about the feelings and emotions that people have in particular situations.","ex":{"en":"There's also been a noticeable rise in the political temperature.","cn":"政治气氛也明显升温了。"}},{"pos":"PHRASE 短语","cn":"室温;常温","en":"If something is at room temperature, its temperature is neither hot nor cold.","ex":{"en":"Stir the parsley into the potatoes and serve at room temperature.","cn":"把欧芹拌入土豆里，放至常温后再端上桌。"}},{"pos":"PHRASE 短语","cn":"发烧","en":"If you are running a temperature or if you have a temperature, your temperature is higher than it usually is.","ex":{"en":"He began to run an extremely high temperature","cn":"他开始发高烧。"}},{"pos":"PHRASE 短语","cn":"量…的体温","en":"If you take someone's temperature you use an instrument called a thermometer to measure the temperature of their body in order to see if they are ill.","ex":{"en":"He will probably take your child's temperature too.","cn":"他很可能也会量量你家孩子的体温。"}}]},"examples":[{"en":"His angry refusal to agree raised the temperature of the meeting.","cn":"他愤然拒不同意，使得会议的气氛紧张起来。"},{"en":"Some places have had temperatures in the 40s (= over 40° centigrade ).","cn":"有些地方气温曾经超过 40 摄氏度。"}]},"television":{"media":{"uk":"media/uk/television__gb_1.mp3","us":"media/us/television__us_1.mp3"},"oxford":{"phon":"ˈtelɪvɪʒn","pos":"noun","senses":[{"en":"a piece of electrical equipment with a screen on which you can watch programmes with moving pictures and sounds","cn":"电视机","g":"[countable]","lab":"also British English, informal，，","ex":{"en":"a widescreen/flat-screen/plasma television","cn":"宽屏幕／平面／等离子电视机"}},{"en":"the programmes broadcast on television","cn":"电视节目","g":"[uncountable]","lab":"also British English, informal，，","ex":{"en":"We don't do much in the evenings except watch television.","cn":"我们在晚上除了看电视不怎么干别的事。"}},{"en":"the system, process or business of broadcasting television programmes","cn":"电视系统；电视学；电视广播业","g":"[uncountable]","lab":"British English","ex":{"en":"satellite/terrestrial/digital/network television","cn":"卫星／地面／数字／网络电视系统"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电视(机)","en":"A television or television set is a piece of electrical equipment consisting of a box with a glass screen on it on which you can watch programmes with pictures and sounds.","ex":{"en":"She turned the television on and flicked around between news programmes.","cn":"她打开电视，来回换台看不同的新闻节目。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"电视","en":"Television is the system of sending pictures and sounds by electrical signals over a distance so that people can receive them on a television in their home.","ex":{"en":"Toy manufacturers began promoting some of their products on television","cn":"玩具制造商开始在电视上推销他们的一些产品。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"电视节目","en":"Television refers to all the programmes that you can watch.","ex":{"en":"I don't have much time to watch very much television.","cn":"我没有太多时间可泡在电视上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"电视广播业;电视行业","en":"Television is the business or industry concerned with making programmes and broadcasting them on television.","ex":{"en":"British commercial television has been steadily losing its lead as the most advanced sector of the industry in Europe.","cn":"英国商业电视在逐步失去其作为欧洲电视广播业最先进部分的领先地位。"}}]},"examples":[{"en":"We don't do much in the evenings except watch television.","cn":"我们在晚上除了看电视不怎么干别的事。"},{"en":"I recognize you. Aren't you on television?","cn":"我认出你来了。你不是常上电视吗？"}]},"teaspoon":{"oxford":{"phon":"ˈtiːspuːn","pos":"noun","senses":[{"en":"a small spoon for putting sugar into tea and other drinks","cn":"茶匙；小匙"},{"en":"the amount a teaspoon can hold","cn":"一茶匙（的量）","ex":{"en":"Add two teaspoons of salt.","cn":"加两小匙盐。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茶匙","en":"A teaspoon is a small spoon that you use to put sugar into tea or coffee.","ex":{"en":"Drop the dough onto a baking sheet with a teaspoon.","cn":"用茶匙把生面团舀到烤盘上。"}},{"pos":"N-COUNT 可数名词","cn":"一茶匙的量","en":"You can refer to an amount of food resting on a teaspoon as a teaspoon of food.","ex":{"en":"He wants three teaspoons of sugar in his coffee.","cn":"他要在咖啡里放 3 茶匙的糖。"}}]},"media":{"img":["media/pic/cutlery_diningroom_comp.jpg","media/thumb/teaspoon.jpg"],"uk":"media/uk/teaspoon__gb_1.mp3","us":"media/us/teaspoon__us_1.mp3"},"examples":[{"en":"Add two teaspoons of salt.","cn":"加两小匙盐。"},{"en":"Add a teaspoon of salt.","cn":"加一茶匙盐。"}]},"temple":{"oxford":{"phon":"ˈtempl","pos":"noun","senses":[{"en":"a building used for religious worship, especially in religions other than Christianity","cn":"（非基督教的）庙宇，寺院，神殿，圣堂","lab":"North American English","ex":{"en":"the Temple of Diana at Ephesus","cn":"以弗所的狄安娜神庙"}},{"en":"each of the flat parts at the sides of the head, at the same level as the eyes and higher","cn":"太阳穴；鬓角；颞颥；颞部","ex":{"en":"He had black hair, greying at the temples.","cn":"他的头发是黑色的，但两鬓已见斑白。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(尤指佛教、印度教以及古希腊、古罗马时代的)寺院，庙宇，圣殿","en":"A temple is a building used for the worship of a god or gods, especially in the Buddhist and Hindu religions, and in ancient Greek and Roman times.","ex":{"en":"...a small Hindu temple.","cn":"一座小的印度教庙宇"}},{"pos":"N-COUNT 可数名词","cn":"太阳穴;鬓角","en":"Your temples are the flat parts on each side of the front part of your head, near your forehead.","ex":{"en":"Threads of silver ran through his beard and the hair at his temples.","cn":"他的胡须和鬓发里夹杂着缕缕银丝。"}}]},"media":{"uk":"media/uk/temple__gb_1.mp3","us":"media/us/temple__us_1.mp3"},"examples":[{"en":"He had black hair, greying at the temples.","cn":"他的头发是黑色的，但两鬓已见斑白。"},{"en":"the Temple of Diana at Ephesus","cn":"以弗所的狄安娜神庙"}]},"technological":{"media":{"uk":"media/uk/technological__gb_1.mp3","us":"media/us/technological__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"科技的;工艺的;技术的","en":"Technological means relating to or associated with technology.","ex":{"en":"...an era of very rapid technological change.","cn":"科技发生迅猛变革的时代"}}]},"examples":[{"en":"a major technological breakthrough","cn":"重大科技突破"},{"en":"technological advances","cn":"科技进步"}],"oxford":{"phon":"ˌteknəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"connected with technology","cn":"技术的；工艺的；工艺技术的","ex":{"en":"technological advances","cn":"技术进步"}}]}},"telephones":{"oxford":{"phon":"ˈtelɪfəʊn","pos":"noun","senses":[{"en":"a system for talking to sb else over long distances, using wires or radio; a machine used for this","cn":"电话；电话系统；电话机"},{"en":"the part of the telephone that you hold in your hand and speak into","cn":"电话听筒"}]}},"tenure":{"media":{"uk":"media/uk/tenure__gb_1.mp3","us":"media/us/tenure__us_1.mp3"},"oxford":{"phon":"ˈtenjə(r)","pos":"noun","senses":[{"en":"the period of time when somebody holds an important job, especially a political one; the act of holding an important job","cn":"（尤指重要政治职务的）任期，任职","ex":{"en":"his four-year tenure as president","cn":"他的四年总统任期"}},{"en":"the right to stay permanently in your job, especially as a teacher at a university","cn":"（尤指大学教师的）终身职位，长期聘用","ex":{"en":"It's still extremely difficult to get tenure.","cn":"要取得终身职位仍然极其困难。"}},{"en":"the legal right to live in a house or use a piece of land","cn":"（房地产的）保有权，保有期","ex":{"en":"When you rent a house here, you don’t have security of tenure.","cn":"在这里租房子没有租住权保障。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(房屋的)居住权;(土地的)使用权，使用期","en":"Tenure is the legal right to live in a particular building or to use a particular piece of land during a fixed period of time.","ex":{"en":"Lack of security of tenure was a reason for many families becoming homeless.","cn":"居住权得不到保证是许多家庭居无定所的一个原因。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(重要职位的)任期，任职期间","en":"Tenure is the period of time during which someone holds an important job.","ex":{"en":"...the three-year tenure of President Bush","cn":"布什总统的三年任期"}},{"pos":"N-UNCOUNT 不可数名词","cn":"终身职位;终身聘用","en":"If you have tenure in your job, you have the right to keep it until you retire.","ex":{"en":"Junior staff have only a slim chance of getting tenure.","cn":"初级职员得到终身职位的机会十分渺茫。"}}]},"examples":[{"en":"She knew that tenure of high political office was beyond her.","cn":"她知道自己与显赫的政治地位无缘。"},{"en":"It's still extremely difficult to get tenure.","cn":"要取得终身职位仍然极其困难。"}]},"textile":{"media":{"uk":"media/uk/textile__gb_1.mp3","us":"media/us/textile__us_1.mp3"},"oxford":{"phon":"ˈtekstaɪl","pos":"noun","senses":[{"en":"any type of cloth made by weaving or knitting","cn":"纺织品","g":"[countable]","ex":{"en":"a factory producing a range of textiles","cn":"生产一系列纺织品的工厂"}},{"en":"the industry that makes cloth","cn":"纺织业","g":"[plural]","ex":{"en":"He got a job in textiles.","cn":"他在纺织行业找到一份工作。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"织物;纺织品","en":"Textiles are types of cloth or fabric, especially ones that have been woven.","ex":{"en":"...decorative textiles for the home.","cn":"家用装饰织品"}},{"pos":"N-PLURAL 复数名词","cn":"纺织业","en":"Textiles are the industries concerned with the manufacture of cloth.","ex":{"en":"Another 75,000 jobs will be lost in textiles and clothing.","cn":"纺织和服装业又要减少 75,000 个工作岗位。"}}]},"examples":[{"en":"a factory producing a range of textiles","cn":"生产一系列纺织品的工厂"},{"en":"a textile designer","cn":"纺织品设计师"}]},"texts":{"oxford":{"phon":"tekst","pos":"noun","senses":[{"en":"the main printed part of a book or magazine, not the notes, pictures, etc. （","cn":"书籍或杂志的）正文，本文（并非附注、图片等）"},{"en":"any form of written material","cn":"文本；文档"}]}},"teams":{"oxford":{"phon":"tiːm","pos":"noun","senses":[{"en":"a group of people who play a particular game or sport against another group of people （","cn":"游戏或运动的）队"},{"en":"a group of people who work together at a particular job （","cn":"一起工作的）组，班"}]}},"tended":{"oxford":{"phon":"tend","pos":"verb","senses":[{"en":"to be likely to do sth or to happen in a particular way because this is what often or usually happens","cn":"往往会；常常就"},{"en":"to take a particular direction or often have a particular quality","cn":"趋向；走向；倾向；趋于"}]}},"teachers":{"oxford":{"phon":"ˈtiːtʃə(r)","pos":"noun","senses":[{"en":"a person whose job is teaching, especially in a school","cn":"教师；教员；老师；先生"}]}},"tests":{"oxford":{"phon":"test","pos":"noun","senses":[{"en":"an examination of sb's knowledge or ability, consisting of questions for them to answer or activities for them to perform","cn":"测验；考查"},{"en":"a medical examination to discover what is wrong with you or to check the condition of your health （","cn":"医疗上的）检查，化验，检验"}]}},"teetering":{"oxford":{"phon":"ˈtiːtə(r)","pos":"verb","senses":[{"en":"to stand or move in an unsteady way so that you look as if you are going to fall","cn":"摇晃；蹒跚行走；踉跄；摇摇欲坠"},{"en":"to be very close to a very unpleasant or dangerous situation","cn":"处在（灾难或危险）的边缘；濒临"}]}},"technologies":{"oxford":{"phon":"tekˈnɒlədʒi","pos":"noun","senses":[{"en":"scientific knowledge used in practical ways in industry, for example in designing new machines","cn":"科技；工艺；工程技术；技术学；工艺学"},{"en":"machinery or equipment designed using technology","cn":"技术性机器（或设备）"}]}},"techniques":{"oxford":{"phon":"tekˈniːk","pos":"noun","senses":[{"en":"a particular way of doing sth, especially one in which you have to learn special skills","cn":"技巧；技艺；工艺"},{"en":"the skill with which sb is able to do sth practical","cn":"技术；技能"}]}},"tears":{"oxford":{"phon":"teə(r)","pos":"verb","senses":[{"en":"to damage sth by pulling it apart or into pieces or by cutting it on sth sharp; to become damaged in this way","cn":"撕裂；撕碎；扯破；戳破"},{"en":"to make a hole in sth by force","cn":"撕开，划成，刺出，扯开（裂口或洞）"}]}},"terrorists":{"oxford":{"phon":"ˈterərɪst","pos":"noun","senses":[{"en":"a person who takes part in terrorism","cn":"恐怖主义者；恐怖分子"}]}},"teen":{"oxford":{"phon":"ˈtiːneɪdʒ","pos":"adj.","senses":[{"en":"between 13 and 19 years old; connected with people of this age","cn":"十几岁的（指 13 至 19 岁）；青少年的"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"十几岁，青少年时期(指从 13 岁到 19 岁)","en":"If you are in your teens, you are between thirteen and nineteen years old.","ex":{"en":"Most people who smoke began smoking in their teens","cn":"多数烟民从十几岁时就开始抽烟了。"}},{"pos":"ADJ 形容词","cn":"面向青少年的;由青少年完成的","en":"Teen is used to describe things such as films, magazines, bands, or activities that are aimed at or are done by people who are in their teens.","ex":{"en":"...a teen movie starring George Carlin","cn":"乔治·卡林主演的青春片"}},{"pos":"N-COUNT 可数名词","cn":"青少年,十几岁的孩子(指从 13 岁到 19 岁)","en":"A teen is someone aged between thirteen and nineteen years old.","ex":{"en":"It used to be that any teen who wanted a summer job could get one.","cn":"从前，十几岁的孩子到了暑假都能找着活干。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41teen2.mp3","us":"media/ldoce/hwd/ame/7/teen.mp3"},"examples":[{"en":"She was in her teens when she met him.","cn":"她遇到他时才十几岁。"},{"en":"We moved to York when I was in my early teens.","cn":"我十三四岁时﹐我们搬到了约克。"}]},"temperaments":{"oxford":{"phon":"ˈtemprəmənt","pos":"noun","senses":[{"en":"a person's or an animal's nature as shown in the way they behave or react to situations or people （","cn":"人或动物的）气质，性情，性格，禀性"},{"en":"the tendency to get emotional and excited very easily and behave in an unreasonable way","cn":"易冲动；（性情）暴躁；喜怒无常"}]}},"teamed":{"oxford":{"phon":"tiːm","pos":"noun","senses":[{"en":"a group of people who play a particular game or sport against another group of people （","cn":"游戏或运动的）队"},{"en":"a group of people who work together at a particular job （","cn":"一起工作的）组，班"}]}},"teasing":{"oxford":{"phon":"tiːz","pos":"verb","senses":[{"en":"to laugh at sb and make jokes about them, either in a friendly way or in order to annoy or embarrass them","cn":"取笑；戏弄；揶揄；寻开心"},{"en":"to annoy an animal, especially by touching it, pulling its tail, etc.","cn":"招惹，逗弄（动物）"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(表情、神态)调侃的，戏谑的，开玩笑的","en":"A teasing expression or manner shows that the person is not completely serious about what they are saying or doing.","ex":{"en":"'But we're having such fun, aren't we?' he protested with a teasing smile","cn":"“可是我们现在玩得很开心，不是吗？”他戏谑地笑着抗议道。"}}]}},"tends":{"oxford":{"phon":"tend","pos":"verb","senses":[{"en":"to be likely to do sth or to happen in a particular way because this is what often or usually happens","cn":"往往会；常常就"},{"en":"to take a particular direction or often have a particular quality","cn":"趋向；走向；倾向；趋于"}]}},"teaches":{"oxford":{"phon":"tiːtʃ","pos":"verb","senses":[{"en":"to give lessons to students in a school, college, university, etc; to help sb learn sth by giving information about it","cn":"教（课程）；讲授；教授"},{"en":"to show sb how to do sth so that they will be able to do it themselves","cn":"教；训练"}]}},"teapots":{"oxford":{"phon":"ˈtiːpɒt","pos":"noun","senses":[{"en":"a container with a spout , a handle and a lid, used for making and serving tea","cn":"茶壶"}]}},"teenagers":{"oxford":{"phon":"ˈtiːneɪdʒə(r)","pos":"noun","senses":[{"en":"a person who is between 13 and 19 years old （13","cn":"至 19 岁之间的）青少年，少年，少女"}]}},"tellers":{"oxford":{"phon":"ˈtelə(r)","pos":"noun","senses":[{"en":"a person whose job is to receive and pay out money in a bank （","cn":"银行的）出纳，出纳员"},{"en":"a machine that pays out money automatically","cn":"出纳机；提款机"}]}},"tested":{"oxford":{"phon":"test","pos":"noun","senses":[{"en":"an examination of sb's knowledge or ability, consisting of questions for them to answer or activities for them to perform","cn":"测验；考查"},{"en":"a medical examination to discover what is wrong with you or to check the condition of your health （","cn":"医疗上的）检查，化验，检验"}]}},"testify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(在法庭上)作证，证明","en":"When someone testifies in a court of law, they give a statement of what they saw someone do or what they know of a situation, after having promised to tell the truth.","ex":{"en":"Several eyewitnesses testified that they saw the officers hit Miller in the face","cn":"几位目击证人证明他们看见那几个警官打了米勒的脸。"}},{"pos":"VERB 动词","cn":"证明;证实","en":"If one thing testifies to another, it supports the belief that the second thing is true.","ex":{"en":"Recent excavations testify to the presence of cultivated inhabitants on the hill during the Arthurian period.","cn":"最近几次发掘证实了亚瑟王时期这座山上有农耕人口居住过。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that something is true, even though it has not been proved and people may not believe it","cn":""},{"en":"to repeatedly say that something is true, especially when other people do not believe you","cn":""},{"en":"to state very firmly that something is true","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To testify is to make a statement or provide evidence, usually in court. Witnesses testify for the prosecution or defense."}]},"collocations":{"phrases":["VERB + TESTIFY be prepared to, be willing to | be unwilling to, refuse to | call sb to, force sb to The president's former aides were called","PREP. against She refused to testify against her brother. | before She was unwilling to testify before Congress. | for a Mafia member who wa","PHRASES testify in court"]},"media":{"uk":"media/ldoce/hwd/bre/c/testify0205.mp3","us":"media/ldoce/hwd/ame/7/testify.mp3"},"examples":[{"en":"He was summoned to testify before a grand jury about his role in the affair.","cn":"他被传唤出庭在大陪审团前就他在这一事件中的角色作证。"},{"en":"Too many young people are unable to write or spell well, as employers will testify.","cn":"写作或拼写不好的年轻人太多了，这一点雇主都会证明。"}],"oxford":{"phon":"ˈtestɪfaɪ","pos":"verb","senses":[{"en":"to make a statement that something happened or that something is true, especially as a witness in court","cn":"（尤指出庭）作证","g":"[intransitive, transitive]","ex":{"en":"She refused to testify against her husband.","cn":"她拒绝出庭作证指控丈夫。"}},{"en":"to say that you believe something is true because you have evidence of it","cn":"证实；证明","g":"[transitive]","lab":"formal","ex":{"en":"Too many young people are unable to write or spell well, as employers will testify.","cn":"写作或拼写不好的年轻人太多了，这一点雇主都会证明。"}},{"en":"to express your belief in God publicly","cn":"见证（上帝的存在）","g":"[intransitive]","lab":"especially North American English"}]}},"teller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"银行出纳员","en":"A teller is someone who works in a bank and who customers pay money to or get money from.","ex":{"en":"Every bank pays close attention to the speed and accuracy of its tellers.","cn":"各家银行都非常注重出纳员工作的速度和准确性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to receive and pay out money in a bank","cn":"银行出纳员"},{"en":"someone who counts votes","cn":"清点选票的人﹐计票员"}]},"media":{"uk":"media/ldoce/hwd/bre/e/teller0205.mp3","us":"media/ldoce/hwd/ame/1/teller.mp3"},"examples":[{"en":"a foul-mouthed teller of lies","cn":"满嘴脏话的撒谎者"},{"en":"automatic teller machines","cn":"自动取款机"}],"oxford":{"phon":"ˈtelə(r)","pos":"noun","senses":[{"en":"a person who works in a bank, receiving and paying out money from and to customers","cn":"（银行的）出纳，出纳员","lab":"especially North American English"},{"en":"a machine that pays out money from a person's bank account","cn":"出纳机；提款机","lab":"North American English","ex":{"en":"He stopped to withdraw cash from an automatic teller.","cn":"他停下来从自动取款机提取现金。"}},{"en":"a person whose job is to count votes, especially in a parliament","cn":"（尤指议会投票时的）计票员"},{"en":"a person who tells stories, etc.","cn":"说…的人；叙述者；讲故事的人；说书人","ex":{"en":"a foul-mouthed teller of lies","cn":"满嘴脏话的撒谎者"}}]}},"telephony":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电话通讯系统","en":"Telephony is a system of sending voice signals using electronic equipment.","ex":{"en":"These optical fibres may be used for new sorts of telephony.","cn":"这些光缆可以用于新型电话通讯系统。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"telephone services, systems, or communication","cn":"电话〔指其服务﹑系统或通信〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld5_telephony.mp3","us":"media/ldoce/hwd/ame/f/ld5_telephony.mp3"},"oxford":{"phon":"təˈlefəni","pos":"noun","senses":[{"en":"the process of sending messages and signals by telephone","cn":"电话通讯"}]}},"telltale":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"泄露内情的;露馅的","en":"Something that is described as telltale gives away information, often about something bad that would otherwise not be noticed.","ex":{"en":"Only occasionally did the telltale redness around his eyes betray the fatigue he was suffering.","cn":"只有从他发红的眼圈上偶尔能看出他非常疲惫。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an event or fact that shows that something is true or that something is happening","cn":""},{"en":"something, especially someone's behaviour or what they say, that makes you believe that something is probably happening or has probably happened","cn":""},{"en":"facts, objects etc that show that something exists or is true","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Something that's telltale accidentally relays important information. A wise parent can tell who ate the last of the birthday cake by the telltale chocolate smudges on the culprit's face."}]},"media":{"uk":"media/ldoce/hwd/bre/d/telltale_adj0205.mp3","us":"media/ldoce/hwd/ame/5/telltale1.mp3"},"examples":[{"en":"The telltale smell of cigarettes told her that he had been in the room.","cn":"那股明显的香烟味告诉她，他曾在这房间里待过。"},{"en":"telltale clues/marks/signs/sounds","cn":"能说明问题的种种线索/痕迹/迹象/声响"}],"oxford":{"phon":"ˈtelteɪl","pos":"adjective","senses":[{"en":"showing that something exists or has happened","cn":"暴露实情的；能说明问题的","ex":{"en":"telltale clues/marks/signs/sounds","cn":"能说明问题的种种线索／痕迹／迹象／声响"}},{"en":"a child who tells an adult what another child has done wrong","cn":"打小报告的小孩；小告密者","pos":"noun"}]}},"tempest":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暴风雨","en":"A tempest is a very violent storm.","ex":{"en":"Torrential rain and a howling tempest cut a swathe of destruction across the country.","cn":"狂风暴雨横扫全国，所到之处，一片狼藉。"}},{"pos":"N-COUNT 可数名词","cn":"风波;风暴","en":"You can refer to a situation in which people are very angry or excited as a tempest . a tempest in a teapot→see: ;","ex":{"en":"I hadn't foreseen the tempest my request would cause","cn":"我没有料到我的请求会掀起这么大一场风波。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a violent storm","cn":"暴风雨"},{"en":"an unimportant matter that someone has become upset about","cn":"大惊小怪﹐小题大做"}]},"vocab":{"pos":"n","senses":[{"en":"Shakespeare's The Tempest begins with one –– a tempest , or a violent and windy storm."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44tempest.mp3","us":"media/ldoce/hwd/ame/8/tempest.mp3"},"examples":[{"en":"Haley dismissed the lawsuit as a tempest in a teapot.","cn":"黑利认为这桩官司是小题大做。"}],"oxford":{"phon":"ˈtempɪst","pos":"noun","senses":[{"en":"a violent storm","cn":"大风暴；暴风雨；暴风雪","ex":{"en":"The screaming tempest whipped into the house, hurling furniture across the room.","cn":"尖叫的暴风雨席卷了房子，把家具扔到了房间的另一边。"}}]}},"tenor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男高音(歌手)","en":"A tenor is a male singer whose voice is fairly high.","ex":{"en":"...a free, open-air concert given by the Italian tenor, Luciano Pavarotti.","cn":"意大利男高音歌唱家卢西亚诺·帕瓦罗蒂举办的一场免费露天演唱会"}},{"pos":"ADJ 形容词","cn":"(萨克斯管等乐器)次中音的","en":"A tenor saxophone or other musical instrument has a range of notes that are of a fairly low pitch.","ex":{"en":"...one of the best tenor sax players ever.","cn":"有史以来最出色的次中音萨克斯管演奏者之一"}},{"pos":"N-SING 单数名词","cn":"大意;主旨;要领","en":"The tenor of something is the general meaning or mood that it expresses.","ex":{"en":"The whole tenor of discussions has changed","cn":"讨论的整个主旨变了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male singing voice that can reach the range of notes below the lowest woman’s voice, or a man with a voice like this","cn":"男高音（歌手）"},{"en":"the part of a musical work that is written for a tenor voice","cn":"男高音声部"},{"en":"the general way in which an event or process takes place 〔","cn":"事物的〕一般趋向﹔〔事件的〕一般（发展）进程"}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"Think of a tenor as a tone — in music, it's the range between baritone and alto in the human voice or in an instrument such as a tenor saxophone. It also is the \"tone\" or meaning of a spoken comment."}]},"collocations":{"phrases":["ADJ. celebrated, famous, great | high | operatic","VERB + TENOR sing We persuaded Jake to sing tenor (= sing the tenor part) .","TENOR + VERB sing Three celebrated tenors sang at the president's inauguration.","TENOR + NOUN voice | part, solo | register 2 atmosphere/feeling","ADJ. even Nothing ever changes the even tenor of life in our village. | general, whole The whole tenor of the meeting was very positive."]},"media":{"uk":"media/ldoce/hwd/bre/9/tenor_n0205.mp3","us":"media/ldoce/hwd/ame/2/tenor.mp3"},"examples":[{"en":"I was encouraged by the general tenor of his remarks.","cn":"他的话中的要点使我深受鼓舞。"},{"en":"a tenor saxophone","cn":"次中音萨克斯管"}],"oxford":{"phon":"ˈtenə(r)","pos":"noun","senses":[{"en":"a man’s singing voice with a range just below the lowest woman’s voice; a man with a tenor voice","cn":"男高音；男高音歌手","g":"[countable]","ex":{"en":"Three celebrated tenors sang at the president's inauguration.","cn":"三位著名男高音歌手在总统就职仪式上演唱。"}},{"en":"a musical part written for a tenor voice","cn":"男高音声部","g":"[singular]","ex":{"en":"We persuaded Jake to sing tenor.","cn":"我们说服杰克唱男高音。"}},{"en":"the general character or meaning of something","cn":"大意；要旨；要领","g":"[singular]","lab":"formal","ex":{"en":"I was encouraged by the general tenor of his remarks.","cn":"他话中的要点使我深受鼓舞。"}},{"en":"with a range of notes similar to that of a tenor voice","cn":"次中音的","ex":{"en":"a tenor saxophone","cn":"次中音萨克斯管"},"pos":"adjective"}]}},"temptress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"勾引男人的女子;妖妇;狐狸精","en":"If you describe a woman as a temptress, you mean that she uses her female charm to encourage men to have sexual relations with her.","ex":{"en":"Supermodel Jane Bracknel plays a nubile temptress out to seduce him.","cn":"超级名模简·布拉克内尔扮演一个性感女郎来勾引他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who makes a man want to have sex with her","cn":"勾引人的女子﹐狐狸精"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41temptress.mp3","us":"media/ldoce/hwd/ame/0/temptress.mp3"},"oxford":{"phon":"ˈtemptrəs","pos":"noun","senses":[{"en":"a woman who tempts somebody, especially one who deliberately makes somebody want to have sex with her","cn":"勾引人的女人；荡妇"}]}},"tetanus":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"破伤风","en":"Tetanus is a serious painful disease caused by bacteria getting into wounds. It makes your muscles, especially your jaw muscles, go stiff."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious illness caused by bacteria that enter your body through cuts and wounds and make your muscles, especially your jaw, go stiff","cn":"破伤风"}]},"vocab":{"pos":"n","senses":[{"en":"Tetanus is a disease of the nervous system spread by bacteria. It's very serious and is usually contracted through an open wound."}]},"media":{"uk":"media/ldoce/hwd/bre/1/tetanus0205.mp3","us":"media/ldoce/hwd/ame/6/tetanus.mp3"},"oxford":{"phon":"ˈtetnəs","pos":"noun","senses":[{"en":"a disease in which the muscles, especially the jaw muscles, become stiff, caused by bacteria entering the body through cuts or wounds","cn":"破伤风"}]}},"teatime":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(下午或傍晚的)茶点时间，喝茶时间","en":"Teatime is the period of the day when people have their tea. It can be eaten in the late afternoon or in the early part of the evening.","ex":{"en":"We left at teatime.","cn":"我们是在下午晚些时候动身的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a time in the late afternoon or early evening when people have a meal 〔","cn":"下午或傍晚的〕茶点时间"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld44teatime.mp3","us":"media/ldoce/hwd/ame/4/ld44teatime.mp3"},"examples":[{"en":"John won’t be back until teatime.","cn":"约翰要到下午茶时间才会回来。"}],"oxford":{"phon":"ˈtiːtaɪm","pos":"noun","senses":[{"en":"the time during the afternoon or early evening when people have the meal called tea","cn":"（下午或傍晚的）茶点时间"}]}},"telex":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电传系统(通过电力或无线电信号收发信息的通讯方式)","en":"Telex is an international system of sending written messages. Messages are converted into signals which are transmitted, either by electricity or by radio signals, and then printed out by a machine in another place."},{"pos":"N-COUNT 可数名词","cn":"电传机;电传收发机","en":"A telex is a machine that transmits and receives telex messages."},{"pos":"N-COUNT 可数名词","cn":"电传;通过电传收发的信息","en":"A telex is a message that you send or that has been received and printed by telex.","ex":{"en":"He sent a telex to the British High Commission in Delhi.","cn":"他给德里的英国高级专员公署发了份电传。"}},{"pos":"VERB 动词","cn":"给…发电传;用电传发送","en":"If you telex a message to someone, you send it to them by telex.","ex":{"en":"The embassy says it has telexed their demands to the foreign ministry","cn":"大使馆表示已通过电传将他们的要求发送给外交部了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a method of communication, in which messages are written on a special machine and then sent using the telephone network","cn":"电传〔一种通信方式〕"},{"en":"a message sent in this way","cn":"电传〔指通过电传发送的信息〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41telex.mp3","us":"media/ldoce/hwd/ame/9/telex1.mp3"},"oxford":{"phon":"ˈteleks","pos":"noun","senses":[{"en":"an international system of communication in which messages are typed on a special machine and sent by the phone system","cn":"电传系统","g":"[uncountable]"},{"en":"a message sent or received by telex","cn":"电传；用户电报","g":"[countable]","ex":{"en":"Several telexes arrived this morning.","cn":"今天早上收到了好几份电传。"}},{"en":"a machine for sending and receiving messages by telex","cn":"电传机；电传收发机","g":"[countable]","lab":"informal"},{"en":"to send a message by telex","cn":"发电传；以电传发出（电文）","pos":"verb"}]}},"template":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(切割木材、纸张、金属等使用的)模板，样板","en":"A template is a thin piece of metal or plastic which is cut into a particular shape. It is used to help you cut wood, paper, metal, or other materials accurately, or to reproduce the same shape many times.","ex":{"en":"Trace around your template and transfer the design onto a sheet of card.","cn":"沿着你的样板边画一圈，把图案描在一张硬纸板上。"}},{"pos":"N-COUNT 可数名词","cn":"样板;范例;范式","en":"If one thing is a template for something else, the second thing is based on the first thing.","ex":{"en":"The deal is likely to provide a template for other agreements.","cn":"这个协议可能会成为其他协议的范例。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin sheet of plastic or metal in a special shape or pattern, used to help cut other materials in a similar shape 〔","cn":"切割材料时用的塑料或金属〕模板﹐型板﹐样板"},{"en":"a computer document containing some basic information that you use as a model for writing other documents, such as business letters, envelopes etc","cn":"模板〔包含一些基本信息的计算机文件样板〕"},{"en":"something that is used as a model for another thing","cn":"样板﹐标准"}]},"vocab":{"pos":"n","senses":[{"en":"A template is a model or a guide for producing something. When you build your website, you might use a free template, filling in your own text and images."}]},"media":{"uk":"media/ldoce/hwd/bre/f/template0205.mp3","us":"media/ldoce/hwd/ame/2/laadtemplate.mp3"},"examples":[{"en":"If you need to write a lot of similar letters, set up a template on your computer.","cn":"如果你需要写许多类似的信件，就在计算机上设一个模板。"},{"en":"Her childhood became a template for how she brought up her own children.","cn":"她的童年生活成了她抚育自己孩子的样板。"}],"oxford":{"phon":"ˈtempleɪt","pos":"noun","senses":[{"en":"a shape cut out of a hard material, used as a model for producing exactly the same shape many times in another material","cn":"样板；模板；型板","ex":{"en":"Pressing the template firmly down on the plastic, cut around it with a knife.","cn":"将模板用力压在塑料上，用刀在其周围切割。"}},{"en":"a thing that is used as a model for producing other similar examples","cn":"样板；模框；标准","ex":{"en":"If you need to write a lot of similar letters, set up a template on your computer.","cn":"如果你需要写许多类似的信件，就在计算机上设一个模板。"}}]}},"technique":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"技巧;方法;工艺","en":"A technique is a particular method of doing an activity, usually a method that involves practical skills.","ex":{"en":"...tests performed using a new technique.","cn":"用新技术进行的试验"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(艺术、体育等方面的)技艺，技法，技能","en":"Technique is skill and ability in an artistic, sporting, or other practical activity that you develop through training and practice.","ex":{"en":"He went off to the Amsterdam Academy to improve his technique.","cn":"他动身前往阿姆斯特丹学院去进修技艺。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of doing something, especially one that is well known and often used","cn":""},{"en":"a set of actions that you use in order to do something. Way is more informal than method and is used more often in everyday English","cn":""},{"en":"something that you use to do something or achieve something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A technique is a method of doing some task or performing something. Your technique for opening drinks might be to twist the top off with your teeth. If so, your dentist better have a good tooth-repair technique ."}]},"collocations":{"phrases":["ADJ. effective, powerful, useful | basic, simple | conventional, established, standard, traditional | advanced, modern, sophisticated | inge","VERB + TECHNIQUE have He has an ingenious technique for dealing with problems of that sort. | adopt, apply, deploy, employ, implement, try, ","TECHNIQUE + VERB allow sth, enable sth Modern freezing techniques enable the chickens to be stored for weeks. | work The new technique works","PREP. ~ for techniques for the storage of data | ~ in They learn basic techniques in self-defence."]},"media":{"uk":"media/ldoce/hwd/bre/1/technique0205.mp3","us":"media/ldoce/hwd/ame/a/technique.mp3"},"examples":[{"en":"The artist combines different techniques in the same painting.","cn":"这位艺术家在同一幅画中把不同的画法结合在一起。"},{"en":"Her technique has improved a lot over the past season.","cn":"在过去的一个赛季里，她的技术大有长进。"}],"oxford":{"phon":"tekˈniːk","pos":"noun","senses":[{"en":"a particular way of doing something, especially one in which you have to learn special skills","cn":"技巧；技艺；工艺","g":"[countable]","lab":"formal","ex":{"en":"management techniques","cn":"管理技巧"}},{"en":"the skill with which somebody is able to do something practical","cn":"技术；技能","g":"[uncountable, singular]","ex":{"en":"The artist spent years perfecting his technique.","cn":"这位艺术家花了许多年完善他的技艺。"}}]}},"testimony":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(法庭上的)证词","en":"In a court of law, someone's testimony is a formal statement that they make about what they saw someone do or what they know of a situation, after having promised to tell the truth.","ex":{"en":"His testimony was an important element of the Prosecution case","cn":"他的证词是这宗公诉案件中的一个重要因素。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"证明;证据","en":"If you say that one thing is testimony to another, you mean that it shows clearly that the second thing has a particular quality.","ex":{"en":"This book is testimony to a very individual kind of courage.","cn":"这本书显示了个人非凡的勇气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who is on trial for a crime","cn":""},{"en":"the lawyers who are working for the defendant","cn":""},{"en":"the lawyers who are trying to prove that the defendant is guilty","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you give testimony you are telling what you saw or what you know. Your testimony that your hand was not in the cookie jar goes against the testimony of several eyewitnesses."}]},"collocations":{"phrases":["ADJ. reliable | false | oral, sworn, verbal, written | eyewitness, personal | expert | court, trial a transcript of the trial testimony","VERB + TESTIMONY give | hear","PREP. by your ~ He had by his own testimony taken part in the burglary. | in ~ In testimony before the Crown Court, she described her moveme","ADJ. ample, clear, eloquent, powerful, remarkable, striking","VERB + TESTIMONY bear, stand as","PREP. ~ to His thick, swollen fingers bore testimony to a lifetime of toil."]},"media":{"uk":"media/ldoce/hwd/bre/f/testimony0205.mp3","us":"media/ldoce/hwd/ame/4/testimony.mp3"},"examples":[{"en":"The pyramids are an eloquent testimony to the ancient Egyptians' engineering skills.","cn":"金字塔是古埃及人非凡工程技术的明鉴。"},{"en":"This increase in exports bears testimony to the successes of industry.","cn":"出口增长证明了工业的成功。"}],"oxford":{"phon":"ˈtestɪməni","pos":"noun","senses":[{"en":"a thing that shows that something else exists or is true","cn":"证据；证明","g":"[uncountable, singular]","lab":"formal","ex":{"en":"This increase in exports bears testimony to the successes of industry.","cn":"出口增长证明了产业的成功。"}},{"en":"a formal written or spoken statement saying what you know to be true, usually in court","cn":"证词；证言；口供","g":"[countable, uncountable]","ex":{"en":"a sworn testimony","cn":"宣誓证词"}}]}},"tectonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地质构造的;地壳构造的","en":"Tectonic means relating to the structure of the earth's surface or crust.","ex":{"en":"...the tectonic plates of the Pacific region.","cn":"太平洋地区的地壳构造板块"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to plate tectonics","cn":"地壳构造的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"No, it’s not the latest electro-dance craze from Japan, the word tectonic refers to the earth's crust and the big hunks of it that shift around."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld5_tectonic.mp3","us":"media/ldoce/hwd/ame/3/ld5_tectonic.mp3"},"examples":[{"en":"tectonic movements","cn":"地壳构造运动"}],"oxford":{"phon":"tekˈtɒnɪk","pos":"adjective","senses":[{"en":"relating to the structure of the earth’s surface","cn":"地壳构造的"}]}},"teal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（见于欧洲和亚洲的）短颈小野鸭，水鸭","en":"A teal is a small duck found in Europe and Asia."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small wild duck","cn":"短颈野鸭﹐水鸭﹐绿翅鸭"},{"en":"a greenish-blue colour","cn":"蓝绿色"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41teal.mp3","us":"media/ldoce/hwd/ame/4/teal.mp3"},"oxford":{"phon":"tiːl","pos":"noun","senses":[{"en":"a small wild duck","cn":"水鸭；短颈野鸭","g":"[countable]"},{"en":"a blue-green colour","cn":"蓝绿色","g":"[uncountable]","lab":"especially North American English"}]}},"teething":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(婴儿)出牙，长乳牙","en":"When babies are teething, their teeth are starting to appear through their gums, often causing them pain.","ex":{"en":"Emma broke off a bit of rusk and gave it to Jacinta, who was teething","cn":"埃玛掰了一块脆饼干给正在出牙的贾辛塔。"}}]}},"terse":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声明、评论）简短的,短促的,无礼的","en":"A terse statement or comment is brief and unfriendly.","ex":{"en":"He issued a terse statement, saying he is discussing his future with colleagues before announcing his decision on Monday","cn":"他发表了简短声明，称他正在和同事讨论他的未来，并将于星期一宣布他的决定。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"replying in very few words in a way that seems rude","cn":""},{"en":"a terse message, reply, statement etc uses very few words and is deliberately intended to make people stop speaking to you or asking you questions","cn":""},{"en":"using few words and saying directly what you think, because that is the way you usually speak, even though it often seems rude to other people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Terse means brief, or using very few words. If your teacher tells you to make your writing in your essay style terse and to the point, he's saying use as few words as you can and be simple and clear."}]},"media":{"uk":"media/ldoce/hwd/bre/c/terse0205.mp3","us":"media/ldoce/hwd/ame/2/terse.mp3"},"examples":[{"en":"The President issued a terse statement denying the charges.","cn":"总统发表了一份简短的声明，否认那些指控。"},{"en":"a terse style","cn":"生硬冷漠的风格"}],"oxford":{"phon":"tɜːs","pos":"adjective","senses":[{"en":"using few words and often not seeming polite or friendly","cn":"简要的；简短生硬的","ex":{"en":"a terse style","cn":"生硬冷漠的风格"}}]}},"teetotal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不喝酒的;滴酒不沾的","en":"Someone who is teetotal does not drink alcohol.","ex":{"en":"He will not be having a celebratory drink, as he is teetotal.","cn":"他滴酒不沾，不会喝庆功酒的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is teetotal never drinks alcohol","cn":"滴酒不沾的"}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. strictly I'm strictly teetotal."]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41teetotal.mp3","us":"media/ldoce/hwd/ame/a/ld41teetotal.mp3"},"examples":[{"en":"He's strictly teetotal.","cn":"他绝对是滴酒不沾。"}],"oxford":{"phon":"ˌtiːˈtəʊtl","pos":"adjective","senses":[{"en":"never drinking alcohol","cn":"从不饮酒的；滴酒不沾的","ex":{"en":"He's strictly teetotal.","cn":"他绝对是滴酒不沾。"}}]}},"technician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"技术员;技师","en":"A technician is someone whose job involves skilled practical work with scientific equipment, for example in a laboratory.","ex":{"en":"...a laboratory technician.","cn":"实验室技术员"}},{"pos":"N-COUNT 可数名词","cn":"巧手;能人","en":"A technician is someone who is very good at the detailed technical aspects of an activity.","ex":{"en":"...a versatile, veteran player, a superb technician.","cn":"技术全面、经验丰富、技巧娴熟的运动能手"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to check equipment or machines and make sure that they are working properly","cn":"技师﹐技术人员"},{"en":"someone who is very good at the skills of a particular sport, music, art etc 〔","cn":"运动﹑音乐﹑艺术等领域的〕技艺精湛者﹐巧匠"}]},"vocab":{"pos":"n","senses":[{"en":"A technician is someone who has knowledge and training in a technical process. If you are having trouble with your computer network, you might have to call in a network technician to get it sorted out."}]},"collocations":{"phrases":["ADJ. chief, senior | skilled | inexperienced | qualified | trainee | lab/laboratory | architectural | dental | computer | lighting, sound He","VERB + TECHNICIAN train a need to train technicians in computer aided engineering • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/9/technician0205.mp3","us":"media/ldoce/hwd/ame/f/technician.mp3"},"examples":[{"en":"laboratory technicians","cn":"实验室技术员"},{"en":"Whether he was a great artist or not, Dali was a superb technician.","cn":"不管达利是不是一位伟大的艺术家﹐他肯定是一个卓越的技巧大师。"}],"oxford":{"phon":"tekˈnɪʃn","pos":"noun","senses":[{"en":"a person whose job is keeping a particular type of equipment or machine in good condition","cn":"技术员；技师","ex":{"en":"laboratory technicians","cn":"实验室技术员"}},{"en":"a person who shows skill at the technical aspects of an art, a sport, etc.","cn":"（艺术、体育等的）有技巧者，技艺精湛者","ex":{"en":"As a pianist, she’s a brilliant technician, but she lacks passion.","cn":"作为一名钢琴家，她是一位出色的技术人员，但她缺乏激情。"}}]}},"technophobe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"科技产品排斥者，技术恐惧者(指不喜欢新科技的人)","en":"If you refer to someone as a technophobe, you mean that they do not like new technology, such as computers or mobile telephones, and are afraid to use it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not like modern machines, such as computers, and would prefer to live without them","cn":"技术恐惧者〔指不喜欢计算机等现代机器的人〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/technophobe0205.mp3","us":"media/ldoce/hwd/ame/b/laadtechnophobe.mp3"},"oxford":{"phon":"ˈteknəʊfəʊb","pos":"noun","senses":[{"en":"a person who is afraid of, dislikes or avoids new technology","cn":"技术恐惧者（惧怕、厌恶或逃避新科技的人）"}]}},"teleconference":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电话会议;电视会议","en":"A teleconference is a meeting involving people in various places around the world who use telephones or video links to communicate with each other.","ex":{"en":"Managers at their factory in Birmingham hold a two-hour teleconference with head office in Stuttgart every day.","cn":"伯明翰工厂的经理们每天和位于斯图加特的总部举行两小时的电话会议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people meet in order to discuss something","cn":""},{"en":"an organized event, especially one that continues for several days, at which a lot of people meet to discuss a particular subject and hear speeches about it","cn":""},{"en":"a large formal meeting of people who belong to a political party, or to an organization of people with the same interests","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/teleconference0205.mp3","us":"media/ldoce/hwd/ame/4/laadteleconference.mp3"},"oxford":{"phon":"ˈtelikɒnfrəns","pos":"verb","senses":[{"en":"to attend a conference or discussion at which members are in different places and speak to each other using phone and video connections","cn":"会议成员在不同的地方参加一个会议或讨论，通过电话和视频连接相互交谈。"},{"en":"a conference or discussion at which members are in different places and speak to each other using phone, internet and video connections","cn":"电话会议；电信会议；远程会议","pos":"noun"}]}},"territorial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"领土的;领海的","en":"Territorial means concerned with the ownership of a particular area of land or water.","ex":{"en":"It is the only republic which has no territorial disputes with the others","cn":"它是唯一和其他国家没有领土争端的共和国。"}},{"pos":"N-COUNT 可数名词","cn":"(英国的)国防义勇军士兵","en":"In Britain, the Territorials are the members of the Territorial Army ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(动物或其行为)地盘意识强的，占地为王的","en":"If you describe an animal or its behaviour as territorial, you mean that it has an area which it regards as its own, and which it defends when other animals try to enter it.","ex":{"en":"Two cats or more in one house will also exhibit territorial behaviour.","cn":"一家若有两只或更多的猫，也会表现出争夺地盘的行为。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"land that is owned by someone or that can be used for farming or building houses","cn":""},{"en":"land that belongs to a country or that is controlled by a country during a war","cn":""},{"en":"relating to land that is owned or controlled by a particular country or government","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If your dog barks whenever someone walks through your yard, it might be because she's territorial , or inclined to protect her territory from trespassers."}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeterritorial.mp3","us":"media/ldoce/hwd/ame/5/territorial.mp3"},"examples":[{"en":"Both countries feel they have territorial claims to (= have a right to own) the islands.","cn":"两个国家都认为对这些岛屿拥有主权。"},{"en":"The country was trying to expand territorially.","cn":"这个国家在设法扩张领土。"}],"oxford":{"phon":"ˌterəˈtɔːriəl","pos":"adjective","senses":[{"en":"connected with the land or sea that is owned by a particular country","cn":"领土的","g":"[usually before noun]","ex":{"en":"territorial disputes","cn":"领土争端"}},{"en":"guarding and defending an area of land that they believe to be their own","cn":"领域性的","ex":{"en":"territorial instincts","cn":"领域性本能"}},{"en":"(in the UK) a member of the Territorial Army","cn":"（英国）本土防卫义勇军士兵","pos":"noun"}]}},"technocracy":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"技术专家统治群体;技术专家政治集团","en":"A technocracy is a group of scientists, engineers, and other experts who have political power as well as technical knowledge.","ex":{"en":"...the power of the Brussels technocracy.","cn":"布鲁塞尔技术专家政治集团的权力"}},{"pos":"N-COUNT 可数名词","cn":"技术专家政府;技术官僚政治","en":"A technocracy is a country or society that is controlled by scientists, engineers, and other experts.","ex":{"en":"...a centralised technocracy.","cn":"技术专家统治的中央集权政府"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a social system in which people with a lot of knowledge about science, machines, and computers have a lot of power","cn":"技术专家政治﹐技术专家统治〔一种科学技术人才掌握大量权力的社会制度〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/technocracy0205.mp3","us":"media/ldoce/hwd/ame/4/laadtechnocracy.mp3"},"oxford":{"phon":"tekˈnɒkrəsi","pos":"noun","senses":[{"en":"a social or political system in which people with scientific knowledge have a lot of power","cn":"专家治国制度；专家政治"}]}},"textured":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"质地粗糙的;有纹理的","en":"A textured surface is not smooth, but has a particular texture, for example, it feels rough.","ex":{"en":"...a mixture of textured and lacy stitches","cn":"织纹状与网眼状交织的针脚"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a surface that is not smooth","cn":"有纹理的﹐质地粗糙的"},{"en":"having a texture that is smooth etc","cn":"质地光滑/粗糙/细密等的"},{"en":"used to describe a work of art, literature, music etc that has many different parts that are combined to produce a final effect 〔","cn":"艺术﹑文学﹑音乐等〕有神韵的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/textured_las2_br.mp3","us":"media/ldoce/hwd/ame/8/laadtextured.mp3"},"examples":[{"en":"textured wallpaper","cn":"起纹理的壁纸"},{"en":"smooth-textured skin","cn":"光滑的皮肤"}],"oxford":{"phon":"ˈtekstʃəd","pos":"adjective","senses":[{"en":"with a surface that is not smooth, but has a particular texture","cn":"起纹理的；质地不平的","ex":{"en":"textured wallpaper","cn":"起纹理的壁纸"}}]}},"telecast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指直播的)电视节目，电视广播","en":"A telecast is a programme that is broadcast on the television, especially a programme that is broadcast live."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is broadcast on television","cn":"电视广播﹐电视节目"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41telecast.mp3","us":"media/ldoce/hwd/ame/e/telecast.mp3"},"examples":[{"en":"The event will be telecast simultaneously to nearly 150 cities.","cn":"这一盛事将向近 150 个城市同时进行电视广播。"}],"oxford":{"phon":"ˈtelikɑːst","pos":"verb","senses":[{"en":"to broadcast something on television","cn":"作电视广播；在电视上播送","ex":{"en":"The event will be telecast simultaneously to nearly 150 cities.","cn":"这一活动将会向近 150 个城市同步电视播送。"}},{"en":"a broadcast on television","cn":"电视广播；电视节目","pos":"noun"}]}},"terry":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤用于制作毛巾、婴儿尿布等的）毛圈棉织物，毛巾布","en":"Terry or terry cloth is a type of fabric which has a lot of very small loops covering both sides. It is used especially for making things like towels and babies' nappies.","ex":{"en":"...a terry nappy.","cn":"毛巾布尿布"}}]},"oxford":{"phon":"ˈteri","pos":"noun","senses":[{"en":"a type of soft cotton cloth that has a surface covered with raised loops of thread, used especially for making towels","cn":"毛圈棉织物（多用以做毛巾）"},{"en":"a first name for boys or girls, short for Terence or Teresa","cn":"特里（男子或女子名，Terence 或 Teresa缩写）","pos":""}]}},"terminal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(疾病)致命的，不治的，晚期的","en":"A terminal illness or disease causes death, often slowly, and cannot be cured.","ex":{"en":"...terminal cancer.","cn":"晚期癌症"}},{"pos":"ADJ 形容词","cn":"(病人)患绝症的，晚期的,病危的","en":"A terminal patient is dying of a terminal illness or disease.","ex":{"en":"They have started a hospice for terminal patients.","cn":"他们为身患绝症的病人开办了一个安养所。"}},{"pos":"N-COUNT 可数名词","cn":"(车辆、乘客、货物的)集散地，起点站，终点站","en":"A terminal is a place where vehicles, passengers, or goods begin or end a journey.","ex":{"en":"Plans are underway for a fifth terminal at Heathrow airport.","cn":"正在制定在希思罗机场修建第 5 航站楼的计划。"}},{"pos":"N-COUNT 可数名词","cn":"终端;终端机","en":"A computer terminal is a piece of equipment consisting of a keyboard and a screen that is used for putting information into a computer or getting information from it.","ex":{"en":"Carl sits at a computer terminal 40 hours a week.","cn":"卡尔每周在电脑终端前坐 40 个小时。"}},{"pos":"N-COUNT 可数名词","cn":"(电路的)端头，端子，线接头","en":"On a piece of electrical equipment, a terminal is one of the points where electricity enters or leaves it.","ex":{"en":"...the positive terminal of the battery.","cn":"电池的阳极"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a big building where people wait to get onto planes","cn":""},{"en":"a long hard surface on which aircraft land and take off","cn":""},{"en":"an area covered with tarmac outside airport buildings","cn":""}]},"vocab":{"pos":"1 adj n 2 n 3 n 4 ad","senses":[{"en":"Terminal is a word with many meanings. Depending on how it's used, it can describe a place where passengers end their journey, a computer screen and keyboard, or a life-ending disease."}]},"collocations":{"phrases":["ADJ. international | air/airport, bus, ferry, rail/railway | passenger | container, freight | coal, gas, etc.","TERMINAL + NOUN building","PREP. at/in a/the ~ We met up at the bus terminal. 2 computer equipment","ADJ. colour | computer | network | display","VERB + TERMINAL connect, disconnect","TERMINAL + NOUN keyboard, screen, server","PREP. at a/the ~ There were two students at each terminal. | on a/the ~ pressing keys on a terminal"]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeterminal.mp3","us":"media/ldoce/hwd/ame/d/terminal1.mp3"},"examples":[{"en":"A second terminal was opened in 2008.","cn":"第二个航空站是 2008 年开始运营的。"},{"en":"The industry is in terminal decline.","cn":"这个行业每况愈下，一蹶不振。"}],"oxford":{"phon":"ˈtɜːmɪnl","pos":"noun","senses":[{"en":"a building or set of buildings at an airport where passengers arrive and leave","cn":"航站楼；航空终点站","ex":{"en":"A second terminal was opened last year.","cn":"第二个航空站是去年开始运营的。"}},{"en":"a place, building or set of buildings where journeys by train, bus or boat begin or end","cn":"（火车、公共汽车或船的）终点站","ex":{"en":"a railway/bus/ferry terminal","cn":"铁路／公共汽车终点站；渡船码头"}},{"en":"a piece of equipment, usually consisting of a keyboard and a screen that joins the user to a central computer system","cn":"终端；终端机","lab":"computing","ex":{"en":"Internet terminals have been installed at most libraries.","cn":"大多数图书馆已经安装了因特网终端。"}},{"en":"a point at which connections can be made in an electric circuit","cn":"（电路的）端子，线接头","lab":"specialist","ex":{"en":"a positive/negative terminal","cn":"正极／负极端子"}},{"en":"that cannot be cured and will lead to death, often slowly","cn":"晚期的；不治的；致命的","lab":"figurative","ex":{"en":"He has terminal lung cancer.","cn":"他患有晚期肺癌。"},"pos":"adjective"},{"en":"suffering from an illness that cannot be cured and will lead to death","cn":"患绝症的；晚期的","ex":{"en":"a terminal patient","cn":"晚期病人"},"pos":"adjective"},{"en":"certain to get worse and come to an end","cn":"不可救药的；无可挽回的","ex":{"en":"The industry is in terminal decline.","cn":"这个行业每况愈下，一蹶不振。"},"pos":"adjective"},{"en":"at the end of something","cn":"末端的；末梢的","g":"[only before noun]","lab":"formal or specialist","ex":{"en":"a terminal branch of a tree","cn":"树顶枝条"},"pos":"adjective"}]}},"teddy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 teddy bear（常用于儿语）","en":"A teddy is the same as a teddy bear. Children often call their teddies 'Teddy' when they are talking to them or about them."}]}},"tempo":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(事情发展的)节奏，速度","en":"The tempo of an event is the speed at which it happens.","ex":{"en":"...owing to the slow tempo of change in an overwhelmingly rural country","cn":"由于以农业占绝对主导地位的国家变革速度缓慢"}},{"pos":"N-VAR 可变名词","cn":"(音乐的)速度，节奏，拍子","en":"The tempo of a piece of music is the speed at which it is played.","ex":{"en":"In a new recording, the Boston Philharmonic tried the original tempo","cn":"在新唱片中，波士顿爱乐乐团尝试了全新的节奏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the speed at which music is played or should be played 〔","cn":"音乐演奏的〕速度"},{"en":"the speed at which something happens 〔","cn":"事情进展的〕节奏﹐步调"}]},"vocab":{"pos":"n","senses":[{"en":"If no one is dancing at your party, you probably want to put on some music with a faster tempo — meaning a faster speed."}]},"collocations":{"phrases":["ADJ. increasing","VERB + TEMPO increase, raise, step up United stepped up the tempo in the second half. | slow (down)","TEMPO + VERB quicken | slacken | change","PHRASES the tempo of life They soon adapted to the tempo of life on the island. 2 speed of a piece of music","ADJ. fast, quick | slow | moderate | waltz, etc.","VERB + TEMPO change","TEMPO + NOUN indications, markings","PREP. at a &hellip; ~ They took the last movement at an unusually slow tempo."]},"media":{"uk":"media/ldoce/hwd/bre/8/tempo0205.mp3","us":"media/ldoce/hwd/ame/e/tempo.mp3"},"examples":[{"en":"It's a difficult piece, with numerous changes of tempo.","cn":"这支曲子节奏变化多，难度很大。"},{"en":"the increasing tempo of life in Western society","cn":"西方社会日益加速的生活节奏"}],"oxford":{"phon":"ˈtempəʊ","pos":"noun","senses":[{"en":"the speed or rhythm of a piece of music","cn":"（乐曲的）速度，拍子，节奏","ex":{"en":"a slow/fast tempo","cn":"慢速；快速"}},{"en":"the speed of any movement or activity","cn":"（运动或活动的）速度，节奏","ex":{"en":"the increasing tempo of life in Western society","cn":"西方社会日益加速的生活节奏"}},{"en":"a vehicle with three wheels, used to deliver goods","cn":"天宝三轮货车","ex":{"en":"A tempo overturned on the main road out of the city, spilling its cargo all over the road.","cn":"出城的主路上，节奏发生了翻车，货物散落在路上。"}}]}},"tendentious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有强烈倾向性的;有偏见的;有争议的","en":"Something that is tendentious expresses a particular opinion or point of view very strongly, especially one that many people disagree with.","ex":{"en":"His analysis was rooted in a somewhat tendentious reading of French history.","cn":"他的分析源于对法国历史带有一定偏见的解读。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a tendentious speech, remark, book etc expresses a strong opinion that is intended to influence people 〔","cn":"演讲﹑评论﹑书籍等〕有强烈倾向性的﹐鼓动性的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are writing a report on climate change, and ignore evidence that the earth is warming, the paper might be called tendentious . Tendentious means promoting a specific, and controversial, point of view."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tendentious.mp3","us":"media/ldoce/hwd/ame/4/tendentious.mp3"},"oxford":{"phon":"tenˈdenʃəs","pos":"adjective","senses":[{"en":"expressing a strong opinion that people are likely to disagree with","cn":"倾向性的；有偏见的；有争议的","ex":{"en":"tendentious political memoirs","cn":"倾向性政治回忆录"}}]}},"teapot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茶壶","en":"A teapot is a container with a lid, a handle, and a spout, used for making and serving tea."},{"pos":"PHRASE 短语","cn":"茶壶里的风暴;小题大做;大惊小怪","en":"If you describe a situation as a tempest in a teapot, you think that a lot of fuss is being made about something that is not important.","ex":{"en":"On Capitol Hill, senators today appear to view the matter as something of a tempest in a teapot.","cn":"美国国会的参议员们今天似乎把这个问题小题大做了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container for making and serving tea, which has a handle and a spout 1 (1)","cn":"茶壶"}]},"media":{"img":["media/ldoce/img/teapot.jpg","media/thumb/teapot.jpg"],"uk":"media/ldoce/hwd/bre/d/teapot_las2_br.mp3","us":"media/ldoce/hwd/ame/e/teapot.mp3"},"oxford":{"phon":"ˈtiːpɒt","pos":"noun","senses":[{"en":"a container with a spout, a handle and a lid (= cover), used for making and serving tea","cn":"茶壶","ex":{"en":"She refilled the teapot with boiling water.","cn":"她把茶壶又添满了开水。"}}]}},"testicle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"睾丸","en":"A man's testicles are the two sex glands between his legs that produce sperm."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two round organs that produce sperm in a male, that are enclosed in a bag of skin behind and below the penis","cn":"睾丸"}]},"media":{"uk":"media/ldoce/hwd/bre/2/testicle0205.mp3","us":"media/ldoce/hwd/ame/6/testicle.mp3"},"examples":[{"en":"testicular cancer","cn":"睾丸癌"}],"oxford":{"phon":"ˈtestɪkl","pos":"noun","senses":[{"en":"either of the two organs that produce sperm, located in a bag of skin below the penis","cn":"睾丸"}]}},"teleprompter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电视广播等公共场合显示讲稿的)电子提词器，自动提示器","en":"A Teleprompter is a device used by people speaking on television or at a public event, which displays words for them to read."}]},"oxford":{"phon":"ˈtelɪprɒmptə(r)","pos":"noun","senses":[{"en":"a device used by people who are speaking in public, especially on television, that displays the words that they have to say","cn":"电子提词器，自动提示器（尤用于电视广播时向说话人提示讲词）"}]}},"telly":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"电视机","en":"A telly is a television.","ex":{"en":"After a hard day's work most people want to relax in front of the telly.","cn":"辛苦了一天后，多数人想在电视机前放松一下。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the system of broadcasting pictures and sound, or the programmes that are broadcast in this way","cn":""},{"en":"the programmes that are broadcast on television or your television set","cn":""},{"en":"use this to talk about programmes on television or people's television sets","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/telly0205.mp3","us":"media/ldoce/hwd/ame/4/ld41telly.mp3"},"examples":[{"en":"He spends most evenings just sitting in front of the telly.","cn":"他大部分晚上的时间都坐在电视机前。"},{"en":"Is there anything good on telly?","cn":"电视上有好的节目吗？"}],"oxford":{"phon":"ˈteli","pos":"noun","senses":[{"en":"a television set","cn":"电视机","g":"[countable]","ex":{"en":"He spends most evenings just sitting in front of the telly.","cn":"他大部分晚上的时间都坐在电视机前。"}},{"en":"the programmes broadcast on television","cn":"电视节目","g":"[uncountable]","ex":{"en":"daytime telly","cn":"日间电视节目"}}]}},"terminus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(公共汽车、火车的)终点站","en":"On a bus or train route, the terminus is the last stop, where the bus or train turns round or starts a journey in the opposite direction.","ex":{"en":"...the London terminus of the Channel Tunnel rail link.","cn":"英吉利海峡隧道连接铁路的伦敦终点站"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where trains or buses regularly stop","cn":""},{"en":"the station or stop at the end of a railway or bus line 〔","cn":"铁路或公共汽车线路的〕终点站"},{"en":"the metal lines along which trains travel. This is sometimes used in American English to say which part of a station a train will leave from","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Consider terminus the end of the line. Whether it describes a train station, a goal, or an era — terminus refers to something’s final point."}]},"media":{"uk":"media/ldoce/hwd/bre/d/terminus0205.mp3","us":"media/ldoce/hwd/ame/2/terminus.mp3"},"oxford":{"phon":"ˈtɜːmɪnəs","pos":"noun","senses":[{"en":"the last station at the end of a railway line or the last stop on a bus route","cn":"（铁路或公共汽车路线的）终点站","ex":{"en":"It's the terminus for trains from the north.","cn":"这是从北方驶来的火车的终点站。"}}]}},"tether":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"无计可施;山穷水尽;走投无路","en":"If you say that you are at the end of your tether, you mean that you are so worried, tired, and unhappy because of your problems that you feel you cannot cope.","ex":{"en":"She was jealous, humiliated, and emotionally at the end of her tether","cn":"她既忌妒又感到屈辱，感情上已经到了崩溃的边缘。"}},{"pos":"N-COUNT 可数名词","cn":"(拴动物的)拴绳，拴链","en":"A tether is a rope or chain which is used to tie an animal to a post or fence so that it can only move around within a small area."},{"pos":"VERB 动词","cn":"将…拴(到)","en":"If you tether an animal or object to something, you attach it there with a rope or chain so that it cannot move very far.","ex":{"en":"The officer dismounted, tethering his horse to a tree.","cn":"军官下了马，把它拴到一棵树上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to feel tired, bored, and annoyed, especially because something annoying keeps happening or something has continued for too long","cn":""},{"en":"to be fed up because you have been doing something or have experienced something boring, annoying etc for too long","cn":""},{"en":"to be very fed up and annoyed, especially with a situation or someone's behaviour that has continued for much too long","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Both a verb and a noun, tether keeps things tied together, or is the tie itself. Remember, when you tether that chair to those balloons, use a strong tether . You don't want to drop from the sky because you tied them together using a cheap piece of rope."}]},"media":{"uk":"media/ldoce/hwd/bre/c/tether_n0205.mp3","us":"media/ldoce/hwd/ame/8/tether1.mp3"},"oxford":{"phon":"ˈteðə(r)","pos":"verb","senses":[{"en":"to tie an animal to a post so that it cannot move very far","cn":"拴（牲畜）","ex":{"en":"He tethered his horse to a tree.","cn":"他用绳子把马拴在树上。"}},{"en":"to use a smartphone to connect a computer to the internet","cn":"与…共享网络（利用智能手机使电脑等接入互联网）","ex":{"en":"You can tether your laptop to your phone.","cn":"您可以将笔记本电脑连接到手机。"}},{"en":"a rope or chain used to tie an animal to something, allowing it to move around in a small area","cn":"（拴牲畜的）拴绳，拴链","pos":"noun"}]}},"terrorise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"telegram":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电报","en":"A telegram is a message that is sent by telegraph and then printed and delivered to someone's home or office.","ex":{"en":"Scores of congratulatory telegrams and letters greeted Franklin on his return","cn":"富兰克林一回来，就收到了好几十封贺电和贺信。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a message sent by telegraph","cn":"电报﹐电文"}]},"vocab":{"pos":"n","senses":[{"en":"A telegram is a message sent by a telegraph, which is also called a wire."}]},"collocations":{"phrases":["ADJ. congratulatory","VERB + TELEGRAM send (sb) | get, receive","TELEGRAM + VERB arrive, come","PREP. ~ from, ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/9/telegram0205.mp3","us":"media/ldoce/hwd/ame/7/telegram.mp3"},"oxford":{"phon":"ˈtelɪɡræm","pos":"noun","senses":[{"en":"a message sent by telegraph and then printed and given to somebody","cn":"电报（用电信号传递的信息）"}]}},"teazel":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"another spelling of teasel teasel","cn":"的另一种拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41teazel.mp3","us":"media/ldoce/hwd/ame/6/ld41teazel.mp3"}},"tease":{"collins":{"senses":[{"pos":"VERB 动词","cn":"嘲笑;取笑;嘲弄","en":"To tease someone means to laugh at them or make jokes about them in order to embarrass, annoy, or upset them.","ex":{"en":"He told her how the boys in East Poldown had set on him, teasing him","cn":"他告诉她东波尔顿的男孩们是如何攻击他、嘲笑他的。"}},{"pos":"N-COUNT 可数名词","cn":"爱开玩笑的人;爱戏弄别人的人","en":"If you refer to someone as a tease, you mean that they like laughing at people or making jokes about them.","ex":{"en":"My brother's such a tease","cn":"我弟弟太喜欢戏弄人了。"}},{"pos":"VERB 动词","cn":"(尤指性方面)逗弄，戏弄，挑逗","en":"If you say that someone is teasing, you mean that they are pretending to offer you something that you want, especially sex, but then not giving it to you.","ex":{"en":"I thought she was teasing, playing the innocent, but looking back, I'm not so sure","cn":"我当时以为她是在勾引我，装纯情，不过现在回想起来，我又说不准了。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指性方面)戏弄别人的人，挑逗别人的人，卖弄风情的人","en":"If you refer to someone as a tease, you mean that they pretend to offer someone what they want, especially sex, but then do not give it to them.","ex":{"en":"Later she heard he had told one of her friends she was a tease.","cn":"后来，她听说他告诉她的一个朋友，说她是狐狸精。"}},{"pos":"","cn":"","en":"相关词组：tease out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to laugh at someone and make jokes in order to have fun by embarrassing them, either in a friendly way or in an unkind way. In everyday English, people often say make fun of rather than tease","cn":""},{"en":"to tease someone, especially in an unkind way, by laughing at something they do and making them seem stupid","cn":""},{"en":"to tease someone in a very unpleasant way that shows you do not respect them, in order to make them angry or upset","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 v","senses":[{"en":"To tease is to pick on someone or to give false hope. You can tease your little sister by saying \"nanny nanny boo boo\" or by holding a cookie just out of her reach."}]},"collocations":{"phrases":["ADV. mercilessly | a little, gently, lightly","VERB + TEASE used to","PREP. about His friends used to tease him about his tatty clothes. | with They teased her mercilessly with remarks about her weight.","PHRASES be just/only teasing Don't get upset, I was only teasing."]},"media":{"uk":"media/ldoce/hwd/bre/9/tease_n0205.mp3","us":"media/ldoce/hwd/ame/8/tease1.mp3"},"examples":[{"en":"The teacher helped them tease out the meaning of the poem.","cn":"老师帮助他们弄清楚那首诗的含义。"},{"en":"I used to get teased about my name.","cn":"过去别人总拿我的名字开玩笑。"}],"oxford":{"phon":"tiːz","pos":"verb","senses":[{"en":"to laugh at somebody and make jokes about them, either in a friendly way or in order to annoy them or make them embarrassed","cn":"取笑；戏弄；揶揄；寻开心","g":"[intransitive, transitive]","ex":{"en":"Don't get upset—I was only teasing.","cn":"别不高兴，我只是在逗你玩。"}},{"en":"to annoy an animal, especially by touching it, pulling its tail, etc.","cn":"招惹，逗弄（动物）","g":"[transitive]"},{"en":"to make somebody sexually excited, especially when you do not intend to have sex with them","cn":"挑逗，撩拨（异性）","g":"[intransitive, transitive]","lab":"disapproving","ex":{"en":"She teased the men with an expression that was both innocent and knowing.","cn":"她带着一种既天真又世故的表情挑逗那些男人。"}},{"en":"to make somebody want something or become excited about something by showing or offering them just a small part of it; to make somebody want more of something","cn":"（用一小部分）逗惹，刺激；使想要更多","g":"[transitive]","ex":{"en":"Spring is here and we have already been teased with a glimpse of summer.","cn":"春天来了，我们已经迫不及待地想要一睹夏日的风采。"}},{"en":"to pull something gently apart into separate pieces","cn":"梳理","g":"[transitive]","ex":{"en":"to tease wool into strands","cn":"把羊毛梳成缕"}},{"en":"to comb your hair in the opposite direction to the way it grows so that it looks thicker","cn":"倒梳（头发）使之蓬起","g":"[transitive]","lab":"North American English"},{"en":"a person who likes to play tricks and jokes on other people, especially by telling them something that is not true or by not telling them something that they want to know","cn":"爱戏弄人的人；逗弄者；取笑者","pos":"noun"},{"en":"an act that is intended as a trick or joke","cn":"戏弄；捉弄；取笑","ex":{"en":"Ignore everything he said—it was all just a tease.","cn":"忽略他所说的一切——这只是一个玩笑。"},"pos":"noun"},{"en":"a person who pretends to be attracted to somebody, makes them sexually excited and then refuses to have sex with them","cn":"卖弄风骚的人；勾引人者","lab":"disapproving","pos":"noun"}]}},"teacup":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茶杯","en":"A teacup is a cup that you use for drinking tea."},{"pos":"PHRASE 短语","cn":"茶杯里的风暴;小题大做;大惊小怪","en":"If you describe a situation as a storm in a teacup, you think that a lot of fuss is being made about something that is not important.","ex":{"en":"Both are trying to present the disagreement as a storm in a teacup.","cn":"双方都想拿这个小分歧做大文章。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cup that you serve tea in","cn":"茶杯"},{"en":"a very small dog, pig, cat etc that is kept as a pet and often carried around","cn":"茶杯犬/茶杯猪/茶杯猫等〔微型宠物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/teacup0205.mp3","us":"media/ldoce/hwd/ame/c/teacup.mp3"},"oxford":{"phon":"ˈtiːkʌp","pos":"noun","senses":[{"en":"a cup in which tea is served","cn":"茶杯"}]}},"teem":{"collins":{"senses":[{"pos":"VERB 动词","cn":"充满，充斥(人或动物)","en":"If you say that a place is teeming with people or animals, you mean that it is crowded and the people and animals are moving around a lot.","ex":{"en":"For most of the year, the area is teeming with tourists.","cn":"一年中大部分时间里，这个地区游人如织。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to rain very heavily","cn":"下大雨"},{"en":"to be very full of people or animals, all moving about","cn":"充满〔走动着的人或动物〕"},{"en":"if it is teeming with rain, it is raining very heavily","cn":"下倾盆大雨"}]},"vocab":{"pos":"v","senses":[{"en":"If your neighborhood seems to teem with cats, that means there are a lot of cats running around. Teem refers to a large number."}]},"media":{"uk":"media/ldoce/hwd/bre/8/teem0205.mp3","us":"media/ldoce/hwd/ame/0/team1.mp3"},"examples":[{"en":"The streets were teeming with tourists.","cn":"大街上游人如鲫。"},{"en":"The rain was teeming down.","cn":"大雨倾盆而下。"}],"oxford":{"phon":"tiːm","pos":"verb","senses":[{"en":"to fall heavily","cn":"倾注；倾泻","ex":{"en":"The rain was teeming down.","cn":"大雨倾盆而下。"}}]}},"tester":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"测试员;试验员","en":"A tester is a person who has been asked to test a particular thing."},{"pos":"N-COUNT 可数名词","cn":"测试器;测试仪","en":"A tester is a machine or device that you use to test whether another machine or device is working properly.","ex":{"en":"I have a battery tester in my garage.","cn":"我的车库里有台电池测试仪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or piece of equipment that tests something","cn":"测试员﹐试验员﹔测试器﹐测试仪"},{"en":"a small bottle of perfume 1 (1) etc, in a shop, for customers to try 〔","cn":"商店里供顾客试用的〕小包装试用品〔如香水〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tester0205.mp3","us":"media/ldoce/hwd/ame/3/laadtester.mp3"},"examples":[{"en":"testers of new software","cn":"新软件测试员"}],"oxford":{"phon":"ˈtestə(r)","pos":"noun","senses":[{"en":"a person or thing that tests something","cn":"测试员；试验员；测试器；测试仪","ex":{"en":"testers of new software","cn":"新软件测试员"}},{"en":"a small container of a product, such as perfume, that you can try in a shop to see if you like it","cn":"（商店里的）小包装试用品（如香水）"}]}},"tercentenary":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"300 周年纪念(日)","en":"A tercentenary is a day or a year which is exactly three hundred years after an important event such as the birth of a famous person.","ex":{"en":"...the tercentenary of Purcell's death.","cn":"普赛尔逝世 300 周年纪念日"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the day or year exactly 300 years after a particular event","cn":"三百周年纪念（日）"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41tercentenary.mp3","us":"media/ldoce/hwd/ame/7/laadtercentenary.mp3"},"examples":[{"en":"the tercentenary of the school's foundation","cn":"建校三百周年纪念"},{"en":"tercentenary celebrations","cn":"三百周年庆典"}],"oxford":{"phon":"ˌtɜːsenˈtiːnəri","pos":"noun","senses":[{"en":"the 300th anniversary of something","cn":"三百周年纪念","ex":{"en":"the tercentenary of the school’s foundation","cn":"建校三百周年纪念"}}]}},"tenement":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大而旧的)公寓大楼","en":"A tenement is a large, old building which is divided into a number of individual flats.","ex":{"en":"...elegant 19th century tenement buildings.","cn":"几幢典雅的 19 世纪公寓大楼"}},{"pos":"N-COUNT 可数名词","cn":"(公寓大楼里的)公寓，房间","en":"A tenement is one of the flats in a tenement.","ex":{"en":"...the cramped Edinburgh tenement in which Connery grew up.","cn":"康纳利小时候居住的位于爱丁堡的狭小公寓"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building divided into apartments, especially in the poorer areas of a city 〔","cn":"尤指城市贫民区的〕公寓大楼"},{"en":"tenement building/house/block","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A tenement is a run-down apartment building. The tenements in Old New York were barely safe enough to live in — fire hazards, no air circulation, and no bathrooms, either."}]},"collocations":{"phrases":["ADJ. crowded | crumbling, dilapidated, ruined, run-down | four-storey, two-storeyed, etc.","TENEMENT + NOUN block, building, house, housing, slum","PREP. in a/the ~ living in a crowded tenement"]},"media":{"uk":"media/ldoce/hwd/bre/3/tenement0205.mp3","us":"media/ldoce/hwd/ame/7/tenement.mp3"},"examples":[{"en":"a tenement block","cn":"经济住宅街区"}],"oxford":{"phon":"ˈtenəmənt","pos":"noun","senses":[{"en":"a large building divided into flats, especially in a poor area of a city","cn":"（尤指城市贫困区的）经济公寓，廉租公寓","ex":{"en":"a tenement block","cn":"经济住宅街区"}}]}},"tedium":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"枯燥;乏味;无聊","en":"If you talk about the tedium of a job, task, or situation, you think it is boring and rather frustrating.","ex":{"en":"She began to wonder whether she wouldn't go mad with the tedium of the job.","cn":"她开始怀疑自己会不会被枯燥的工作逼疯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of being bored because the things you are doing are not interesting and continue for a long time without changing","cn":"冗长乏味"}]},"vocab":{"pos":"n","senses":[{"en":"You can call the state of being really bored while doing something repetitive, tedium . You may loathe the tedium of eating dinner with the family — after all, what is more boring than talking to mom and dad, especially if you could be texting friends?"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41tedium.mp3","us":"media/ldoce/hwd/ame/8/ld41tedium.mp3"},"examples":[{"en":"She longed for something to relieve the tedium of everyday life.","cn":"她渴望有什么事情能排解她日常生活中的烦闷。"},{"en":"We sang while we worked, to relieve the tedium .","cn":"我们边唱歌边干活来排遣无聊。"}],"oxford":{"phon":"ˈtiːdiəm","pos":"noun","senses":[{"en":"the fact of being boring","cn":"单调乏味；冗长；啰嗦","ex":{"en":"She longed for something to relieve the tedium of everyday life.","cn":"她渴望有什么事情能排解她日常生活中的烦闷。"}}]}},"tetchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坏脾气的;易怒的;暴躁的","en":"If you say that someone is tetchy, you mean they are bad-tempered and likely to get angry suddenly without an obvious reason.","ex":{"en":"You always get tetchy when you're hungry","cn":"你一饿的时候火气就大。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"likely to get angry or upset easily","cn":"急躁的﹔容易生气的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tetchy.mp3","us":"media/ldoce/hwd/ame/a/ld41tetchy.mp3"},"examples":[{"en":"Jane’s a bit tetchy this morning.","cn":"简今天上午有点犯急。"}],"oxford":{"phon":"ˈtetʃi","pos":"adjective","senses":[{"en":"easily annoyed","cn":"易怒的；暴躁的；动辄发怒的","ex":{"en":"He sounded tetchy when I asked him where he’d been.","cn":"当我问他去哪儿时，他听起来很暴躁。"}}]}},"tenderness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not hard, firm, or stiff, but easy to press","cn":""},{"en":"used about meat or vegetables that are soft and easy to cut, especially because they have been well cooked","cn":""},{"en":"very wet and too soft, in a way that seems unpleasant – used about bread, vegetables, and the ground","cn":""}]},"collocations":{"phrases":["ADJ. extreme, great, infinite | unexpected | loving","QUANT. wave He felt a brief wave of tenderness towards his old teacher.","VERB + TENDERNESS feel | show","PREP. with (a) ~ She spoke with loving tenderness. | ~ for/towards She felt great tenderness for him.","PHRASES tenderness in sb's eyes/voice, etc. There was tenderness in his face as he looked at her."]},"media":{"uk":"media/ldoce/hwd/bre/b/tender_adj0205.mp3","us":"media/ldoce/hwd/ame/c/tender1.mp3"},"examples":[{"en":"Continue cooking until the meat is tender.","cn":""},{"en":"My arm is still tender where I bruised it.","cn":""}],"oxford":{"phon":"ˈtendənəs","pos":"noun","senses":[{"en":"the quality of being kind, gentle and loving","cn":"和善的；温柔的；亲切的；慈爱的","ex":{"en":"She always treated him with tenderness and compassion.","cn":"她对待他总是充满温柔和同情。"}},{"en":"the quality in food of being easy to bite through and cut","cn":"嫩的；柔软的","ex":{"en":"The meat had been slow-cooked to incredible tenderness.","cn":"肉被慢煮到令人难以置信的嫩度。"}},{"en":"the fact of a part of the body being painful when you touch it","cn":"疼痛的；一触即痛的","ex":{"en":"The patient complained of pain and tenderness in the chest.","cn":"患者主诉胸部疼痛和压痛。"}}]}},"tertiary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"第三的;第三位的;第三阶段的","en":"Tertiary means third in order, third in importance, or at a third stage of development.","ex":{"en":"He must have come to know those philosophers through secondary or tertiary sources.","cn":"他一定是通过第二手或第三手资料了解那些哲学家的。"}},{"pos":"ADJ 形容词","cn":"高等（教育）","en":"Tertiary education is education at university or college level.","ex":{"en":"...institutions of tertiary education.","cn":"高等教育机构"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"third in place, degree, or order","cn":"第三的﹔第三级的﹔第三位的"}]},"vocab":{"pos":"adj","senses":[{"en":"Tertiary is another way of saying \"third in importance,\" like socializing with co-workers being a tertiary reason for getting an after-school job — less important than, first, earning money and second, gaining skills."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tertiary.mp3","us":"media/ldoce/hwd/ame/7/l3tertiary.mp3"},"examples":[{"en":"the tertiary sector (= the area of industry that deals with services rather than materials or goods)","cn":"第三产业部门"},{"en":"( BrE ) tertiary education (= at university or college level)","cn":"高等教育"}],"oxford":{"phon":"ˈtɜːʃəri","pos":"adjective","senses":[{"en":"third in order, rank or importance","cn":"第三的；第三位的；第三级的","ex":{"en":"the tertiary sector (= the area of industry that deals with services)","cn":"第三产业部门"}}]}},"termination":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of ending something, or the end of something","cn":"结束﹐终止﹐停止"},{"en":"a medical operation to end the life of a developing child before it is born","cn":"终止妊娠"}]},"vocab":{"pos":"n","senses":[{"en":"Whether it refers to getting fired from a job, a contract running out, or the assassination of a deep-cover spy, termination is \"the end of the line.\""}]},"collocations":{"phrases":["ADJ. early, premature | sudden","TERMINATION + NOUN date","PHRASES notice of termination The landlord gave notice of the termination of tenancy. | a termination of a contract, termination of employme","ADJ. early","VERB + TERMINATION have, undergo She chose to have an early termination.","PHRASES a termination of (a) pregnancy"]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41termination.mp3","us":"media/ldoce/hwd/ame/3/termination.mp3"},"examples":[{"en":"Failure to comply with these conditions will result in termination of the contract.","cn":"违反这些条件将导致合同终止。"},{"en":"You may face a reduction or termination of benefits.","cn":"你的津贴可能会减少或取消。"}],"oxford":{"phon":"ˌtɜːmɪˈneɪʃn","pos":"noun","senses":[{"en":"the act of ending something; the end of something","cn":"结束；终止；末端；端","g":"[uncountable, countable]","lab":"formal","ex":{"en":"Failure to comply with these conditions will result in termination of the contract.","cn":"违反这些条款将导致合同终止。"}},{"en":"a medical operation to end a pregnancy at an early stage","cn":"终止妊娠","g":"[countable]","lab":"medical","ex":{"en":"She chose to have an early termination.","cn":"她选择了早期终止妊娠。"}}]}},"temptation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"诱惑;引诱;诱惑物;诱因","en":"If you feel you want to do something or have something, even though you know you really should avoid it, you can refer to this feeling as temptation. You can also refer to the thing you want to do or have as a temptation .","ex":{"en":"Will they be able to resist the temptation to buy?","cn":"他们能忍住诱惑不买吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality that something has, which makes people like it, want it, or feel interested in it. Attraction is also used about places or things to do that people like, find interesting, or want to visit","cn":""},{"en":"a quality that someone or something has that makes people like it, want it, or feel interested in it","cn":""},{"en":"a strongly attractive quality that makes you want something very much, even though you know it may be bad for you","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Temptation is something you want to have or to do, even though you know you shouldn't. That bag of peanut butter cups on top of your fridge might be an example of a temptation ."}]},"collocations":{"phrases":["ADJ. big, great, overwhelming, strong | constant","VERB + TEMPTATION feel, have I had the constant temptation to look out of the window. | avoid, overcome, resist | give in/way to, succumb to","PHRASES in/out of temptation's way, place/put temptation in sb's way Keep your valuables locked away so as not to put temptation in the way "]},"media":{"uk":"media/ldoce/hwd/bre/2/temptation0205.mp3","us":"media/ldoce/hwd/ame/9/temptation.mp3"},"examples":[{"en":"I couldn't resist the temptation to open the letter.","cn":"我抑制不住好奇心把信打开了。"},{"en":"An expensive bicycle is a temptation to thieves.","cn":"高档自行车对窃贼是个诱惑。"}],"oxford":{"phon":"tempˈteɪʃn","pos":"noun","senses":[{"en":"the desire to do or have something that you know is bad or wrong","cn":"引诱；诱惑","g":"[countable, uncountable]","ex":{"en":"the temptation of easy profits","cn":"轻而易举获利的诱惑"}},{"en":"a thing that makes somebody want to do or have something that they know is bad or wrong","cn":"煽诱人的事物","g":"[countable]","ex":{"en":"An expensive bicycle is a temptation to thieves.","cn":"高档自行车对窃贼是个诱惑。"}}]}},"terrific":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的;非常棒的;了不起的","en":"If you describe something or someone as terrific, you are very pleased with them or very impressed by them.","ex":{"en":"What a terrific idea!","cn":"多么好的主意！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很多的;很大的;很强的","en":"Terrific means very great in amount, degree, or intensity.","ex":{"en":"He did a terrific amount of fundraising","cn":"他做了大量的筹款工作。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good","cn":""},{"en":"extremely good","cn":""},{"en":"extremely good","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Something that's terrific is very great, like a terrific concert you'll never forget, or something that's very intense, like a terrific thunderstorm."}]},"media":{"uk":"media/ldoce/hwd/bre/4/terrific0205.mp3","us":"media/ldoce/hwd/ame/e/terrific.mp3"},"examples":[{"en":"We drove along at a terrific speed.","cn":"我们以极快的速度驱车行驶。"},{"en":"I feel absolutely terrific today!","cn":"我今天的感觉真是好极了！"}],"oxford":{"phon":"təˈrɪfɪk","pos":"adjective","senses":[{"en":"excellent; wonderful","cn":"极好的；绝妙的；了不起的","lab":"informal","ex":{"en":"I feel absolutely terrific today!","cn":"我今天的感觉真是好极了！"}},{"en":"very large; very great","cn":"很大的；巨大的；异乎寻常的","lab":"informal","ex":{"en":"I've got a terrific amount of work to do.","cn":"我有大量的工作要做。"}}]}},"teammate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"队友","en":"In a game or sport, your team-mates are the other members of your team."}]},"oxford":{"phon":"ˈtiːmmeɪt","pos":"noun","senses":[{"en":"a member of the same team or group as yourself","cn":"同队队员；队友"}]}},"techie":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"技术人员;（尤指）计算机专业人员","en":"Some people refer to someone who works in a technological industry, especially computing, as a techie ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who uses a computer","cn":""},{"en":"someone whose job is to write programs","cn":""},{"en":"someone who works in computing or who knows a lot about computers","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/techie0205.mp3","us":"media/ldoce/hwd/ame/c/laadtechie.mp3"},"oxford":{"phon":"ˈteki","pos":"noun","senses":[{"en":"a person who is expert in or enthusiastic about technology, especially computers","cn":"科技通；科技迷；（尤指）电脑通，电脑迷"},{"en":"expert in or enthusiastic about technology, especially computers; making use of technology","cn":"科技通；科技迷；（尤指）电脑通，电脑迷","ex":{"en":"How techie are you?","cn":"你对电脑有多迷？"},"pos":"adjective"}]}},"terrestrial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动植物)陆地的，陆生的，陆栖的","en":"A terrestrial animal or plant lives on land or on the ground rather than in the sea, in trees, or in the air.","ex":{"en":"Terrestrial and aquatic fauna may sometimes be found resting together under a loose stone.","cn":"有时在松动的石头下可以同时看见栖息的陆生动物和水生动物。"}},{"pos":"ADJ 形容词","cn":"地球的;地球上的","en":"Terrestrial means relating to the planet Earth rather than to some other part of the universe.","ex":{"en":"...terrestrial life forms.","cn":"地球上的各种生命形态"}},{"pos":"ADJ 形容词","cn":"(电视频道)地面的(有别于卫星转播的)","en":"Terrestrial television channels are transmitted using equipment situated at ground level, and not by satellite."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the Earth rather than to the Moon or other planet s","cn":"地球的"},{"en":"living on or relating to land rather than water","cn":"陆地的﹔陆生的﹐陆栖的"},{"en":"TV etc that is broadcast from the Earth rather than from a satellite","cn":"地面转播电视/广播/频道等"}]},"vocab":{"pos":"adj","senses":[{"en":"Not straying far from its Latin root \"terra\" meaning \"earth,\" terrestrial means \"of the earth.\" If it's terrestrial , you'll find it on earth. If it's extra terrestrial , you'll find it emerging from a UFO."}]},"media":{"uk":"media/ldoce/hwd/bre/6/terrestrial0205.mp3","us":"media/ldoce/hwd/ame/0/terrestrial.mp3"},"examples":[{"en":"terrestrial life","cn":"地球上的生物"}],"oxford":{"phon":"təˈrestriəl","pos":"adjective","senses":[{"en":"living on the land or on the ground, rather than in water, in trees or in the air","cn":"陆地的；陆栖的；陆生的","lab":"specialist","ex":{"en":"a terrestrial habitat","cn":"陆上栖息地"}},{"en":"connected with the planet Earth","cn":"地球的；地球上的","ex":{"en":"terrestrial life","cn":"地球上的生物"}},{"en":"operating by using equipment on the surface of the earth, rather than sending the signal via a satellite","cn":"陆地上的，地面上的（与卫星相对而言）"}]}},"televangelist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(定期在电视上宣扬基督教并筹款的)电视福音布道者","en":"A televangelist is someone who makes regular television broadcasts to promote a particular form of Christianity and raise money for particular Christian groups or projects."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who appears regularly on television to try to persuade people to become Christians, and often also asks people to give them money","cn":"电视福音布道者〔定期在电视上宣传基督教并劝人捐款的人〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld44televangelis.mp3","us":"media/ldoce/hwd/ame/e/televangelist.mp3"},"oxford":{"phon":"ˌtelɪˈvændʒəlɪst","pos":"noun","senses":[{"en":"(especially in the US) a person who appears regularly on television to try to persuade people to become Christians and to give money","cn":"电视福音布道者（在美国尤指定期在电视上劝人加入基督教及捐款者）"}]}},"tenet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(理论、信仰的)基本原则，根本信条","en":"The tenets of a theory or belief are the main principles on which it is based.","ex":{"en":"Non-violence and patience are the central tenets of their faith","cn":"非暴力和忍耐是他们的信仰的核心原则。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a principle or belief, especially one that is part of a larger system of beliefs","cn":"原则﹔信条﹔宗旨﹔教义"},{"en":"central/basic/fundamental etc tenet one of the basic tenets of democracy","cn":"民主制度的基本原则之一 tenet of the main tenet of his philosophy 他的哲学思想的主要原则"}]},"vocab":{"pos":"n","senses":[{"en":"A tenet is a principle or belief honored by a person or, more often, a group of people. \"Seek pleasure and avoid pain\" is a basic tenet of Hedonism. \"God exists\" is a tenet of most major religions."}]},"media":{"uk":"media/ldoce/hwd/bre/2/tenet0205.mp3","us":"media/ldoce/hwd/ame/1/tenet.mp3"},"examples":[{"en":"one of the basic/central tenets of Christianity","cn":"基督教的基本/主要信条之一"}],"oxford":{"phon":"ˈtenɪt","pos":"noun","senses":[{"en":"one of the principles or beliefs that a theory or larger set of beliefs is based on","cn":"原则；信条；教义","ex":{"en":"one of the basic/central tenets of Christianity","cn":"基督教的基本／主要信条之一"}}]}},"teak":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"柚木(木材)","en":"Teak is the wood of a tall tree with very hard, light-coloured wood which grows in South-East Asia.","ex":{"en":"The door is beautifully made in solid teak.","cn":"门是由纯柚木制成，做工精美。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard yellowish-brown wood that is used for making ships and good quality furniture","cn":"柚木"}]},"media":{"uk":"media/ldoce/hwd/bre/f/teak0205.mp3","us":"media/ldoce/hwd/ame/3/teak.mp3"},"oxford":{"phon":"tiːk","pos":"noun","senses":[{"en":"the strong hard wood of a tall Asian tree, used especially for making furniture","cn":"柚木（尤用以制造家具）"}]}},"terminate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)终止;(使)结束","en":"When you terminate something or when it terminates, it ends completely.","ex":{"en":"Her next remark abruptly terminated the conversation","cn":"她接下来说的话使谈话戛然而止。"}},{"pos":"VERB 动词","cn":"终止(妊娠)","en":"To terminate a pregnancy means to end it.","ex":{"en":"After a lot of agonizing she decided to terminate the pregnancy","cn":"经历一番痛苦挣扎后，她决定终止妊娠。"}},{"pos":"VERB 动词","cn":"(火车、公共汽车)到达终点","en":"When a train or bus terminates somewhere, it ends its journey there.","ex":{"en":"This train will terminate at Taunton.","cn":"这列火车的终点站是汤顿。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a woman has a miscarriage the baby comes out of her body far too early for it to be able to live","cn":""},{"en":"a baby that is stillborn is born dead but fully developed","cn":""},{"en":"if a baby is born dead , it is not alive when it is born","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To terminate something is to bring it to an end. Period. Full stop."}]},"collocations":{"phrases":["ADV. abruptly, prematurely His contract was abruptly terminated. | swiftly | automatically","VERB + TERMINATE be entitled to, be free to","PHRASES the right to terminate sth Either party has the right to terminate the agreement."]},"media":{"uk":"media/ldoce/hwd/bre/5/terminate0205.mp3","us":"media/ldoce/hwd/ame/b/terminate.mp3"},"examples":[{"en":"This train terminates at London Victoria.","cn":"这趟列车的终点站是伦敦维多利亚火车站。"},{"en":"Your contract of employment terminates in December.","cn":"你的聘约十二月份到期。"}],"oxford":{"phon":"ˈtɜːmɪneɪt","pos":"verb","senses":[{"en":"to end; to make something end","cn":"（使）停止，结束，终止","g":"[intransitive, transitive]","ex":{"en":"Your contract of employment terminates in December.","cn":"你的聘约十二月份到期。"}},{"en":"to end a journey","cn":"到达终点站","g":"[intransitive]","ex":{"en":"This train terminates at London Victoria.","cn":"这趟列车的终点站是伦敦维多利亚火车站。"}}]}},"textbook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"课本;教材;教科书","en":"A textbook is a book containing facts about a particular subject that is used by people studying that subject.","ex":{"en":"She wrote a textbook on international law.","cn":"她写了本国际法教材。"}},{"pos":"ADJ 形容词","cn":"(案件、例子)典型的，典范的","en":"If you say that something is a textbook case or example, you are emphasizing that it provides a clear example of a type of situation or event.","ex":{"en":"The house is a textbook example of medieval domestic architecture","cn":"这所房子是典型的中世纪民居。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book about imaginary people and events","cn":""},{"en":"books that describe imaginary people and events","cn":""},{"en":"novels and plays that are considered to be important works of art","cn":""}]},"collocations":{"phrases":["ADJ. basic, general, introductory, standard Do you have the standard textbook on the subject? | recommended | economics, geography, medical,"]},"media":{"uk":"media/ldoce/hwd/bre/2/textbook_n0205.mp3","us":"media/ldoce/hwd/ame/9/textbook1.mp3"},"examples":[{"en":"a textbook example of how the game should be played","cn":"这项比赛的标准示范"},{"en":"a school/medical/history, etc. textbook","cn":"学校、医学、历史等教科书"}],"oxford":{"phon":"ˈtekstbʊk","pos":"noun","senses":[{"en":"a book that teaches a particular subject and that is used especially in schools and colleges","cn":"教科书；课本；教材","ex":{"en":"a school/medical/history textbook","cn":"学校／医学／历史教科书"}},{"en":"used to describe something that is done exactly as it should be done, in the best possible way","cn":"规范的；标准的","ex":{"en":"a textbook example of how the game should be played","cn":"这项比赛的标准示范"},"pos":"adjective"}]}},"technicality":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(过程、活动的)技术细节，详细步骤","en":"The technicalities of a process or activity are the detailed methods used to do it or to carry it out.","ex":{"en":"...the technicalities of classroom teaching.","cn":"课堂教学的具体步骤"}},{"pos":"N-COUNT 可数名词","cn":"(尤指法律上的)技术性细则","en":"A technicality is a point, especially a legal one, that is based on a strict interpretation of the law or of a set of rules.","ex":{"en":"The earlier verdict was overturned on a legal technicality.","cn":"由于诉讼程序上的一个技术细则，原先的判决被推翻了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"details that are included in a contract or agreement and are written in small print, with the result that people do not always notice them","cn":""},{"en":"a small detail in a set of rules or a law, especially one on which a decision is based","cn":""},{"en":"the exact details about a particular person, plan, agreement etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A technicality is a trivial or very small detail. You might consider your scuffed, unpolished shoes to be an unimportant technicality when you're dressing for a job interview."}]},"collocations":{"phrases":["ADJ. complex | legal","VERB + TECHNICALITY understand | discuss, go into I don't want to go into all the technicalities just now.","PREP. on a ~ (= because of a technicality) The court was forced to release him on a technicality."]},"media":{"uk":"media/ldoce/hwd/bre/f/technicality0205.mp3","us":"media/ldoce/hwd/ame/6/technicality.mp3"},"examples":[{"en":"She was released on a technicality (= because of a small detail in the law).","cn":"根据诉讼程序上的一个细则，她获释了。"},{"en":"I don’t really want to get into discussing the technicalities of laser printing.","cn":"我不想讨论激光打印的技术细节。"}],"oxford":{"phon":"ˌteknɪˈkæləti","pos":"noun","senses":[{"en":"the small details of how to do something or how something works","cn":"技术性细节","g":"[plural]","ex":{"en":"He described the process in broad terms without going into the technicalities.","cn":"他从广义上描述了该过程，但没有深入讨论技术细节。"}},{"en":"a small detail in a law or set of rules, especially one that does not seem fair","cn":"诉讼程序性细节，技术性细则（尤指似乎不合理的）","ex":{"en":"She was released on a technicality (= because of a small detail in the law).","cn":"根据诉讼程序上的一个细则，她获释了。"}}]}},"tearjerker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"催人泪下的戏剧(或电影、书籍)","en":"If you refer to a play, film, or book as a tear-jerker, you are indicating that it is very sad or sentimental."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dealing with emotions such as love and sadness in a way that seems silly and insincere","cn":""},{"en":"a song, poem etc that is soppy seems silly to people because it expresses feelings of love and sympathy too strongly but in a way that does not seem serious","cn":""},{"en":"a story, play, film etc that is intended to make people feel sad and cry","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tearjerker.mp3","us":"media/ldoce/hwd/ame/7/tearjerker.mp3"}},"testis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"睾丸","en":"A man's testes are his testicles ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a testicle","cn":"睾丸"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41testis.mp3","us":"media/ldoce/hwd/ame/3/testis.mp3"},"oxford":{"phon":"ˈtestɪs","pos":"noun","senses":[{"en":"a testicle","cn":"睾丸"}]}},"temporize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(为争取时间)拖延","en":"If you say that someone is temporizing, you mean that they keep doing unimportant things in order to delay something important such as making a decision or stating their real opinion.","ex":{"en":"They are still temporizing in the face of what can only be described as a disaster","cn":"面临着显而易见的灾难，他们还在拖延时间。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to delay or avoid making a decision in order to gain time 〔","cn":"为争取时间而〕拖延"}]},"vocab":{"pos":"v","senses":[{"en":"The verb temporize describes stalling in order to gain time in the hopes of avoiding or preventing something. Your class might temporize so your teacher won't have time to give the pop quiz you all think she's going to give."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41temporize.mp3","us":"media/ldoce/hwd/ame/9/temporize.mp3"},"oxford":{"phon":"ˈtempəraɪz","pos":"verb","senses":[{"en":"to delay making a decision or giving a definite answer, in order to gain time","cn":"拖延时间（不迅速作决定等）"}]}},"teeter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"濒临(危险的形势)","en":"Teeter is used in expressions such as teeter on the brink and teeter on the edge to emphasize that something seems to be in a very unstable situation or position.","ex":{"en":"Three of the hotels are in receivership, and others are teetering on the brink of bankruptcy","cn":"有 3 家宾馆已破产在管，其他几家正在破产的边缘徘徊。"}},{"pos":"VERB 动词","cn":"(人)步履蹒跚，踉踉跄跄;(物)摇摇欲坠，东倒西歪","en":"If someone or something teeters, they shake in an unsteady way, and seem to be about to lose their balance and fall over.","ex":{"en":"Hyde shifted his weight and felt himself teeter forward, beginning to overbalance","cn":"海德转移了一下重心，就感到自己往前倾，开始失去平衡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly become unsteady and start to fall","cn":""},{"en":"if someone or something totters or teeters they move unsteadily from side to side and look as if they are going to fall","cn":""},{"en":"to move unsteadily from side to side","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/teeter0205.mp3","us":"media/ldoce/hwd/ame/1/teeter.mp3"},"examples":[{"en":"She teetered after him in her high-heeled shoes.","cn":"她穿着高跟鞋一步三晃地跟在他后面走。"},{"en":"The country is teetering on the brink of civil war.","cn":"这个国家正处在内战的边缘。"}],"oxford":{"phon":"ˈtiːtə(r)","pos":"verb","senses":[{"en":"to stand or move in an unsteady way so that you look as if you are going to fall","cn":"摇晃；蹒跚行走；踉跄；摇摇欲坠","ex":{"en":"She teetered after him in her high-heeled shoes.","cn":"她穿着高跟鞋一步三晃地跟在他后面走。"}}]}},"temperamentally":{"collins":{"senses":[{"pos":"ADV 副词","cn":"性情地;出于本性地","en":"Temperamentally means because of someone's basic nature or related to someone's basic nature.","ex":{"en":"He is a quitter who is temperamentally unsuited to remaining a champion.","cn":"他是个遇难而退的人，照他的性格，不可能长期保住冠军的称号。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a machine or piece of equipment is not working or doesn't work , it does not do the job it is supposed to do","cn":""},{"en":"if there is something wrong with a machine, car etc, it does not work properly, but you do not know exactly why","cn":""},{"en":"not working - use this especially about a small machine or a small piece of equipment","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/temperamental_las3_br.mp3","us":"media/ldoce/hwd/ame/0/temperamental.mp3"},"examples":[{"en":"I'm temperamentally unsuited to this job.","cn":"我的性格不适合这种工作。"},{"en":"Preston is particularly good at handling temperamental people.","cn":""}],"oxford":{"phon":"ˌtemprəˈmentəli","pos":"adverb","senses":[{"en":"in a way that is connected with somebody's nature and personality","cn":"气质的；性情的；性格的","ex":{"en":"I'm temperamentally unsuited to this job.","cn":"我的性格不适合这个工作。"}}]}},"teamster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卡车司机","en":"A teamster is a person who drives a truck."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to drive a truck","cn":"卡车司机"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41teamster.mp3","us":"media/ldoce/hwd/ame/3/teamster.mp3"},"oxford":{"phon":"ˈtiːmstə(r)","pos":"noun","senses":[{"en":"a person whose job is driving a truck","cn":"卡车司机"}]}},"technocrat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"技术专家官员;技术官僚","en":"A technocrat is a scientist, engineer, or other expert who is one of a group of similar people who have political power as well as technical knowledge."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a skilled scientist who has a lot of power in industry or government 〔","cn":"在产业界或政府内有很大权力的〕技术专家官员﹐技术官僚"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41technocrat.mp3","us":"media/ldoce/hwd/ame/a/technocrat.mp3"},"oxford":{"phon":"ˈteknəkræt","pos":"noun","senses":[{"en":"an expert in science, engineering, etc. who has a lot of power in politics and/or industry","cn":"技术专家官员；技术官僚"}]}},"terrified":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very frightened","cn":"非常害怕的﹐极度惊恐的"},{"en":"very frightened – used especially when you are so frightened that you cannot think or move","cn":""},{"en":"very frightened","cn":"非常害怕的﹐极度惊恐的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you're terrified , you're so scared you can hardly move. Some people keep fuzzy spiders as pets, and others are truly terrified of them."}]},"collocations":{"phrases":["VERBS appear, be, feel, look, seem","ADV. really, truly | absolutely, completely, quite, utterly | pretty | clearly, obviously, plainly | secretly","PREP. at She was absolutely terrified at the thought of jumping off the bridge. | of He's terrified of spiders."]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeterrified.mp3","us":"media/ldoce/hwd/ame/a/terrified.mp3"},"examples":[{"en":"She was terrified at the thought of being alone.","cn":"她一想到孤零零的独自一人就惊恐不安。"},{"en":"I'm terrified of losing you.","cn":"我真害怕失去你。"}],"oxford":{"phon":"ˈterɪfaɪd","pos":"adjective","senses":[{"en":"very frightened","cn":"非常害怕；十分恐惧","ex":{"en":"to be terrified of spiders","cn":"惧怕蜘蛛"}}]}},"teat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(雌性动物的)乳头，奶头","en":"A teat is a pointed part on the body of a female animal which her babies suck in order to get milk."},{"pos":"N-COUNT 可数名词","cn":"(尤指奶瓶上的)塑料(或橡皮)奶嘴","en":"A teat is a piece of rubber or plastic that is shaped like a teat, especially one that is fitted to a bottle so that a baby can drink from it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the rubber part on a baby’s bottle that the baby sucks milk from 〔","cn":"婴儿奶瓶上的〕橡皮奶头﹐奶嘴"},{"en":"one of the small parts on a female animal’s body that her babies suck milk from 〔","cn":"雌性动物的〕奶头﹐乳头"}]},"media":{"uk":"media/ldoce/hwd/bre/8/teat0205.mp3","us":"media/ldoce/hwd/ame/c/teat.mp3"},"oxford":{"phon":"tiːt","pos":"noun","senses":[{"en":"the rubber part at the end of a baby’s bottle that the baby sucks on with its lips and tongue in order to get milk, etc. from the bottle","cn":"奶嘴；橡胶乳头","lab":"British English"},{"en":"one of the parts of a female animal’s body that the young animals drink milk from","cn":"（雌兽的）乳头，奶头"}]}},"tenner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"十英镑;十英镑钞票","en":"A tenner is ten pounds or a ten-pound note."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"£10 or a ten-pound note","cn":"十英镑﹔十英镑钞票"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tenner0205.mp3","us":"media/ldoce/hwd/ame/8/ld41tenner.mp3"},"examples":[{"en":"You can have it for a tenner.","cn":"你出十英镑，这就归你了。"},{"en":"Can you lend me a tenner?","cn":"你能借给我十英镑吗？"}],"oxford":{"phon":"ˈtenə(r)","pos":"noun","senses":[{"en":"£10 or a ten pound note","cn":"十英镑；十英镑钞票","ex":{"en":"You can have it for a tenner.","cn":"你出十英镑，这就归你了。"}}]}},"texas":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a large state in the south of the US, which has a long border with Mexico. It is an important centre of the oil and gas industries, and also of cattle and crop farming. Its cities include Houston, Dallas, San Antonio, Austin, and El Paso. Before it became part","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/p028-000011954.mp3","us":"media/ldoce/hwd/ame/9/texas1.mp3"},"oxford":{"phon":"ˈteksəs","pos":"","senses":[{"en":"a large south-western US state, also called the Lone Star State because it was once an independent republic. It has the second largest population of all US states. Its biggest cities are Houston, San Antonio and Dallas, and the capital city is Austin. Texas became independent of Mexico in 1836 and a US state in 1845. It was also one of the Confederate States. It has been well known for its cowboys and now produces a lot of oil and gas as well as beef and many agricultural products. Tourists visit the Alamo, Big Bend National Park and the Lyndon B Johnson Space Center.","cn":"得克萨斯（美国西南部的州，美国人口第二大州。最大城市休斯敦、圣安东尼奥和达拉斯，首府奥斯汀）"}]}},"tentative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(协议、计划、安排)暂行的，临时的，试探性的","en":"Tentative agreements, plans, or arrangements are not definite or certain, but have been made as a first step.","ex":{"en":"Political leaders have reached a tentative agreement to hold a preparatory conference next month","cn":"政治领导人已就下个月举行预备会议达成初步协定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"踌躇不决的;犹豫的","en":"If someone is tentative, they are cautious and not very confident because they are uncertain or afraid.","ex":{"en":"My first attempts at complaining were rather tentative","cn":"我刚开始投诉时很犹豫不决。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not definite or certain, because you may want to change things","cn":"不确定的﹔暂定的"},{"en":"done without confidence","cn":"踌躇不决的﹐犹豫的"}]},"vocab":{"pos":"adj","senses":[{"en":"Choose the adjective tentative to describe something you are unsure or hesitant about. On Monday, you can make tentative plans for the weekend, but it's too early to commit to one party or another."}]},"media":{"uk":"media/ldoce/hwd/bre/c/tentative0205.mp3","us":"media/ldoce/hwd/ame/0/tentative.mp3"},"examples":[{"en":"I'm taking the first tentative steps towards fitness.","cn":"我试探性地开始实施健身计划。"},{"en":"We made a tentative arrangement to meet on Friday.","cn":"我们暂定星期五见面。"}],"oxford":{"phon":"ˈtentətɪv","pos":"adjective","senses":[{"en":"not definite or certain because you may want to change it later","cn":"不确定的；不肯定的；暂定的","ex":{"en":"We made a tentative arrangement to meet on Friday.","cn":"我们暂定星期五见面。"}},{"en":"not behaving or done with confidence","cn":"踌躇的；犹豫不定的；不果断的","ex":{"en":"a tentative greeting","cn":"怯声怯气的问候"}}]}},"temerity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鲁莽;冒失;无礼","en":"If you say that a person has the temerity to do something, you are annoyed about something they have done which you think showed a lack of respect.","ex":{"en":"He has even had the temerity to invoke the names of Martin Luther King Jr and Malcolm X in defence of his actions.","cn":"他竟然敢搬出马丁·路德·金和马尔科姆·艾克斯的名字来为自己的行为辩解。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone says or does something in a way that shows a lack of respect for other people and is likely to offend them","cn":"鲁莽﹐冒失"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun temerity to mean the quality of being unafraid of danger or punishment. If you have the temerity to jump off the bridge even after hearing about the risk of instant death, you truly are a nutcase."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41temerity.mp3","us":"media/ldoce/hwd/ame/e/temerity.mp3"},"examples":[{"en":"He had the temerity to call me a liar!","cn":"他竟敢说我撒谎！"},{"en":"He actually had the temerity to tell her to lose weight.","cn":"他竟然放肆地叫她减肥。"}],"oxford":{"phon":"təˈmerəti","pos":"noun","senses":[{"en":"extremely confident behaviour that people are likely to consider rude","cn":"鲁莽；冒失；蛮勇","ex":{"en":"He had the temerity to call me a liar!","cn":"他竟敢说我撒谎！"}}]}},"teaser":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指竞赛中的)难题，棘手的问题","en":"A teaser is a difficult question, especially one in a competition."},{"pos":"N-COUNT 可数名词","cn":"爱戏弄别人的人","en":"A teaser is someone who makes fun of people in a slightly cruel way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very difficult question that you have to answer as part of a game or competition 〔","cn":"游戏或竞赛中的〕难题"},{"en":"a short advertisement which appears a few days or weeks before a full advertisement for a product","cn":"悬念式广告﹐预热广告"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n","senses":[{"en":"The nearly impossible puzzle your math teacher gives for extra credit can be called a teaser — a tricky problem to solve."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41teaser.mp3","us":"media/ldoce/hwd/ame/f/teaser.mp3"},"oxford":{"phon":"ˈtiːzə(r)","pos":"noun","senses":[{"en":"a difficult problem or question","cn":"难题；棘手的问题","lab":"informal"},{"en":"an advertisement for a product that does not mention the name of the product or say much about it but is intended to make people interested and likely to pay attention to later advertisements","cn":"前导广告，悬念式广告（含蓄而引人好奇）","ex":{"en":"For the first week we ran a teaser featuring a black cat.","cn":"第一周我们播放了一个以黑猫为主角的预告片。"}}]}},"tepee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美洲印第安人用动物的毛皮或树皮制作的)圆锥形帐篷","en":"A tepee is a round tent. Tepees were first made by Native American peoples from animal skins or the outer covering of trees."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round tent with a pointed top, used by some Native Americans 〔","cn":"一些美洲印第安人使用的〕圆锥形帐篷"}]},"media":{"uk":"media/ldoce/hwd/bre/6/tepee0205.mp3","us":"media/ldoce/hwd/ame/4/laadtepee.mp3"},"oxford":{"phon":"ˈtiːpiː","pos":"noun","senses":[{"en":"a type of tall tent like a cone in shape, used in the past by native North American peoples of the Plains and Great Lakes regions","cn":"（美洲印第安人用兽皮制成的）圆锥形帐篷"}]}},"tenacious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚韧不拔的;坚毅的;坚持不懈的","en":"If you are tenacious, you are very determined and do not give up easily.","ex":{"en":"She is very tenacious and will work hard and long to achieve objectives","cn":"她是个锲而不舍的人，为了达到目标愿意长期苦干。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点、信念)根深蒂固的，深入人心的","en":"If you describe something such as an idea or belief as tenacious, you mean that it has a strong influence on people and is difficult to change or remove.","ex":{"en":"...a remarkably tenacious belief that was to dominate future theories of military strategy.","cn":"会左右未来军事战略理论的一个特别根深蒂固的信念"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are determined to do something, you have decided that you are definitely going to do it, and you will not let anything stop you. Determined is also used about someone’s character, when they usually behave in this way","cn":""},{"en":"determined not to change what you are doing, especially when other people think you are behaving in an unreasonable way. Stubborn is often used when you disapprove of someone. It is also sometimes used when you admire them","cn":""},{"en":"someone who is single-minded works very hard in order to achieve one particular thing, and thinks that everything else is much less important","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use tenacious to mean \"not easily letting go or giving up,\" like a clingy child who has a tenacious grip on his mother's hand."}]},"media":{"uk":"media/ldoce/hwd/bre/0/tenacious0205.mp3","us":"media/ldoce/hwd/ame/f/tenacious.mp3"},"examples":[{"en":"Though seriously ill, he still clings tenaciously to life.","cn":"他虽然病情严重，但仍然顽强地活着。"},{"en":"The party has kept its tenacious hold on power for more than twenty years.","cn":"这个政党已牢牢掌握大权二十多年。"}],"oxford":{"phon":"təˈneɪʃəs","pos":"adjective","senses":[{"en":"that does not stop holding something or give up something easily; determined","cn":"紧握的；不松手的；坚持的","ex":{"en":"a tenacious grip","cn":"紧握"}},{"en":"continuing to exist, have influence, etc. for longer than you might expect","cn":"顽强的；坚忍不拔的","ex":{"en":"a tenacious illness","cn":"顽症"}}]}},"tenancy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(土地、房屋的)租赁，租用","en":"Tenancy is the use that you have of land or property belonging to someone else, for which you pay rent.","ex":{"en":"His father took over the tenancy of the farm 40 years ago","cn":"他父亲 40 年前租下了这个农场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the period of time that someone rents a house, land etc 〔","cn":"住房﹑土地等的〕租赁期﹐租用期"},{"en":"the right to use a house, land etc that is rented 〔","cn":"住房﹑土地等的〕租赁权﹐租用权"}]},"vocab":{"pos":"n","senses":[{"en":"Tenancy is the act of living somewhere, especially in a house, building, or apartment. You could say, for example, that your tenancy in the little white farmhouse lasted for six years, until you moved to the city."}]},"collocations":{"phrases":["ADJ. weekly, yearly, etc. | life | shorthold | joint | assured, protected, secure | business, council, local authority","VERB + TENANCY hold (sth on) The tenancy is held in joint names. The land was held on a yearly tenancy. | take over | grant (sb) | terminate","TENANCY + VERB end, expire","TENANCY + NOUN agreement","PREP. under a/the ~ The club occupies the land under a protected tenancy."]},"media":{"uk":"media/ldoce/hwd/bre/9/tenancy0205.mp3","us":"media/ldoce/hwd/ame/1/tenancy.mp3"},"examples":[{"en":"They had taken over the tenancy of the farm.","cn":"他们承租了那个农场。"},{"en":"a three-month tenancy","cn":"三个月的租期"}],"oxford":{"phon":"ˈtenənsi","pos":"noun","senses":[{"en":"a period of time that you rent a house, land, etc. for","cn":"（房屋、土地等的）租用期限，租赁期限，租期","g":"[countable]","lab":"especially North American English","ex":{"en":"a three-month tenancy","cn":"三个月的租期"}},{"en":"the right to live or work in a building or on land that you rent","cn":"（房屋或土地的）租用，租赁","g":"[countable, uncountable]","ex":{"en":"They had taken over the tenancy of the farm.","cn":"他们承租了那个农场。"}}]}},"tendril":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一束，一缕(头发等)","en":"A tendril is something light and thin, for example a piece of hair which hangs loose and is away from the main part.","ex":{"en":"Tendrils of hair strayed to the edge of her pillow.","cn":"她的几缕头发散落在枕边。"}},{"pos":"N-COUNT 可数名词","cn":"(攀缘植物的)卷须, 蔓","en":"Tendrils are thin stems which grow on some plants so that they can attach themselves to supports such as walls or other plants."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin leafless curling stem by which a climbing plant fastens itself to a support 〔","cn":"攀缘植物的〕卷须"},{"en":"a thin curling piece of hair","cn":"一缕鬈发"}]},"vocab":{"pos":"n","senses":[{"en":"Plants don't have arms or tentacles, but they have something a tiny bit similar: tendrils . Tendrils are thin organs of plants that wrap around other objects for support."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tendril.mp3","us":"media/ldoce/hwd/ame/1/tendril.mp3"},"oxford":{"phon":"ˈtendrəl","pos":"noun","senses":[{"en":"a thin, curly stem that grows from a climbing plant. A plant uses tendrils to attach itself to a wall or other support.","cn":"（攀缘植物的）卷须"},{"en":"a thin, curly piece of something such as hair","cn":"卷须状物（如鬈发）","lab":"literary","ex":{"en":"Her hair hung in tendrils about her face.","cn":"她的头发卷须垂在脸上。"}}]}},"tequila":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"龙舌兰酒，特奎拉酒(一种墨西哥产的烈性酒)","en":"Tequila is a strong alcoholic drink made in Mexico from a type of cactus plant.","ex":{"en":"...a long evening spent downing tequilas.","cn":"豪饮龙舌兰酒度过的漫长夜晚"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong alcoholic drink made in Mexico","cn":"龙舌兰酒﹐特奎拉酒〔一种墨西哥烈酒〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/tequila0205.mp3","us":"media/ldoce/hwd/ame/2/tequila.mp3"},"oxford":{"phon":"təˈkiːlə","pos":"noun","senses":[{"en":"a strong alcoholic drink made in Mexico from a tropical plant","cn":"龙舌兰酒，特奎拉酒（墨西哥产的一种烈性酒）","g":"[uncountable, countable]"},{"en":"a glass of tequila","cn":"一杯龙舌兰酒","g":"[countable]"}]}},"tearaway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小流氓;小痞子;不良青年","en":"If you refer to a young person as a tearaway, you mean that they behave in a wild and uncontrolled way.","ex":{"en":"He blamed lack of parental control for the young tearaways' behaviour.","cn":"他认为，那些小流氓行为不端是因为缺少家教。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young person who behaves badly and often gets into trouble","cn":"小流氓﹐小混混﹔不良青年"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tearaway.mp3","us":"media/ldoce/hwd/ame/c/ld41tearaway.mp3"},"examples":[{"en":"His car was wrecked by a couple of young tearaways.","cn":"他的车被几个小流氓毁得一塌糊涂。"}],"oxford":{"phon":"ˈteərəweɪ","pos":"noun","senses":[{"en":"a young person who is difficult to control and often does stupid, dangerous and/or illegal things","cn":"小流氓；阿飞；不良青年"}]}},"testosterone":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"睾丸素;睾丸酮","en":"Testosterone is a hormone found in men and male animals, which can also be produced artificially. It is thought to be responsible for the male sexual instinct and other male characteristics."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the hormone (= chemical produced by the body ) in males that gives them their male qualities","cn":"睾酮"}]},"vocab":{"pos":"n","senses":[{"en":"Testosterone is a hormone made in the testes in males and in the ovaries in females. Testosterone is generally found in greater amounts in males, where it aids in the development of the male sex organs and sperm."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41testosterone.mp3","us":"media/ldoce/hwd/ame/2/testosterone.mp3"},"oxford":{"phon":"teˈstɒstərəʊn","pos":"noun","senses":[{"en":"a hormone (= chemical substance produced in the body) that causes men to develop the physical and sexual features that are characteristic of the male body","cn":"睾酮；睾丸素"}]}},"terrorize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使惊恐;恐吓;威胁","en":"If someone terrorizes you, they keep you in a state of fear by making it seem likely that they will attack you.","ex":{"en":"Bands of gunmen have hijacked food shipments and terrorized relief workers.","cn":"几伙持枪歹徒劫持了运输的食品，还恐吓了救援人员。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel frightened about what will happen if they do not do something, so that they do it. Scare somebody into is more informal than frighten somebody into","cn":""},{"en":"to deliberately frighten people over a long period of time, by using violence or by threatening them, especially in order to make them do what you want","cn":""},{"en":"to deliberately frighten people by threatening to harm them, especially so they will do what you want","cn":"恐吓﹔恫吓﹔威胁"}]},"vocab":{"pos":"v","senses":[{"en":"When you terrorize someone, you act in a way that makes that person feel terrified, or full of fear. A bully might terrorize his younger victims by threatening to beat them up."}]},"media":{"uk":"media/ldoce/hwd/bre/2/terrorize0205.mp3","us":"media/ldoce/hwd/ame/a/terrorize.mp3"},"examples":[{"en":"People were terrorized into leaving their homes.","cn":"人们在恫吓之下离开家园。"},{"en":"drug dealers terrorizing the neighbourhood","cn":"使附近地区人心惶惶的毒品贩子"}],"oxford":{"phon":"ˈterəraɪz","pos":"verb","senses":[{"en":"to frighten and threaten people so that they will not oppose something or will do as they are told","cn":"恐吓；恫吓；威胁","ex":{"en":"drug dealers terrorizing the neighbourhood","cn":"使附近地区人心惶惶的毒品贩子"}}]}},"teasel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"起绒草;川续断","en":"A teasel is a plant with dry prickly flowers and leaves."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant with leaves and flowers that feel sharp when you touch them","cn":"川续断﹐起绒草"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41teasel.mp3","us":"media/ldoce/hwd/ame/8/ld41teasel.mp3"},"oxford":{"phon":"ˈtiːzl","pos":"noun","senses":[{"en":"a plant that has large flowers with spikes, used in the past for brushing cloth to give it a smooth surface","cn":"川续断，起绒草（旧时用以使织物表面起绒）"}]}},"tempestuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(关系)紧张的，跌宕起伏的;(局势)动荡不定的，风云变幻的","en":"If you describe a relationship or a situation as tempestuous, you mean that very strong and intense emotions, especially anger, are involved.","ex":{"en":"For years, the couple's tempestuous relationship made the headlines","cn":"有好多年，那对夫妻跌宕起伏的关系总是登上报纸头条。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a tempestuous relationship or period of time involves a lot of difficulty and strong emotions 〔","cn":"关系〕动荡的﹐紧张的﹐错杂的﹔〔时代〕风云变幻的"},{"en":"a tempestuous sea or wind is very rough and violent","cn":"波涛汹涌的﹔狂风大作的"}]},"vocab":{"pos":"adj","senses":[{"en":"A tempest is a storm, so you can use the adjective tempestuous to describe anything stormy or volatile — from a tempestuous hurricane to a tempestuous romance."}]},"media":{"uk":"media/ldoce/hwd/bre/a/tempestuous0205.mp3","us":"media/ldoce/hwd/ame/2/tempestuous.mp3"},"examples":[{"en":"a tempestuous relationship","cn":"冲突不断的关系"},{"en":"tempestuous seas","cn":"波涛汹涌的大海"}],"oxford":{"phon":"temˈpestʃuəs","pos":"adjective","senses":[{"en":"full of extreme emotions","cn":"激烈的；狂暴的；骚动的","lab":"formal","ex":{"en":"a tempestuous relationship","cn":"冲突不断的关系"}},{"en":"caused by or affected by a violent storm","cn":"狂风暴雨的；大风暴的","lab":"formal or literary","ex":{"en":"tempestuous seas","cn":"波涛汹涌的大海"}}]}},"teepee":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"another spelling of tepee tepee","cn":"的另一种拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41teepee.mp3","us":"media/ldoce/hwd/ame/5/teepee.mp3"},"oxford":{"phon":"ˈtiːpiː","pos":"noun","senses":[{"en":"a type of tall tent like a cone in shape, used in the past by native North American peoples of the Plains and Great Lakes regions","cn":"（美洲印第安人用兽皮制成的）圆锥形帐篷"}]}},"teardrop":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"泪珠;泪滴","en":"A teardrop is a large tear that comes from your eye when you are crying quietly."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a single drop of salty liquid that comes out of your eye when you are crying","cn":"泪滴﹐泪珠"}]},"media":{"uk":"media/ldoce/hwd/bre/3/teardrop0205.mp3","us":"media/ldoce/hwd/ame/7/teardrop.mp3"},"examples":[{"en":"A large teardrop ran down her cheek.","cn":"一颗大大的泪珠从她的脸颊上淌下来。"}],"oxford":{"phon":"ˈtɪədrɒp","pos":"noun","senses":[{"en":"a single tear that comes from your eye","cn":"泪珠"}]}},"teach-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宣讲会，座谈会(学生、教师就某一话题举行的讨论会)","en":"A teach-in is a meeting, usually between students and teachers, with discussions on important and interesting topics. Teach-ins are not usually part of a formal academic course."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an informal meeting of people who are interested in a particular subject, where they have the opportunity to learn more about it 〔","cn":"某一专题的〕宣讲会﹐座谈会"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41teach-in.mp3","us":"media/ldoce/hwd/ame/3/teach-in.mp3"},"oxford":{"phon":"ˈtiːtʃ ɪn","pos":"noun","senses":[{"en":"an informal lecture and discussion on a subject of public interest","cn":"（以公众关注的事情等为题的）宣讲会，座谈会"}]}},"tearoom":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a restaurant where tea and small meals are served 〔","cn":"供应茶和简餐的〕茶馆﹐茶室"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tearoom.mp3","us":"media/ldoce/hwd/ame/3/tearoom.mp3"}},"testy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"急躁的;没耐心的;易怒的","en":"If you describe someone as testy, you mean that they easily become impatient or angry.","ex":{"en":"Ben's getting a little testy in his old age.","cn":"上了年纪后本变得有点性急了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impatient and easily annoyed","cn":"不耐烦的﹔急躁的"}]},"vocab":{"pos":"adj","senses":[{"en":"You might feel a bit testy before taking a test, but test and testy are unrelated. Feeling testy is like being peeved, annoyed, or irritated."}]},"media":{"uk":"media/ldoce/hwd/bre/a/testy0205.mp3","us":"media/ldoce/hwd/ame/4/testy.mp3"},"examples":[{"en":"‘Leave me alone,’ she said testily. “","cn":"别管我。”她不耐烦地说。"},{"en":"‘Leave me alone,’ she said testily.","cn":""}],"oxford":{"phon":"ˈtesti","pos":"adjective","senses":[{"en":"easily annoyed; showing this","cn":"易怒的；暴躁的","ex":{"en":"There was a testy exchange of words.","cn":"双方进行了激烈的交锋。"}}]}},"telephonist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电话接线员;话务员","en":"A telephonist is someone who works at a telephone exchange or whose job is to answer the telephone for a business or other organization."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to connect telephone calls to people in a large organization","cn":"接线员﹐话务员"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41telephonist.mp3","us":"media/ldoce/hwd/ame/f/ld41telephonist.mp3"},"oxford":{"phon":"təˈlefənɪst","pos":"noun","senses":[{"en":"a person who works on the phone switchboard of a large company or organization, especially at a telephone exchange","cn":"电话员；接线员"}]}},"teeny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很小的;极小的","en":"If you describe something as teeny, you are emphasizing that it is very small.","ex":{"en":"...little teeny bugs","cn":"丁点儿大的虫子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very small","cn":"很小的﹐极小的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeteeny.mp3","us":"media/ldoce/hwd/ame/4/teeny.mp3"},"examples":[{"en":"teeny magazines","cn":"青少年杂志"},{"en":"I was just a teeny bit disappointed.","cn":"我只是稍微有点失望。"}],"oxford":{"phon":"ˈtiːni","pos":"adjective","senses":[{"en":"very small","cn":"很小的；极小的","ex":{"en":"a teeny-weeny insect","cn":"一种微小的昆虫"}},{"en":"connected with people between 13 and 19 years old","cn":"十几岁青少年的","ex":{"en":"teeny magazines","cn":"青少年杂志"}}]}},"tensile":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可伸展的;可拉长的","en":"You use tensile when you are talking about the amount of stress that materials such as wire, rope, and concrete can take without breaking; a technical term in engineering.","ex":{"en":"Certain materials can be manufactured with a high tensile strength.","cn":"有些材料可以制造成抗拉强度大的产品。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to be stretched without breaking","cn":"可伸展[拉长]的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective tensile to describe materials that can be shaped, such as the tensile clay that a potter crafts into a bowl or vase."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41tensile.mp3","us":"media/ldoce/hwd/ame/0/tensile.mp3"},"examples":[{"en":"the tensile strength of rope","cn":"绳索的抗拉强度"},{"en":"tensile cable","cn":"可伸延的电缆"}],"oxford":{"phon":"ˈtensaɪl","pos":"adjective","senses":[{"en":"used to describe the extent to which something can stretch without breaking","cn":"张力的；拉力的；抗张的","g":"[only before noun]","ex":{"en":"the tensile strength of rope","cn":"绳索的抗拉强度"}},{"en":"that can be drawn out or stretched","cn":"可拉长的；能伸长的；可延展的","ex":{"en":"tensile cable","cn":"可伸延的电缆"}}]}},"technically":{"collins":{"senses":[{"pos":"ADV 副词","cn":"严格说来;准确来说","en":"If something is technically the case, it is the case according to a strict interpretation of facts, laws, or rules, but may not be important or relevant in a particular situation.","ex":{"en":"Nude bathing is technically illegal but there are plenty of unspoilt beaches where no one would ever know","cn":"严格说来，裸泳是违法的，但在许多人迹罕至的海滩，没人会知道。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"according to the exact details of a rule or law","cn":"严格根据法律地﹔严格遵循规则地"},{"en":"concerning the special skills that are needed to play music, do a sport etc","cn":"技巧上﹔与技巧有关地"},{"en":"concerning the way machines are used to do work","cn":"在技术上﹔在工艺上"}]},"vocab":{"pos":"1 adv 2 adv","senses":[{"en":"Something technically true is actually, really true or correct but it may not be the way people think about it. For example, although people call a tomato a vegetable, technically , it’s a fruit."}]},"media":{"uk":"media/ldoce/hwd/bre/b/technically_las3_br.mp3","us":"media/ldoce/hwd/ame/c/laadtechnically.mp3"},"examples":[{"en":"In those days recording sound was not technically possible.","cn":"在那个时候，录音在技术上是不可能的。"},{"en":"It is still technically possible for them to win (= but it seems unlikely).","cn":"从理论上讲，他们仍有获胜的可能性。"}],"oxford":{"phon":"ˈteknɪkli","pos":"adverb","senses":[{"en":"according to the exact meaning, facts etc.","cn":"根据确切意义地；严格按照事实地","ex":{"en":"Technically (speaking), the two countries are still at war.","cn":"严格说来，这两国仍在交战。"}},{"en":"in a way that is connected with the skills needed for a particular job, sport, art, etc.","cn":"在专业上；在技巧上；在技艺上","ex":{"en":"As a musician, she is technically accomplished.","cn":"作为乐师，她演奏技艺精湛。"}},{"en":"in a way that is connected with the practical use of machines, methods, etc. in science and industry","cn":"在技术上；在技能上；在工艺上","ex":{"en":"a technically advanced society","cn":"科技先进的社会"}}]}},"tearful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(脸)有泪水的;(声音)带哭腔的","en":"If someone is tearful, their face or voice shows signs that they have been crying or that they want to cry.","ex":{"en":"She became very tearful when pressed to talk about it.","cn":"她被逼谈论此事时开始泪如雨下。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is tearful is crying a little, or almost crying","cn":"哭泣的﹔含泪的﹐快要哭的"}]},"vocab":{"pos":"adj","senses":[{"en":"Before you break out in a full-fledged cry — when you're wiping your eyes and blowing your nose, you're tearful."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound She sounded angry and tearful. | become, get He suddenly became very tearful. | leave sb Defeat left her t","ADV. very | almost I felt quite emotional?almost tearful. | a bit, a little, rather"]},"media":{"uk":"media/ldoce/hwd/bre/a/tearful0205.mp3","us":"media/ldoce/hwd/ame/b/tearful.mp3"},"examples":[{"en":"She suddenly became very tearful.","cn":"她突然痛哭流涕。"},{"en":"a tearful farewell","cn":"挥泪送别"}],"oxford":{"phon":"ˈtɪəfl","pos":"adjective","senses":[{"en":"crying, or about to cry","cn":"哭泣的；含泪的","ex":{"en":"She suddenly became very tearful.","cn":"她突然痛哭流涕。"}},{"en":"at which people feel emotional and cry","cn":"令人伤心的；催人泪下的","ex":{"en":"a tearful farewell","cn":"挥泪送别"}}]}},"teaspoonful":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一茶匙的量","en":"You can refer to an amount of food resting on a teaspoon as a teaspoonful of food.","ex":{"en":"...a heaped teaspoonful of salt.","cn":"满满一茶匙的盐"}}]}},"telepathy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"传心术;读心术;心灵感应","en":"If you refer to telepathy, you mean the direct communication of thoughts and feelings between people's minds, without the need to use speech, writing, or any other normal signals.","ex":{"en":"Many of us find it very difficult to state our needs. We expect people to know by telepathy what we are feeling.","cn":"我们许多人感觉很难用语言表达自己的需求，希望别人能通过心灵感应了解我们的感受。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of communicating in which thoughts are sent from one person’s mind to another person’s mind","cn":"传心术﹐心灵感应"}]},"vocab":{"pos":"n","senses":[{"en":"That thing that happens when somehow you know in your head exactly what your brother wants for dinner even though he hasn’t said a word? That could be telepathy , communication that involves none of the known senses."}]},"media":{"uk":"media/ldoce/hwd/bre/d/telepathy0205.mp3","us":"media/ldoce/hwd/ame/c/telepathy.mp3"},"oxford":{"phon":"təˈlepəθi","pos":"noun","senses":[{"en":"the direct communication of thoughts or feelings from one person to another without using speech, writing, or any other normal method","cn":"传心术；通灵术；心灵感应"}]}},"terrorist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"恐怖主义分子","en":"A terrorist is a person who uses violence, especially murder and bombing, in order to achieve political aims.","ex":{"en":"One American was killed and three were wounded in terrorist attacks.","cn":"在几起恐怖袭击中，一名美国人遇难，三人受伤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who uses violence such as bombing, shooting etc to obtain political demands","cn":"恐怖分子"}]},"vocab":{"pos":"n","senses":[{"en":"Someone who uses violence, mayhem, and destruction — or the threat of those things — to coerce people or countries into taking a certain action is a terrorist . A terrorist may be motivated by religious fervor, politics, or just plain old-fashioned greed."}]},"collocations":{"phrases":["ADJ. suspected | armed | international The bomb attacks have been attributed to a group of international terrorists. | republican, right-win","TERRORIST + NOUN band, faction, gang, group, organization, unit | act, action, activity, atrocity, attack, bomb, bombing, campaign, explosio"]},"media":{"uk":"media/ldoce/hwd/bre/3/terrorist0205.mp3","us":"media/ldoce/hwd/ame/d/terrorist.mp3"},"examples":[{"en":"The terrorists are threatening to blow up the plane.","cn":"恐怖分子扬言要炸毁飞机。"},{"en":"a terrorist attack/bomb/group","cn":"恐怖分子的袭击/炸弹/团体"}],"oxford":{"phon":"ˈterərɪst","pos":"noun","senses":[{"en":"a person who takes part in terrorism","cn":"恐怖主义者；恐怖分子","ex":{"en":"The terrorists are threatening to blow up the plane.","cn":"恐怖分子扬言要炸毁飞机。"}}]}},"teetotaller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不喝酒的人;滴酒不沾的人","en":"A teetotaller is someone who does not drink alcohol.","ex":{"en":"He is a strict teetotaller.","cn":"他绝对滴酒不沾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who never drinks anything containing alcohol, often for religious or moral reasons","cn":""},{"en":"to not drink even a little of anything alcoholic, usually because you have decided to stop drinking alcohol","cn":""},{"en":"someone who never drinks alcohol","cn":"滴酒不沾的人"}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeteetotaller.mp3","us":"media/ldoce/hwd/ame/8/teetotaler.mp3"},"oxford":{"phon":"ˌtiːˈtəʊtlə(r)","pos":"noun","senses":[{"en":"a person who does not drink alcohol","cn":"不饮酒的人；滴酒不沾的人","ex":{"en":"She’s a strict teetotaller.","cn":"她是一个严格滴酒不沾的人。"}}]}},"ted":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 Teddy boy","en":"A Ted is the same as a Teddy boy ."}]},"oxford":{"phon":"ted","pos":"","senses":[{"en":"a first name for boys, short for Edward, Edmund or Edwin","cn":"泰德（男子名，Edward，Edmund 或 Edwin缩写）"}]}},"tern":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"燕鸥","en":"A tern is a small black and white seabird with long wings and a forked tail."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a black and white sea bird that has long wings and a tail with two points","cn":"燕鸥〔一种海鸟〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tern.mp3","us":"media/ldoce/hwd/ame/6/tern.mp3"},"oxford":{"phon":"tɜːn","pos":"noun","senses":[{"en":"a bird with long pointed wings and a tail with two points that lives near the sea","cn":"燕鸥"}]}},"testimonial":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常由雇主出具的、证明某人品格和能力的)推荐信，证明书","en":"A testimonial is a written statement about a person's character and abilities, often written by their employer.","ex":{"en":"She could hardly expect her employer to provide her with testimonials to her character and ability.","cn":"她可不敢指望雇主给她出具关于她品格和能力的证明书。"}},{"pos":"N-COUNT 可数名词","cn":"(部分票款捐给某运动员或其家人的)纪念赛，义捐比赛","en":"A testimonial is a sports match which is specially arranged so that part of the profit from the tickets sold can be given to a particular player or to a particular player's family."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a formal written statement describing someone’s character and abilities 〔","cn":"介绍描述某人品格和能力的〕证明书﹐推荐信"},{"en":"something that is given or done to someone to thank or praise them, or show admiration for them","cn":"感谢信﹔表扬信﹔奖状﹔奖励"}]},"vocab":{"pos":"n adj","senses":[{"en":"A testimonial is like a personal recommendation. If you give a testimonial on behalf of a restaurant, then you really like that restaurant."}]},"media":{"uk":"media/ldoce/hwd/bre/1/testimonial0205.mp3","us":"media/ldoce/hwd/ame/d/testimonial.mp3"},"examples":[{"en":"The catalogue is full of testimonials from satisfied customers.","cn":"这份商品目录满篇皆是称心顾客的赞辞。"},{"en":"a testimonial game (= to raise money for a particular player)","cn":"纪念赛（为某位运动员筹款）"}],"oxford":{"phon":"ˌtestɪˈməʊniəl","pos":"noun","senses":[{"en":"a formal written statement, often by a former employer, about somebody’s abilities, qualities and character; a formal written statement about the quality of something","cn":"证明信；介绍信；推荐信","ex":{"en":"a glowing testimonial","cn":"充满赞誉的推荐信"}},{"en":"a thing that you give or do to show that you admire and appreciate somebody","cn":"感谢信；纪念品；奖品；奖状","ex":{"en":"a testimonial game (= to raise money for a particular player)","cn":"纪念赛（为某位运动员筹款）"}}]}},"teacake":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茶点心","en":"Teacakes are round flat bread cakes. They usually contain raisins and are often toasted and eaten with butter."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small flat round amount of bread with raisin s or currant s in it","cn":"茶点心〔一种含葡萄干的扁平圆形小面包〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41teacake.mp3","us":"media/ldoce/hwd/ame/1/ld41teacake.mp3"},"examples":[{"en":"toasted teacakes","cn":"烘烤的茶点饼"}],"oxford":{"phon":"ˈtiːkeɪk","pos":"noun","senses":[{"en":"a small, flat, round cake made of a bread-like mixture, usually containing dried fruit","cn":"茶点饼（扁平状，常含有果干）","ex":{"en":"toasted teacakes","cn":"烘烤的茶点饼"}}]}},"tentacle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(章鱼等的)触须，触手，触角","en":"The tentacles of an animal such as an octopus are the long thin parts that are used for feeling and holding things, for getting food, and for moving."},{"pos":"N-COUNT 可数名词","cn":"(政治、商业、社会等机构的)影响力，触角","en":"If you talk about the tentacles of a political, commercial, or social organization, you are referring to the power and influence that it has in the outside community.","ex":{"en":"Free speech is being gradually eroded year after year by new tentacles of government control.","cn":"言论自由正在一年又一年逐渐被政府不断施加的影响力所削弱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the long thin parts of a sea creature such as an octopus which it uses for holding things 〔","cn":"章鱼等海洋动物的〕触手﹐触角﹐触须"},{"en":"the influence or effect that something has on other people or things – used to show disapproval","cn":"影响力﹔控制力〔含贬义〕"}]},"vocab":{"pos":"n","senses":[{"en":"A tentacle is long, ropey thing that sticks out of an animal’s face. You probably think they’re gross. Octopuses probably think they’re cute."}]},"media":{"uk":"media/ldoce/hwd/bre/9/tentacle0205.mp3","us":"media/ldoce/hwd/ame/a/tentacle.mp3"},"examples":[{"en":"The tentacles of satellite television are spreading even wider.","cn":"卫星电视的影响正日益扩大。"},{"en":"( figurative ) Tentacles of fear closed around her body.","cn":"恐惧的阴影笼罩着她。"}],"oxford":{"phon":"ˈtentəkl","pos":"noun","senses":[{"en":"a long, thin part of the body of some creatures, such as squid, used for feeling or holding things, for moving or for getting food","cn":"触角；触手；触须","g":"[countable]"},{"en":"the influence that a large place, organization or system has and that is hard to avoid","cn":"（大的地方、组织或系统难以避免的）影响，束缚，约束","g":"[plural]","lab":"usually disapproving","ex":{"en":"The tentacles of satellite television are spreading even wider.","cn":"卫星电视的影响正日益扩大。"}}]}},"tenable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(论点、观点或立场)有道理的，站得住脚的","en":"If you say that an argument, point of view, or situation is tenable, you believe that it is reasonable and could be successfully defended against criticism.","ex":{"en":"This argument is simply not tenable","cn":"这个论点根本站不住脚。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a belief, argument etc that is tenable is reasonable and can be defended successfully 〔","cn":"信仰﹑论点等〕有道理的﹐站得住脚的"}]},"vocab":{"pos":"adj","senses":[{"en":"If your teacher says your position on the benefits of abolishing homework is not tenable , she means it is not based in fact. To be tenable is to be evidence-based and well-founded."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41tenable.mp3","us":"media/ldoce/hwd/ame/7/tenable.mp3"},"examples":[{"en":"The old idea that this work was not suitable for women was no longer tenable.","cn":"这种工作不适合妇女的旧想法再也站不住脚了。"},{"en":"The lectureship is tenable for a period of three years.","cn":"讲师这一职务任期三年。"}],"oxford":{"phon":"ˈtenəbl","pos":"adjective","senses":[{"en":"easy to defend against attack or criticism","cn":"说得过去的；站得住脚的","ex":{"en":"a tenable position","cn":"说得过去的观点"}},{"en":"that can be held for a particular period of time","cn":"可保有，可保持，可担任（一段时间）","g":"[not before noun]","ex":{"en":"The lectureship is tenable for a period of three years.","cn":"讲师这一职务任期三年。"}}]}},"tendon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(连结肌肉和骨骼的)腱，肌腱","en":"A tendon is a strong cord in a person's or animal's body which joins a muscle to a bone."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick strong string-like part of your body that connects a muscle to a bone","cn":"腱"}]},"vocab":{"pos":"n","senses":[{"en":"If you feel the back of your ankle, you will find the tough, ropelike tendon that joins your calf muscle to your heel bone. That's the job of tendons throughout your body: connecting bone and muscle so you can move."}]},"collocations":{"phrases":["ADJ. damaged, severed | Achilles","VERB + TENDON pull, sever, tear","TENDON + NOUN injury, trouble | operation, repair"]},"media":{"uk":"media/ldoce/hwd/bre/9/tendon0205.mp3","us":"media/ldoce/hwd/ame/f/tendon.mp3"},"oxford":{"phon":"ˈtendən","pos":"noun","senses":[{"en":"a strong band of tissue in the body that joins a muscle to a bone","cn":"腱","lab":"especially British English","ex":{"en":"He had surgery for a torn tendon in his elbow.","cn":"他因肘部一处肌腱撕裂动了手术。"}}]}},"tee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(高尔夫运动中用来放置球的)球座","en":"In golf, a tee is a small piece of wood or plastic which is used to support the ball before it is hit at the start of each hole."},{"pos":"N-COUNT 可数名词","cn":"(高尔夫运动中的)开球区，发球区","en":"On a golf course, a tee is one of the small flat areas of ground from which people hit the ball at the start of each hole."},{"pos":"","cn":"","en":"to a tee→see: ;"},{"pos":"","cn":"","en":"相关词组：tee off tee up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small object that you use in a game of golf to hold the ball above the ground before you hit it 〔","cn":"高尔夫球运动中用来放置球的〕球座"},{"en":"the place where you first hit the ball towards each hole in a game of golf 〔","cn":"高尔夫球运动中的〕开球区﹐发球区"},{"en":"another word for T-shirt T-shirt","cn":"的另一种说法"}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdetee.mp3","us":"media/ldoce/hwd/ame/0/t__t.mp3"},"examples":[{"en":"to drive off from the first tee","cn":"从第一发球区开球"},{"en":"a tee shot","cn":"开球处击球"}],"oxford":{"phon":"tiː","pos":"noun","senses":[{"en":"a flat area on a golf course from which players hit the ball","cn":"（高尔夫球场的）发球区，开球处","ex":{"en":"to drive off from the first tee","cn":"从第一发球区开球"}},{"en":"a small piece of plastic or wood that you stick in the ground to support a golf ball before you hit it","cn":"（高尔夫球）球座"},{"en":"a T-shirt","cn":"（用以表示完全合适）恰好，丝毫不差","lab":"informal","ex":{"en":"She wore jeans and a plain white tee.","cn":"她穿着牛仔裤和纯白 T 恤。"}}]}},"termite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"白蚁","en":"Termites are small white insects which live in hot countries in homes made of earth. Termites do a lot of damage by eating wood."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an insect that eats and destroys wood from trees and buildings","cn":"白蚁"}]},"media":{"uk":"media/ldoce/hwd/bre/d/termite0205.mp3","us":"media/ldoce/hwd/ame/6/termite.mp3"},"examples":[{"en":"a termite colony","cn":"白蚁群"}],"oxford":{"phon":"ˈtɜːmaɪt","pos":"noun","senses":[{"en":"an insect that lives in organized groups, mainly in hot countries. Termites do a lot of damage by eating the wood of trees and buildings.","cn":"白蚁","ex":{"en":"a termite colony","cn":"白蚁群"}}]}},"tepid":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(水等液体)微温的，微热的","en":"Water or another liquid that is tepid is slightly warm.","ex":{"en":"She bent her mouth to the tap and drank the tepid water.","cn":"她把嘴伸到水龙头底下去喝那微温的水。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情、反应等)冷淡的，不够热情的","en":"If you describe something such as a feeling or reaction as tepid, you mean that it lacks enthusiasm.","ex":{"en":"His nomination, while strongly backed by the President, has received tepid support in the Senate.","cn":"尽管他的提名得到总统的大力支持，但支持他的参议员却寥寥无几。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a little hot, but not very hot, especially in a way that is pleasant","cn":""},{"en":"food or drinks that are lukewarm are slightly warm and not as warm or cold as they should be","cn":""},{"en":"liquid that is tepid is only slightly warm, especially in a way that seems unpleasant","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Tepid means lukewarm or half-hearted. If the applause for your mime-on-a-unicycle performance was more tepid than enthusiastic, it might be time to find a new hobby."}]},"media":{"uk":"media/ldoce/hwd/bre/f/tepid0205.mp3","us":"media/ldoce/hwd/ame/9/tepid.mp3"},"examples":[{"en":"The play was greeted with tepid applause.","cn":"这台戏只得到了零落的掌声。"},{"en":"tepid tea","cn":"温吞的茶"}],"oxford":{"phon":"ˈtepɪd","pos":"adjective","senses":[{"en":"slightly warm, sometimes in a way that is not pleasant","cn":"不冷不热的；微温的；温吞的","ex":{"en":"tepid tea","cn":"温吞的茶"}},{"en":"not enthusiastic","cn":"不热情的；不热烈的","ex":{"en":"The play was greeted with tepid applause.","cn":"这台戏只得到了零落的掌声。"}}]}},"testament":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"证据;证明","en":"If one thing is a testament to another, it shows that the other thing exists or is true.","ex":{"en":"Braka's house, just off Sloane Square, is a testament to his Gothic tastes","cn":"布拉卡那幢紧靠斯隆广场的房子是他喜好哥特式建筑的一个证据。"}},{"pos":"PHRASE 短语","cn":"最新遗嘱;（尤指）临终遗嘱,临终遗言","en":"Someone's last will and testament is the most recent will that they have made, especially the last will that they make before they die."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to show very clearly that someone has good qualities, though those qualities are not always named","cn":""},{"en":"if a fact or achievement is a tribute to someone or something, it shows their good qualities because it is a result of those qualities","cn":""},{"en":"if an action or event reflects well on a person or organization, it shows that they have good qualities or abilities, and this makes people's opinion of them improve","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A testament is a statement of belief. The most famous testaments are the two parts of the Christian Bible: the Old and New Testaments ."}]},"collocations":{"phrases":["ADJ. fine, fitting, worthy","VERB + TESTAMENT bear The immaculate state of the garden bears testament to a lifetime's effort.","PREP. ~ to The monument is a worthy testament to the courage of the men who fought in the war."]},"media":{"uk":"media/ldoce/hwd/bre/d/testament0205.mp3","us":"media/ldoce/hwd/ame/a/testament.mp3"},"examples":[{"en":"The new model is a testament to the skill and dedication of the workforce.","cn":"这种新型产品显示了全体员工的技术水平和敬业精神。"},{"en":"This is the last will and testament of …","cn":"这是 … 的临终遗嘱"}],"oxford":{"phon":"ˈtestəmənt","pos":"noun","senses":[{"en":"a thing that shows that something else exists or is true","cn":"证据；证明","g":"[countable, usually singular, uncountable]","ex":{"en":"The new model is a testament to the skill and dedication of the workforce.","cn":"这种新型产品显示了全体员工的技术水平和敬业精神。"}},{"en":"a legal document that says what is to happen to somebody’s money and property after they die","cn":"遗嘱","g":"[countable]","ex":{"en":"This is the last will and testament of…","cn":"这是…的临终遗嘱。"}}]}},"terminology":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"学科术语;专门用语","en":"The terminology of a subject is the set of special words and expressions used in connection with it.","ex":{"en":"...gastritis, which in medical terminology means an inflammation of the stomach.","cn":"胃炎是一个医学术语，意思是胃部炎症"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a form of a language that is spoken in one area of a country, with different words, grammar, or pronunciation from other areas","cn":""},{"en":"the way that someone pronounces words, because of where they were born or live, or their social class","cn":""},{"en":"very informal spoken language, used especially by people who belong to a particular group, for example young people or criminals","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Terminology is vocabulary associated with a certain field of study, profession, or activity. Knowing the terminology is an important part of being able to work in a given profession."}]},"collocations":{"phrases":["ADJ. modern | specialist, specialized, technical | computer, legal, medical, scientific, etc.","VERB + TERMINOLOGY use The article uses rather specialized musical terminology. | borrow | standardize","PREP. in &hellip; ~ The outer walls, in building terminology, are &lsquo;double skin&rsquo;."]},"media":{"uk":"media/ldoce/hwd/bre/f/terminology0205.mp3","us":"media/ldoce/hwd/ame/c/terminology.mp3"},"examples":[{"en":"The disagreement arose over a different use of terminology.","cn":"分歧的缘起在于专门用语使用的不同。"},{"en":"medical terminology","cn":"医学术语"}],"oxford":{"phon":"ˌtɜːmɪˈnɒlədʒi","pos":"noun","senses":[{"en":"the set of technical words or expressions used in a particular subject","cn":"（某学科的）术语","ex":{"en":"The article avoids using too much medical terminology.","cn":"这篇文章避免使用过多的医学术语。"}}]}},"televise":{"collins":{"senses":[{"pos":"VERB 动词","cn":"通过电视播放","en":"If an event or programme is televised, it is broadcast so that it can be seen on television.","ex":{"en":"The Grand Prix will be televised by the BBC.","cn":"汽车大奖赛将由英国广播公司进行电视转播。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a programme is on , it is being broadcast and you can watch it on television or listen to it on the radio","cn":""},{"en":"if a television company shows a particular programme, it makes the programme available for people to watch","cn":""},{"en":"if a television or radio company broadcasts a programme, they send it out so that people can watch it on television or listen to it on the radio","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"You're most likely to televise something if you work at a TV station — to televise is to transmit or broadcast on a television."}]},"collocations":{"phrases":["ADV. nationally a nationally televised debate | live"]},"media":{"uk":"media/ldoce/hwd/bre/8/televise0205.mp3","us":"media/ldoce/hwd/ame/3/televise.mp3"},"examples":[{"en":"The speech will be televised live.","cn":"这次演讲将由电视直播。"},{"en":"a televised debate","cn":"电视播送的辩论"}],"oxford":{"phon":"ˈtelɪvaɪz","pos":"verb","senses":[{"en":"to broadcast something on television","cn":"作电视广播；在电视上播送","ex":{"en":"a televised debate","cn":"电视播送的辩论"}}]}},"tenuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(联系)脆弱的;(理由)站不住脚的，牵强的;(地位)不稳固的","en":"If you describe something such as a connection, a reason, or someone's position as tenuous, you mean that it is very uncertain or weak.","ex":{"en":"The cultural and historical links between the many provinces were seen to be very tenuous","cn":"许多省份之间的文化和历史纽带被认为是很脆弱的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a situation or relationship that is tenuous is uncertain, weak, or likely to change","cn":"缥缈的﹔脆弱的﹔不确定的"},{"en":"very thin and easily broken","cn":"纤细的﹔易碎的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is tenuous it's thin, either literally or metaphorically. If you try to learn a complicated mathematical concept by cramming for 45 minutes, you will have a tenuous grasp of that concept, at best."}]},"media":{"uk":"media/ldoce/hwd/bre/e/tenuous0205.mp3","us":"media/ldoce/hwd/ame/4/tenuous.mp3"},"examples":[{"en":"His links with the organization turned out to be, at best, tenuous.","cn":"最后证实他与这个组织的关系充其量不过是不即不离罢了。"},{"en":"a tenuous hold on life","cn":"命若游丝"}],"oxford":{"phon":"ˈtenjuəs","pos":"adjective","senses":[{"en":"so weak or uncertain that it hardly exists","cn":"脆弱的；微弱的；缥缈的","ex":{"en":"a tenuous hold on life","cn":"命若游丝"}},{"en":"extremely thin and easily broken","cn":"纤细的；薄的；易断的","ex":{"en":"the tenuous threads of a spider’s web","cn":"蜘蛛网的细丝。"}}]}},"telemarketing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电话销售;电话推销","en":"Telemarketing is a method of selling in which someone employed by a company telephones people to try and persuade them to buy the company's products or services."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of selling products to people in which you telephone people to see if they want to buy something","cn":"电话推销"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41telemarketing.mp3","us":"media/ldoce/hwd/ame/c/telemarketing.mp3"},"oxford":{"phon":"ˈtelimɑːkɪtɪŋ","pos":"noun","senses":[{"en":"a method of selling things and taking orders for sales by phone","cn":"电话销售；电话推销"}]}},"temperance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"戒酒;禁酒","en":"If you believe in temperance, you disapprove of drinking alcohol.","ex":{"en":"...a reformed alcoholic extolling the joys of temperance.","cn":"对戒酒的好处赞不绝口的已成功戒酒的酒徒"}},{"pos":"N-UNCOUNT 不可数名词","cn":"节制;有分寸;自我克制","en":"A person who shows temperance has a strong mind and does not eat too much, drink too much, or do too much of anything.","ex":{"en":"The age of hedonism is being ushered out by a new era of temperance.","cn":"享乐主义时代正让位于一个注重节制的时代。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone never drinks alcohol because of their moral or religious beliefs 〔","cn":"出于道德或宗教原因的〕戒酒﹐禁酒"},{"en":"sensible control of the things you say and do, especially the amount of alcohol you drink 〔","cn":"尤指对饮酒的〕自我克制﹐节制"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Temperance means restraint and moderation, but if you're talking about alcohol, temperance means not just drinking in moderation, it means not having it at all."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41temperance.mp3","us":"media/ldoce/hwd/ame/4/temperance.mp3"},"oxford":{"phon":"ˈtempərəns","pos":"noun","senses":[{"en":"the practice of not drinking alcohol because of your moral or religious beliefs","cn":"（由于道德或宗教信仰而实行的）戒酒，禁酒，滴酒不沾","lab":"old-fashioned","ex":{"en":"The temperance movement was at its peak at the end of the 19th century.","cn":"十九世纪末，禁酒运动达到顶峰。"}},{"en":"the practice of controlling your behaviour, the amount you eat, etc., so that it is always reasonable","cn":"自我克制；克己；节欲；节食","lab":"formal"}]}},"tenderize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(采用特殊方法)将(肉)烹制得软嫩","en":"If you tenderize meat, you make it softer by preparing it in a particular way.","ex":{"en":"Wine vinegar tenderises meat.","cn":"酒醋能让肉变嫩。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make meat softer and easier to eat by preparing it in a special way 〔","cn":"通过特殊处理〕使〔肉〕软嫩"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41tenderize.mp3","us":"media/ldoce/hwd/ame/9/tenderize.mp3"},"oxford":{"phon":"ˈtendəraɪz","pos":"verb","senses":[{"en":"to make meat softer and easier to cut and eat by preparing it in a particular way","cn":"使（肉）变嫩；使（肉）变软"}]}},"teutonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"典型德国人的;日耳曼人所独具的","en":"Teutonic means typical of or relating to German people.","ex":{"en":"There was sweat pouring over her Teutonic face","cn":"汗水顺着她那张典型的德国人的脸往下淌。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having qualities that are thought to be typical of German people","cn":"日耳曼人作风的﹔典型德国人风格的"},{"en":"relating to the ancient German peoples of northwest Europe 〔","cn":"古代西北欧的〕条顿人的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41teutonic.mp3","us":"media/ldoce/hwd/ame/2/teutonic.mp3"},"examples":[{"en":"The preparations were made with Teutonic thoroughness.","cn":"各项准备工作均以日耳曼人缜密的精神完成。"},{"en":"Teutonic efficiency","cn":"日耳曼人的效率"}],"oxford":{"phon":"tjuːˈtɒnɪk","pos":"adjective","senses":[{"en":"showing qualities considered typical of German people","cn":"德意志民族特点的；日耳曼人风格的；条顿的","ex":{"en":"The preparations were made with Teutonic thoroughness.","cn":"各项准备工作均以日耳曼人缜密的精神完成。"}}]}},"tenant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"承租人;租户;房客","en":"A tenant is someone who pays rent for the place they live in, or for land or buildings that they use.","ex":{"en":"Regulations placed clear obligations on the landlord for the benefit of the tenant","cn":"为维护房客的利益，条例明确规定了房东负有的各项义务。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a country or town or area, or the number of people who live in it","cn":""},{"en":"someone who lives in a particular area of a town, a particular street or building etc","cn":""},{"en":"one of the people who live in a place, especially in a town or city or in an area of a country","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A tenant is someone who lives in a place owned by someone else, usually paying rent. If you play your music loud and let the cat pee in the corner, your landlord will not think that you're a very good tenant ."}]},"collocations":{"phrases":["ADJ. current, existing, sitting the sale of council houses to sitting tenants | life | protected, secure | joint | potential, prospective | ","VERB + TENANT find | evict","TENANT + VERB occupy sth The property is currently occupied by a life tenant.","TENANT + NOUN farmer","PHRASES landlord and tenant conflicts that might arise between landlord and tenant"]},"media":{"uk":"media/ldoce/hwd/bre/7/tenant0205.mp3","us":"media/ldoce/hwd/ame/d/tenant.mp3"},"examples":[{"en":"They had evicted their tenants for non-payment of rent.","cn":"他们赶走了未交房租的房客。"},{"en":"The decorating was done by a previous tenant.","cn":"装修是一位前房客搞的。"}],"oxford":{"phon":"ˈtenənt","pos":"noun","senses":[{"en":"a person who pays rent for the use of a room, building, land, etc. to the person who owns it","cn":"房客；租户；佃户","lab":"especially North American English","ex":{"en":"They had evicted their tenants for non-payment of rent.","cn":"他们赶走了未交房租的房客。"}},{"en":"to live or work in a place as a tenant","cn":"（作为租赁者）居住，工作","ex":{"en":"a tenanted farm","cn":"租种的农场"},"pos":"verb"}]}},"terrify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"吓坏;使极度恐慌;使非常害怕","en":"If something terrifies you, it makes you feel extremely frightened.","ex":{"en":"Flying terrifies him","cn":"坐飞机让他害怕得要命。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel afraid","cn":""},{"en":"to frighten someone. Scare is less formal than frighten , and is the usual word to use in everyday English","cn":""},{"en":"to make someone feel extremely frightened","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you terrify someone, that person is enormously frightened of you."}]},"media":{"uk":"media/ldoce/hwd/bre/3/terrify0205.mp3","us":"media/ldoce/hwd/ame/d/terrify.mp3"},"examples":[{"en":"It was a terrifying experience.","cn":"那是一次可怕的经历。"},{"en":"Flying terrifies her.","cn":"她害怕坐飞机。"}],"oxford":{"phon":"ˈterɪfaɪ","pos":"verb","senses":[{"en":"to make somebody feel extremely frightened","cn":"使恐惧；使十分害怕；使惊恐","ex":{"en":"Flying terrifies her.","cn":"她害怕坐飞机。"}}]}},"telescopic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(镜头、仪器)能望远的，望远镜的","en":"Telescopic lenses and instruments are used to make things seem larger and nearer, and are usually longer than others of the same type.","ex":{"en":"...a sporting rifle fitted with a telescopic sight.","cn":"安装了望远镜瞄准器的猎枪"}},{"pos":"ADJ 形容词","cn":"能伸缩的;套叠式的","en":"A telescopic object is made of cylindrical sections that fit or slide into each other, so that it can be made longer or shorter, for example to save space when it is not being used.","ex":{"en":"...this new lightweight telescopic ladder.","cn":"这把新型的伸缩式轻便梯子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made of parts that slide over each other so that the whole thing can be made longer or shorter","cn":"可伸缩的﹔套叠式的"},{"en":"making distant things look bigger, like a telescope does","cn":"能望到远处的﹔似望远镜的"},{"en":"done using a telescope","cn":"借助望远镜的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41telescopic.mp3","us":"media/ldoce/hwd/ame/6/telescopic.mp3"},"examples":[{"en":"a rifle with a telescopic sight","cn":"装有望远瞄准器的步枪"},{"en":"a telescopic aerial","cn":"可伸缩天线"}],"oxford":{"phon":"ˌtelɪˈskɒpɪk","pos":"adjective","senses":[{"en":"connected with or using a telescope; making things look larger as a telescope does","cn":"望远镜的；望远的；放大的","ex":{"en":"a rifle with a telescopic sight","cn":"装有望远瞄准器的步枪"}},{"en":"made of sections that can slide into each other to make the object longer or shorter","cn":"可伸缩的；套叠的；套筒的","ex":{"en":"a telescopic aerial","cn":"可伸缩天线"}}]}},"techno":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"高科技舞曲(一种快节奏的现代电子音乐)","en":"Techno is a form of modern electronic music with a very fast beat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of popular electronic dance music with a fast strong beat","cn":"泰克诺音乐﹐高科技舞曲〔一种节奏快而强劲的电子舞蹈音乐〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/techno0205.mp3","us":"media/ldoce/hwd/ame/9/laadtechno.mp3"},"oxford":{"phon":"ˈteknəʊ","pos":"noun","senses":[{"en":"a type of fast, electronic dance music, typically with little or no singing","cn":"泰克诺音乐，电子音乐（一种节奏快、通常无歌声相伴的电子舞曲）"},{"en":"connected with technology","cn":"技术的；工艺的；工艺技术的","ex":{"en":"technophobe (= a person who is afraid of technology)","cn":"科技恐惧者"},"pos":"combining form"}]}},"teflon":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"特氟龙，聚四氟乙烯(一种防粘锅的涂料)","en":"Teflon is a type of plastic which is often used to coat pans. Teflon provides a very smooth surface which food does not stick to, so the pan can be cleaned easily."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plastic that stops things from sticking to it, used on the inside of pans to stop food sticking to the pan 〔","cn":"炊具的〕特富龙不粘涂料"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41teflon.mp3","us":"media/ldoce/hwd/ame/b/teflon.mp3"},"examples":[{"en":"The Teflon Prime Minister has survived another crisis.","cn":"不倒翁首相又挺过了一次危机。"}],"oxford":{"phon":"ˈteflɒn","pos":"noun","senses":[{"en":"a substance used especially to cover the inside of cooking pans, that stops food from sticking to them","cn":"特氟隆，聚四氟乙烯（不粘锅涂层材料）"},{"en":"still having a good reputation after making a mistake or doing something that is not legal","cn":"扳不倒的（犯错误或违法后声誉不受损）","ex":{"en":"The Teflon Prime Minister has survived another crisis.","cn":"不倒翁首相又挺过了一次危机。"},"pos":"adjective"}]}},"telepathic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"会传心术的;有读心能力的;能心灵感应的","en":"If you believe that someone is telepathic, you believe that they have mental powers which cannot be explained by science, such as being able to communicate with other people's minds, and know what other people are thinking.","ex":{"en":"About half the subjects considered themselves to be telepathic","cn":"实验对象中有一半左右自认为有心灵感应能力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is telepathic has a mysterious ability to know what other people are thinking","cn":"有心灵感应能力的"},{"en":"a telepathic message is sent from one person to another by using thoughts, not by talking or writing","cn":"以心灵感应术传送的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you can read your brother's mind, you can describe yourself as telepathic , or able to communicate psychically."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41telepathic.mp3","us":"media/ldoce/hwd/ame/6/telepathic.mp3"},"examples":[{"en":"How do I know what he's thinking? I'm not telepathic!","cn":"我怎么知道他在想什么？我又不会传心术！"},{"en":"telepathic communication","cn":"心灵感应交流"}],"oxford":{"phon":"ˌtelɪˈpæθɪk","pos":"adjective","senses":[{"en":"using telepathy","cn":"用传心术的；心灵感应的","ex":{"en":"telepathic communication","cn":"心灵感应交流"}},{"en":"able to communicate by telepathy","cn":"会传心术的；有心灵感应的","ex":{"en":"How do I know what he's thinking? I'm not telepathic!","cn":"我怎么知道他在想什么？我又不会传心术！"}}]}},"testicular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"睾丸的","en":"Testicular means relating to or involving the testicles.","ex":{"en":"...testicular cancer.","cn":"睾丸癌"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two round organs that produce sperm in a male, that are enclosed in a bag of skin behind and below the penis","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/testicle0205.mp3","us":"media/ldoce/hwd/ame/6/testicle.mp3"},"examples":[{"en":"testicular cancer","cn":"睾丸癌"}],"oxford":{"phon":"teˈstɪkjələ(r)","pos":"adjective","senses":[{"en":"connected with the testicles","cn":"睾丸：与睾丸相连","ex":{"en":"testicular cancer","cn":"睾丸癌"}}]}},"technicolor":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(制作电影的)彩色印片法","en":"Technicolor is a system of colour photography used in making cinema films.","ex":{"en":"...films in Technicolor.","cn":"彩色影片"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤用作夸张）五彩缤纷，色彩斑斓","en":"You can use technicolor to describe real or imagined scenes when you want to emphasize that they are very colourful, especially in an exaggerated way.","ex":{"en":"I was seeing it all in glorious technicolour: mountains, valleys, lakes, summer sunshine.","cn":"我所看见的一切——大山、山谷、湖泊和夏日的阳光全都绚丽多彩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of producing the colour in films, used for the cinema","cn":"特艺色染印法〔彩色电影的一种制作方法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41technicolor.mp3","us":"media/ldoce/hwd/ame/1/technicolor.mp3"},"oxford":{"phon":"ˈteknɪkʌlə(r)","pos":"noun","senses":[{"en":"a process of producing colour film, as used in cinema films","cn":"特艺色彩色电影印片法"}]}},"tel":{"ldoce":{"phon":"","pos":"","senses":[{"en":"the written abbreviation of telephone number","cn":"电话号码"}]},"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"telephone number","cn":"电话号码"}]}}});
